CREATE OR REPLACE FUNCTION "public"."apply_completion_change"("p_operation" "text", "p_completion_id" "uuid" DEFAULT NULL::"uuid", "p_expected_revision" bigint DEFAULT NULL::bigint, "p_completion" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."completion_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_timezone text;
  v_completion_id uuid;
  v_revision bigint;
  v_plan_session_id uuid;
  v_snapshot jsonb;
  v_activity jsonb;
  v_constraint text;
  v_title text;
  v_sport text;
  v_replaced_by uuid;
  v_replacement public.completion_receipt;
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  if p_operation is null or p_operation not in ('create', 'edit', 'delete')
    -- Delete (ADR-031) carries no content: it names a log and the revision
    -- read, and nothing else.
    or (p_operation = 'delete' and p_completion is not null)
    or (p_operation <> 'delete'
      and not public.completion_input_is_valid(p_completion, p_operation))
  then
    raise exception using errcode = '22023', message = 'Invalid completion change.';
  end if;

  -- What a replaced log points at. Written first when it is new: the
  -- recursive create is the same function under the same owner, so every rule
  -- unplanned training answers to is applied to it unchanged, and if anything
  -- after it fails the whole call rolls back and neither log exists.
  if p_completion ? 'replacement' then
    v_replacement := public.apply_completion_change(
      'create', null, null,
      (p_completion->'replacement') || pg_catalog.jsonb_build_object(
        'status', 'unplanned',
        'actualLocalDate', p_completion->'actualLocalDate',
        'painReported', false,
        'illnessReported', false,
        'injuryReported', false,
        'severeFatigueReported', false
      )
    );
    v_replaced_by := v_replacement.completion_id;
  elsif p_completion ? 'replacedByCompletionId' then
    v_replaced_by := (p_completion->>'replacedByCompletionId')::uuid;
    -- This owner's, and unplanned: a planned log replaces nothing and cannot
    -- itself stand for what was done instead. Another owner's log is simply
    -- not there, and is refused the same way a missing one is.
    if not exists (
      select 1 from public.completions target
      where target.id = v_replaced_by
        and target.user_id = v_user_id
        and target.plan_session_id is null
    ) then
      raise exception using errcode = '22023', message = 'Invalid completion change.';
    end if;
  end if;

  if p_operation = 'create' then
    -- A create names no existing record and answers to no revision.
    if p_completion_id is not null or p_expected_revision is not null then
      raise exception using errcode = '22023', message = 'Invalid completion change.';
    end if;

    -- The record carries the zone its local date was written in, because the
    -- profile zone changes and a past date must not move with it.
    select profile.timezone_name into v_timezone
    from public.profiles profile where profile.user_id = v_user_id;
    if v_timezone is null then
      raise exception using errcode = 'PT428',
        message = 'Confirm your time zone before logging training.';
    end if;

    -- Nothing is completed before it happens.
    if (p_completion->>'actualLocalDate')::date
      > (v_now at time zone v_timezone)::date
    then
      raise exception using errcode = 'PT430',
        message = 'Training cannot be logged for a future date.';
    end if;

    if p_completion->>'status' <> 'unplanned' then
      v_plan_session_id := (p_completion->>'planSessionId')::uuid;
      -- Owner-scoped by construction: the state function reads the row only
      -- when it belongs to this owner, so another owner's session is simply
      -- not there. The snapshot is taken now and never read through again.
      -- Snapshot lock: hold the planned row before it is read, so what is
      -- read is what the log is written against. No timeout of its own: this
      -- is the wait the insert's foreign key already made, moved earlier, and
      -- the only holder it can wait for is a plan change, which bounds its
      -- own waits at three seconds and commits or fails.
      perform 1 from public.rolling_plan_sessions session
      where session.id = v_plan_session_id and session.user_id = v_user_id
      for key share;
      v_snapshot := public.rolling_plan_session_state(v_user_id, v_plan_session_id);
      if v_snapshot is null then
        raise exception using errcode = '22023',
          message = 'That planned session does not exist.';
      end if;
      -- A duplicate is refused by `completions_plan_session_key` and reported
      -- from the handler below. Reading first would answer the same question
      -- twice and answer it differently under a race: two callers can both
      -- pass a non-serialized `exists` and only the constraint decides.
    end if;

    -- Every new log carries its own name. The caller states it; when it does
    -- not - the app deployed before this migration never does - the name is
    -- the planned session's, or for unplanned training the first activity's,
    -- which is exactly where that version kept it. The backfill above follows
    -- the same rule, so no log reads differently depending on when it was
    -- written.
    if p_completion ? 'title' then
      v_title := pg_catalog.btrim(p_completion->>'title');
      v_sport := pg_catalog.btrim(p_completion->>'sport');
    elsif v_snapshot is not null then
      v_title := v_snapshot->>'title';
      v_sport := v_snapshot->>'sport';
    else
      select pg_catalog.btrim(first.value->>'name'),
        pg_catalog.btrim(first.value->>'sport')
      into v_title, v_sport
      from pg_catalog.jsonb_array_elements(p_completion->'activities')
        as first(value)
      order by (first.value->>'position')::integer
      limit 1;
    end if;

    insert into public.completions (
      user_id, plan_session_id, status, actual_local_date, timezone_name,
      actual_started_at, duration_minutes, perceived_effort, note,
      replacement_description, pain_reported, illness_reported, injury_reported,
      severe_fatigue_reported, planned_snapshot, title, sport,
      replaced_by_completion_id, created_at, updated_at
    ) values (
      v_user_id, v_plan_session_id, p_completion->>'status',
      (p_completion->>'actualLocalDate')::date, v_timezone,
      (p_completion->>'actualStartedAt')::timestamptz,
      (p_completion->>'durationMinutes')::integer,
      (p_completion->>'perceivedEffort')::smallint,
      nullif(p_completion->>'note', ''),
      nullif(pg_catalog.btrim(
        coalesce(p_completion->>'replacementDescription', '')), ''),
      coalesce((p_completion->>'painReported')::boolean, false),
      coalesce((p_completion->>'illnessReported')::boolean, false),
      coalesce((p_completion->>'injuryReported')::boolean, false),
      coalesce((p_completion->>'severeFatigueReported')::boolean, false),
      v_snapshot, v_title, v_sport, v_replaced_by, v_now, v_now
    ) returning id, revision into v_completion_id, v_revision;

    for v_activity in
      select value from pg_catalog.jsonb_array_elements(p_completion->'activities')
    loop
      if v_activity ? 'personalActivityId'
        and pg_catalog.jsonb_typeof(v_activity->'personalActivityId') <> 'null'
        and not exists (
          select 1 from public.personal_activities
          where id = (v_activity->>'personalActivityId')::uuid
            and user_id = v_user_id
        )
      then
        raise exception using errcode = '22023',
          message = 'Invalid completed activity.';
      end if;
      -- An actual may answer one planned activity of this log's own snapshot
      -- and no other. Unplanned training has no snapshot, so it answers none.
      -- A second actual answering the same one is refused by
      -- `completion_activities_planned_key`.
      if v_activity ? 'plannedPosition'
        and pg_catalog.jsonb_typeof(v_activity->'plannedPosition') <> 'null'
        and not exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            coalesce(v_snapshot->'activities', '[]'::jsonb)) as planned(value)
          where (planned.value->>'position')::integer
            = (v_activity->>'plannedPosition')::integer
        )
      then
        raise exception using errcode = '22023',
          message = 'Invalid completed activity.';
      end if;
      insert into public.completion_activities (
        user_id, completion_id, personal_activity_id, position, planned_position,
        name, sport, instructions, measurement_mode, actual_measurement,
        created_at, updated_at
      ) values (
        v_user_id, v_completion_id,
        (v_activity->>'personalActivityId')::uuid,
        (v_activity->>'position')::smallint,
        (v_activity->>'plannedPosition')::smallint,
        pg_catalog.btrim(v_activity->>'name'),
        pg_catalog.btrim(v_activity->>'sport'),
        nullif(v_activity->>'instructions', ''),
        v_activity->>'measurementMode',
        nullif(v_activity->'actualMeasurement', 'null'::jsonb), v_now, v_now
      );
    end loop;
    return (v_completion_id, v_revision, 'created')::public.completion_receipt;
  end if;

  -- An edit or a delete answers to the revision the owner last read.
  if p_completion_id is null or p_expected_revision is null
    or p_expected_revision < 0
  then
    raise exception using errcode = '22023', message = 'Invalid completion change.';
  end if;

  -- ADR-010. The wait is bounded, so a second same-owner save gets an answer
  -- rather than hanging. Locking the one row rather than the history lets two
  -- different completions be corrected at the same time.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    select completion.revision, completion.plan_session_id,
      completion.timezone_name, completion.planned_snapshot
    into v_revision, v_plan_session_id, v_timezone, v_snapshot
    from public.completions completion
    where completion.id = p_completion_id and completion.user_id = v_user_id
    for update;
  exception when lock_not_available then
    raise exception using errcode = 'PT409',
      message = 'That completion changed. Reload and try again.';
  end;

  -- A record another owner holds, or one already removed, is reported the same
  -- way: it changed. That is honest and leaks nothing.
  if v_revision is null or v_revision <> p_expected_revision then
    raise exception using errcode = 'PT409',
      message = 'That completion changed. Reload and try again.';
  end if;

  -- Delete a log (ADR-031). Really deleted: the row goes and its activities
  -- with it, by `completion_activities_completion_fkey`'s cascade. Planned
  -- sessions logged "Replaced" by this one go first, which the owner decided
  -- (16 Oct 2026) and which `completions_replaced_by_fkey` (no action) needs.
  -- Each was this owner's to delete: the pointer is checked to be the owner's
  -- own when it is written, and the predicate repeats it. A freed session is
  -- simply not logged; the settled rule tests for a log naming it.
  if p_operation = 'delete' then
    -- The Replaced logs are locked as the log was, under the same bounded
    -- wait, so a save holding one is answered as a change and not as an
    -- unexplained failure.
    begin
      perform 1 from public.completions replaced
      where replaced.replaced_by_completion_id = p_completion_id
        and replaced.user_id = v_user_id
      for update;
    exception when lock_not_available then
      raise exception using errcode = 'PT409',
        message = 'That completion changed. Reload and try again.';
    end;
    delete from public.completions replaced
    where replaced.replaced_by_completion_id = p_completion_id
      and replaced.user_id = v_user_id;
    delete from public.completions
    where id = p_completion_id and user_id = v_user_id;
    return (p_completion_id, v_revision, 'deleted')::public.completion_receipt;
  end if;

  -- The planned link is immutable, so an edit can never cross the boundary
  -- between a planned completion and an unplanned one.
  if (p_completion->>'status' = 'unplanned') <> (v_plan_session_id is null) then
    raise exception using errcode = '22023', message = 'Invalid completion change.';
  end if;

  -- A planned log's actuals may be corrected like any other log's. What it
  -- was measured against is `planned_snapshot`, which this branch reads to
  -- check each `plannedPosition` and never writes: correcting what was done
  -- does not rewrite what was planned. (M3-23 refused this, reading the actual
  -- list as though it were the snapshot.)

  -- The completion's own zone, not the profile's: an edit must not be judged
  -- against a zone the owner has since moved to.
  if (p_completion->>'actualLocalDate')::date
    > (v_now at time zone v_timezone)::date
  then
    raise exception using errcode = 'PT430',
      message = 'Training cannot be logged for a future date.';
  end if;

  update public.completions set
    status = p_completion->>'status',
    actual_local_date = (p_completion->>'actualLocalDate')::date,
    actual_started_at = (p_completion->>'actualStartedAt')::timestamptz,
    duration_minutes = (p_completion->>'durationMinutes')::integer,
    perceived_effort = (p_completion->>'perceivedEffort')::smallint,
    note = nullif(p_completion->>'note', ''),
    replacement_description = nullif(pg_catalog.btrim(
      coalesce(p_completion->>'replacementDescription', '')), ''),
    pain_reported = coalesce((p_completion->>'painReported')::boolean, false),
    illness_reported = coalesce((p_completion->>'illnessReported')::boolean, false),
    injury_reported = coalesce((p_completion->>'injuryReported')::boolean, false),
    severe_fatigue_reported =
      coalesce((p_completion->>'severeFatigueReported')::boolean, false),
    -- A name the edit does not state is left as it is: the app deployed
    -- before this migration sends none, and must not erase one.
    title = case when p_completion ? 'title'
      then pg_catalog.btrim(p_completion->>'title') else title end,
    sport = case when p_completion ? 'title'
      then pg_catalog.btrim(p_completion->>'sport') else sport end,
    -- Set on every edit, so a log corrected away from `replaced` no longer
    -- points anywhere; the validator admits a pointer only beside it.
    replaced_by_completion_id = v_replaced_by,
    revision = v_revision + 1,
    updated_at = v_now
  where id = p_completion_id and user_id = v_user_id;

  -- Replacing the list wholesale rather than updating rows in place: position
  -- is unique per completion, so a reorder would collide mid-statement, and the
  -- rows carry no history of their own.
  if p_completion ? 'activities' then
    delete from public.completion_activities
    where completion_id = p_completion_id and user_id = v_user_id;
    for v_activity in
      select value from pg_catalog.jsonb_array_elements(p_completion->'activities')
    loop
      if v_activity ? 'personalActivityId'
        and pg_catalog.jsonb_typeof(v_activity->'personalActivityId') <> 'null'
        and not exists (
          select 1 from public.personal_activities
          where id = (v_activity->>'personalActivityId')::uuid
            and user_id = v_user_id
        )
      then
        raise exception using errcode = '22023',
          message = 'Invalid completed activity.';
      end if;
      -- An actual may answer one planned activity of this log's own snapshot
      -- and no other. Unplanned training has no snapshot, so it answers none.
      -- A second actual answering the same one is refused by
      -- `completion_activities_planned_key`.
      if v_activity ? 'plannedPosition'
        and pg_catalog.jsonb_typeof(v_activity->'plannedPosition') <> 'null'
        and not exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            coalesce(v_snapshot->'activities', '[]'::jsonb)) as planned(value)
          where (planned.value->>'position')::integer
            = (v_activity->>'plannedPosition')::integer
        )
      then
        raise exception using errcode = '22023',
          message = 'Invalid completed activity.';
      end if;
      insert into public.completion_activities (
        user_id, completion_id, personal_activity_id, position, planned_position,
        name, sport, instructions, measurement_mode, actual_measurement,
        created_at, updated_at
      ) values (
        v_user_id, p_completion_id,
        (v_activity->>'personalActivityId')::uuid,
        (v_activity->>'position')::smallint,
        (v_activity->>'plannedPosition')::smallint,
        pg_catalog.btrim(v_activity->>'name'),
        pg_catalog.btrim(v_activity->>'sport'),
        nullif(v_activity->>'instructions', ''),
        v_activity->>'measurementMode',
        nullif(v_activity->'actualMeasurement', 'null'::jsonb), v_now, v_now
      );
    end loop;
  end if;

  return (p_completion_id, v_revision + 1, 'updated')::public.completion_receipt;
exception
  when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    -- Its own code, whether the second caller arrives a minute or a
    -- millisecond late: the surface has to tell the owner which refusal this
    -- is, and nothing about the outcome, the date, or the numbers is wrong.
    if v_constraint = 'completions_plan_session_key' then
      raise exception using errcode = 'PT431',
        message = 'That session already has a completion.';
    end if;
    raise exception using errcode = '22023', message = 'Invalid completion change.';
  when foreign_key_violation or check_violation
    or not_null_violation or invalid_datetime_format
    or invalid_text_representation then
    raise exception using errcode = '22023', message = 'Invalid completion change.';
end;
$$;


ALTER FUNCTION "public"."apply_completion_change"("p_operation" "text", "p_completion_id" "uuid", "p_expected_revision" bigint, "p_completion" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_goal_change"("p_expected_collection_revision" bigint, "p_operation" "text", "p_goal_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_desired_outcome" "text" DEFAULT NULL::"text", "p_sports" "text"[] DEFAULT NULL::"text"[], "p_target_date" "date" DEFAULT NULL::"date", "p_priority_tier" "text" DEFAULT NULL::"text", "p_target_rank" smallint DEFAULT NULL::smallint, "p_ordered_goal_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "public"."goal_change_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_current_revision bigint;
  v_new_revision bigint;
  v_goal public.goals;
  v_goal_id uuid;
  v_result text;
  v_old_tier text;
  v_old_rank smallint;
  v_old_status text;
  v_target_rank smallint;
  v_active_count integer;
  v_order_count integer;
  v_sport text;
  v_clean_sports text[] := array[]::text[];
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (
    select 1
    from public.profiles
    where user_id = v_user_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_expected_collection_revision is null
    or p_expected_collection_revision < 0
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid goal change.';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    62001,
    pg_catalog.hashtext(v_user_id::text)
  );

  select revision
  into v_current_revision
  from public.goal_collections
  where user_id = v_user_id;

  v_current_revision := coalesce(v_current_revision, 0);

  if v_current_revision <> p_expected_collection_revision then
    raise exception using
      errcode = 'PT409',
      message = 'Goals changed. Reload and try again.';
  end if;

  v_new_revision := v_current_revision + 1;
  set constraints public.goals_active_rank_key deferred;

  if p_operation in ('create', 'edit') then
    if p_title is null
      or char_length(trim(p_title)) not between 1 and 120
      or p_desired_outcome is null
      or char_length(trim(p_desired_outcome)) not between 1 and 1000
      or p_priority_tier is null
      or p_priority_tier not in ('core', 'supporting')
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    -- Changed: a goal names one to ten sports. Until now only the form
    -- required one. `coalesce` because `cardinality(null)` is null, which
    -- would pass a comparison rather than fail it.
    if cardinality(coalesce(p_sports, '{}')) not between 1 and 10 then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    foreach v_sport in array p_sports
    loop
      v_sport := trim(v_sport);
      if v_sport is null
        or char_length(v_sport) not between 1 and 60
        or lower(v_sport) = any (
          select lower(existing_sport)
          from unnest(v_clean_sports) as existing_sport
        )
      then
        raise exception using
          errcode = '22023',
          message = 'Invalid goal change.';
      end if;
      v_clean_sports := array_append(v_clean_sports, v_sport);
    end loop;
  end if;

  if p_operation = 'create' then
    if p_goal_id is not null or p_ordered_goal_ids is not null then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    select count(*)
    into v_active_count
    from public.goals
    where user_id = v_user_id
      and status = 'active'
      and priority_tier = p_priority_tier;

    if p_priority_tier = 'core' and v_active_count >= 3 then
      raise exception using
        errcode = 'PT409',
        message = 'Three core goals are already active.';
    end if;

    v_target_rank := coalesce(p_target_rank, v_active_count + 1);
    if v_target_rank < 1
      or v_target_rank > v_active_count + 1
      or (p_priority_tier = 'core' and v_target_rank > 3)
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    update public.goals
    set
      active_rank = active_rank + 1,
      last_active_rank = active_rank + 1,
      updated_at = v_now
    where user_id = v_user_id
      and status = 'active'
      and priority_tier = p_priority_tier
      and active_rank >= v_target_rank;

    insert into public.goals (
      user_id,
      title,
      desired_outcome,
      sports,
      target_date,
      priority_tier,
      status,
      active_rank,
      last_active_rank,
      created_at,
      updated_at
    )
    values (
      v_user_id,
      trim(p_title),
      trim(p_desired_outcome),
      v_clean_sports,
      p_target_date,
      p_priority_tier,
      'active',
      v_target_rank,
      v_target_rank,
      v_now,
      v_now
    )
    returning id into v_goal_id;
    v_result := 'created';

  elsif p_operation = 'edit' then
    if p_goal_id is null or p_ordered_goal_ids is not null then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    select *
    into v_goal
    from public.goals
    where id = p_goal_id
      and user_id = v_user_id;

    if not found then
      raise exception using
        errcode = 'PT409',
        message = 'Goals changed. Reload and try again.';
    end if;

    v_goal_id := v_goal.id;
    v_old_tier := v_goal.priority_tier;
    v_old_rank := v_goal.active_rank;

    if v_goal.status = 'active' then
      select count(*)
      into v_active_count
      from public.goals
      where user_id = v_user_id
        and status = 'active'
        and priority_tier = p_priority_tier
        and id <> v_goal.id;

      if p_priority_tier = 'core' and v_active_count >= 3 then
        raise exception using
          errcode = 'PT409',
          message = 'Three core goals are already active.';
      end if;

      v_target_rank := coalesce(
        p_target_rank,
        case
          when v_old_tier = p_priority_tier then v_old_rank
          else v_active_count + 1
        end
      );
      if v_target_rank < 1
        or v_target_rank > v_active_count + 1
        or (p_priority_tier = 'core' and v_target_rank > 3)
      then
        raise exception using
          errcode = '22023',
          message = 'Invalid goal change.';
      end if;

      if v_old_tier = p_priority_tier then
        if v_target_rank < v_old_rank then
          update public.goals
          set
            active_rank = active_rank + 1,
            last_active_rank = active_rank + 1,
            updated_at = v_now
          where user_id = v_user_id
            and status = 'active'
            and priority_tier = v_old_tier
            and id <> v_goal.id
            and active_rank >= v_target_rank
            and active_rank < v_old_rank;
        elsif v_target_rank > v_old_rank then
          update public.goals
          set
            active_rank = active_rank - 1,
            last_active_rank = active_rank - 1,
            updated_at = v_now
          where user_id = v_user_id
            and status = 'active'
            and priority_tier = v_old_tier
            and id <> v_goal.id
            and active_rank > v_old_rank
            and active_rank <= v_target_rank;
        end if;
      else
        update public.goals
        set
          active_rank = active_rank - 1,
          last_active_rank = active_rank - 1,
          updated_at = v_now
        where user_id = v_user_id
          and status = 'active'
          and priority_tier = v_old_tier
          and active_rank > v_old_rank;

        update public.goals
        set
          active_rank = active_rank + 1,
          last_active_rank = active_rank + 1,
          updated_at = v_now
        where user_id = v_user_id
          and status = 'active'
          and priority_tier = p_priority_tier
          and active_rank >= v_target_rank;
      end if;
    else
      v_target_rank := null;
    end if;

    update public.goals
    set
      title = trim(p_title),
      desired_outcome = trim(p_desired_outcome),
      sports = v_clean_sports,
      target_date = p_target_date,
      priority_tier = p_priority_tier,
      active_rank = v_target_rank,
      last_active_rank = coalesce(v_target_rank, last_active_rank),
      updated_at = v_now
    where id = v_goal.id
      and user_id = v_user_id;
    v_result := 'updated';

  elsif p_operation = 'reorder' then
    if p_goal_id is not null
      or p_priority_tier not in ('core', 'supporting')
      or p_ordered_goal_ids is null
      or p_target_rank is not null
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    select count(*)
    into v_active_count
    from public.goals
    where user_id = v_user_id
      and status = 'active'
      and priority_tier = p_priority_tier;

    select count(distinct goal_id)
    into v_order_count
    from unnest(p_ordered_goal_ids) as goal_id;

    if cardinality(p_ordered_goal_ids) <> v_active_count
      or v_order_count <> v_active_count
      or exists (
        select 1
        from unnest(p_ordered_goal_ids) as requested_goal_id
        where not exists (
          select 1
          from public.goals
          where id = requested_goal_id
            and user_id = v_user_id
            and status = 'active'
            and priority_tier = p_priority_tier
        )
      )
    then
      raise exception using
        errcode = 'PT409',
        message = 'Goals changed. Reload and try again.';
    end if;

    update public.goals
    set
      active_rank = array_position(p_ordered_goal_ids, id),
      last_active_rank = array_position(p_ordered_goal_ids, id),
      updated_at = v_now
    where user_id = v_user_id
      and status = 'active'
      and priority_tier = p_priority_tier;
    v_result := 'reordered';

  elsif p_operation in (
    'pause',
    'resume',
    'achieve',
    'abandon',
    'reopen',
    'delete'
  ) then
    if p_goal_id is null or p_ordered_goal_ids is not null then
      raise exception using
        errcode = '22023',
        message = 'Invalid goal change.';
    end if;

    select *
    into v_goal
    from public.goals
    where id = p_goal_id
      and user_id = v_user_id;

    if not found then
      raise exception using
        errcode = 'PT409',
        message = 'Goals changed. Reload and try again.';
    end if;

    v_goal_id := v_goal.id;
    v_old_tier := v_goal.priority_tier;
    v_old_rank := v_goal.active_rank;
    v_old_status := v_goal.status;

    if p_operation in ('pause', 'achieve', 'abandon') then
      if v_goal.status <> 'active' then
        raise exception using
          errcode = 'PT409',
          message = 'Goals changed. Reload and try again.';
      end if;

      update public.goals
      set
        status = case
          when p_operation = 'pause' then 'paused'
          when p_operation = 'achieve' then 'achieved'
          else 'abandoned'
        end,
        active_rank = null,
        last_active_rank = v_old_rank,
        -- Changed: the moment a goal was achieved is its own column.
        achieved_at = case when p_operation = 'achieve' then v_now end,
        updated_at = v_now
      where id = v_goal.id
        and user_id = v_user_id;

      update public.goals
      set
        active_rank = active_rank - 1,
        last_active_rank = active_rank - 1,
        updated_at = v_now
      where user_id = v_user_id
        and status = 'active'
        and priority_tier = v_old_tier
        and active_rank > v_old_rank;
      v_result := case
        when p_operation = 'pause' then 'paused'
        when p_operation = 'achieve' then 'achieved'
        else 'abandoned'
      end;

    elsif p_operation in ('resume', 'reopen') then
      if (
          p_operation = 'resume'
          and v_goal.status <> 'paused'
        )
        or (
          p_operation = 'reopen'
          and v_goal.status not in ('achieved', 'abandoned')
        )
      then
        raise exception using
          errcode = 'PT409',
          message = 'Goals changed. Reload and try again.';
      end if;

      if p_priority_tier is not null
        and p_priority_tier not in ('core', 'supporting')
      then
        raise exception using
          errcode = '22023',
          message = 'Invalid goal change.';
      end if;
      v_old_tier := coalesce(p_priority_tier, v_goal.priority_tier);

      select count(*)
      into v_active_count
      from public.goals
      where user_id = v_user_id
        and status = 'active'
        and priority_tier = v_old_tier;

      if v_old_tier = 'core' and v_active_count >= 3 then
        raise exception using
          errcode = 'PT409',
          message = 'Three core goals are already active.';
      end if;

      v_target_rank := coalesce(p_target_rank, v_active_count + 1);
      if v_target_rank < 1
        or v_target_rank > v_active_count + 1
        or (v_old_tier = 'core' and v_target_rank > 3)
      then
        raise exception using
          errcode = '22023',
          message = 'Invalid goal change.';
      end if;

      update public.goals
      set
        active_rank = active_rank + 1,
        last_active_rank = active_rank + 1,
        updated_at = v_now
      where user_id = v_user_id
        and status = 'active'
        and priority_tier = v_old_tier
        and active_rank >= v_target_rank;

      update public.goals
      set
        priority_tier = v_old_tier,
        status = 'active',
        achieved_at = null,
        active_rank = v_target_rank,
        last_active_rank = v_target_rank,
        updated_at = v_now
      where id = v_goal.id
        and user_id = v_user_id;

      if p_operation = 'reopen' then
        insert into public.goal_lifecycle_events (
          user_id,
          goal_id,
          from_status,
          to_status,
          collection_revision,
          created_at
        )
        values (
          v_user_id,
          v_goal.id,
          v_old_status,
          'active',
          v_new_revision,
          v_now
        );
        v_result := 'reopened';
      else
        v_result := 'resumed';
      end if;

    else
      -- Changed: any goal can be deleted, whatever its status and whether or
      -- not it was reopened (owner, 7 Oct 2026). Its reopen history goes
      -- first, because that table's foreign key restricts the delete.
      delete from public.goal_lifecycle_events
      where goal_id = v_goal.id
        and user_id = v_user_id;

      delete from public.goals
      where id = v_goal.id
        and user_id = v_user_id;

      if v_old_rank is not null then
        update public.goals
        set
          active_rank = active_rank - 1,
          last_active_rank = active_rank - 1,
          updated_at = v_now
        where user_id = v_user_id
          and status = 'active'
          and priority_tier = v_old_tier
          and active_rank > v_old_rank;
      end if;
      v_result := 'deleted';
    end if;

  else
    raise exception using
      errcode = '22023',
      message = 'Invalid goal change.';
  end if;

  if exists (
    select 1
    from (
      select
        priority_tier,
        count(*) as goal_count,
        min(active_rank) as min_rank,
        max(active_rank) as max_rank,
        count(distinct active_rank) as distinct_rank_count
      from public.goals
      where user_id = v_user_id
        and status = 'active'
      group by priority_tier
    ) as ordering
    where min_rank <> 1
      or max_rank <> goal_count
      or distinct_rank_count <> goal_count
      or (priority_tier = 'core' and goal_count > 3)
  ) then
    raise exception using
      errcode = '23514',
      message = 'Goal ordering could not be completed.';
  end if;

  insert into public.goal_collections (user_id, revision, updated_at)
  values (v_user_id, v_new_revision, v_now)
  on conflict (user_id)
  do update set
    revision = excluded.revision,
    updated_at = excluded.updated_at;

  return (
    v_goal_id,
    v_new_revision,
    v_result
  )::public.goal_change_receipt;
end;
$$;


ALTER FUNCTION "public"."apply_goal_change"("p_expected_collection_revision" bigint, "p_operation" "text", "p_goal_id" "uuid", "p_title" "text", "p_desired_outcome" "text", "p_sports" "text"[], "p_target_date" "date", "p_priority_tier" "text", "p_target_rank" smallint, "p_ordered_goal_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_live_workout_log"("p_live_workout_id" "uuid", "p_completion" "jsonb") RETURNS "public"."completion_receipt"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  if p_live_workout_id is null then
    raise exception using errcode = '22023', message = 'Invalid completion change.';
  end if;

  delete from public.live_workouts workout
  where workout.id = p_live_workout_id and workout.user_id = v_user_id;
  if not found then
    raise exception using errcode = 'PT409',
      message = 'That workout was already logged or discarded.';
  end if;

  return public.apply_completion_change('create', null, null, p_completion);
end;
$$;


ALTER FUNCTION "public"."apply_live_workout_log"("p_live_workout_id" "uuid", "p_completion" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_memory_change"("p_expected_collection_revision" bigint, "p_operation" "text", "p_item_id" "uuid" DEFAULT NULL::"uuid", "p_memory_type" "text" DEFAULT NULL::"text", "p_content" "text" DEFAULT NULL::"text", "p_expires_on" "date" DEFAULT NULL::"date") RETURNS "public"."memory_change_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_current_revision bigint;
  v_new_revision bigint;
  v_item public.memory_items;
  v_current public.memory_revisions;
  v_item_id uuid;
  v_revision_id uuid;
  v_revision_number integer;
  v_content text;
  v_status text;
  v_change_kind text;
  v_provenance text;
  v_result text;
  v_purged integer;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (
    select 1
    from public.profiles
    where user_id = v_user_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_expected_collection_revision is null
    or p_expected_collection_revision < 0
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory change.';
  end if;

  -- ADR-010. Every lock wait in this transaction is bounded. An unbounded wait
  -- would leave a second same-owner save hanging with no answer, which is the
  -- defect M2-01's review found in ADR-009's advisory lock. Exhaustion becomes
  -- a conflict the caller can act on rather than a silent hang.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62002,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Memory changed. Reload and try again.';
  end;

  select revision
  into v_current_revision
  from public.memory_collections
  where user_id = v_user_id;

  v_current_revision := coalesce(v_current_revision, 0);

  if v_current_revision <> p_expected_collection_revision then
    raise exception using
      errcode = 'PT409',
      message = 'Memory changed. Reload and try again.';
  end if;

  v_new_revision := v_current_revision + 1;

  if p_operation not in (
    'create',
    'edit',
    'accept',
    'edit_and_accept',
    'reject',
    'disable',
    'enable',
    'renew',
    'delete'
  ) then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory change.';
  end if;

  -- Every operation states exactly which inputs it accepts, so an unexpected
  -- field is a rejected change rather than a silently ignored one.
  if p_operation = 'create' then
    if p_item_id is not null
      or p_memory_type is null
      or p_content is null
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory change.';
    end if;
  elsif p_operation in ('edit', 'edit_and_accept') then
    if p_item_id is null
      or p_memory_type is not null
      or p_content is null
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory change.';
    end if;
  elsif p_operation = 'renew' then
    if p_item_id is null
      or p_memory_type is not null
      or p_content is not null
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory change.';
    end if;
  else
    if p_item_id is null
      or p_memory_type is not null
      or p_content is not null
      or p_expires_on is not null
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory change.';
    end if;
  end if;

  if p_memory_type is not null
    and p_memory_type not in (
      'profile_fact',
      'constraint',
      'preference',
      'observed_pattern'
    )
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory change.';
  end if;

  if p_content is not null then
    v_content := trim(p_content);
    if char_length(v_content) not between 1 and 1000 then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory change.';
    end if;
  end if;

  if p_operation = 'create' then
    v_item_id := gen_random_uuid();
    v_revision_id := gen_random_uuid();
    v_revision_number := 1;
    -- Anything the owner states about themselves is active on save, whichever
    -- class it belongs to. `proposed` is reserved for content FitTip derived
    -- rather than content the owner wrote, and this path cannot produce that:
    -- provenance and author class are fixed below and are not caller inputs.
    v_status := 'active';

    insert into public.memory_revisions (
      id,
      user_id,
      item_id,
      revision_number,
      content,
      author_class,
      provenance,
      change_kind,
      status_after,
      previous_revision_id,
      created_at
    )
    values (
      v_revision_id,
      v_user_id,
      v_item_id,
      v_revision_number,
      v_content,
      'user',
      'user_created',
      'created',
      v_status,
      null,
      v_now
    );

    insert into public.memory_items (
      id,
      user_id,
      memory_type,
      status,
      provenance,
      expires_on,
      current_revision_id,
      user_confirmed_at,
      status_changed_at,
      created_at,
      updated_at
    )
    values (
      v_item_id,
      v_user_id,
      p_memory_type,
      v_status,
      'user_created',
      p_expires_on,
      v_revision_id,
      -- The owner wrote it and saved it, so it is confirmed at creation.
      v_now,
      v_now,
      v_now,
      v_now
    );
    v_result := 'created';

  else
    select *
    into v_item
    from public.memory_items
    where id = p_item_id
      and user_id = v_user_id;

    if not found then
      raise exception using
        errcode = 'PT409',
        message = 'Memory changed. Reload and try again.';
    end if;

    v_item_id := v_item.id;

    select *
    into v_current
    from public.memory_revisions
    where id = v_item.current_revision_id
      and user_id = v_user_id;

    if not found then
      raise exception using
        errcode = '23503',
        message = 'The memory change could not be completed.';
    end if;

    if p_operation = 'delete' then
      delete from public.memory_revisions
      where item_id = v_item.id
        and user_id = v_user_id;
      get diagnostics v_purged = row_count;

      delete from public.memory_items
      where id = v_item.id
        and user_id = v_user_id;

      -- Evidence that a deletion happened, carrying none of the deleted text.
      insert into public.memory_deletion_events (
        user_id,
        item_id,
        memory_type,
        purged_revision_count,
        collection_revision,
        created_at
      )
      values (
        v_user_id,
        v_item.id,
        v_item.memory_type,
        v_purged,
        v_new_revision,
        v_now
      );
      v_revision_number := null;
      v_result := 'deleted';

    else
      if p_operation = 'edit' then
        if v_item.status not in ('active', 'archived') then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := v_item.status;
        v_change_kind := 'edited';
        v_provenance := 'user_created';
        v_result := 'updated';

      elsif p_operation = 'edit_and_accept' then
        if v_item.status not in ('proposed', 'rejected') then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := 'active';
        v_change_kind := 'edited_and_accepted';
        v_provenance := 'user_created';
        v_result := 'accepted';

      elsif p_operation = 'accept' then
        if v_item.status not in ('proposed', 'rejected') then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := 'active';
        v_change_kind := 'accepted';
        -- Accepting does not rewrite the text, so the new revision keeps the
        -- provenance of the content it carries. The item's own provenance and
        -- its user_confirmed_at record who confirmed it.
        v_provenance := v_current.provenance;
        v_content := v_current.content;
        v_result := 'accepted';

      elsif p_operation = 'reject' then
        if v_item.status <> 'proposed' then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := 'rejected';
        v_change_kind := 'rejected';
        v_provenance := v_current.provenance;
        v_content := v_current.content;
        v_result := 'rejected';

      elsif p_operation = 'disable' then
        if v_item.status <> 'active' then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := 'archived';
        v_change_kind := 'disabled';
        v_provenance := v_current.provenance;
        v_content := v_current.content;
        v_result := 'disabled';

      elsif p_operation = 'enable' then
        if v_item.status <> 'archived' then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := 'active';
        v_change_kind := 'enabled';
        v_provenance := v_current.provenance;
        v_content := v_current.content;
        v_result := 'enabled';

      else
        if v_item.status <> 'active' then
          raise exception using
            errcode = 'PT409',
            message = 'Memory changed. Reload and try again.';
        end if;
        v_status := 'active';
        v_change_kind := 'renewed';
        v_provenance := v_current.provenance;
        v_content := v_current.content;
        v_result := 'renewed';
      end if;

      v_revision_id := gen_random_uuid();
      v_revision_number := v_current.revision_number + 1;

      insert into public.memory_revisions (
        id,
        user_id,
        item_id,
        revision_number,
        content,
        author_class,
        provenance,
        change_kind,
        status_after,
        previous_revision_id,
        created_at
      )
      values (
        v_revision_id,
        v_user_id,
        v_item.id,
        v_revision_number,
        v_content,
        'user',
        v_provenance,
        v_change_kind,
        v_status,
        v_current.id,
        v_now
      );

      update public.memory_items
      set
        status = v_status,
        expires_on = case
          when p_operation in ('edit', 'edit_and_accept', 'renew')
            then p_expires_on
          else expires_on
        end,
        current_revision_id = v_revision_id,
        user_confirmed_at = case
          when p_operation in ('edit', 'edit_and_accept', 'accept')
            then v_now
          else user_confirmed_at
        end,
        status_changed_at = case
          when v_status <> v_item.status then v_now
          else status_changed_at
        end,
        updated_at = v_now
      where id = v_item.id
        and user_id = v_user_id;
    end if;
  end if;

  insert into public.memory_collections (user_id, revision, updated_at)
  values (v_user_id, v_new_revision, v_now)
  on conflict (user_id)
  do update set
    revision = excluded.revision,
    updated_at = excluded.updated_at;

  -- The receipt carries no memory content.
  return (
    v_item_id,
    v_new_revision,
    v_revision_number,
    v_result
  )::public.memory_change_receipt;
end;
$$;


ALTER FUNCTION "public"."apply_memory_change"("p_expected_collection_revision" bigint, "p_operation" "text", "p_item_id" "uuid", "p_memory_type" "text", "p_content" "text", "p_expires_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_roadmap_proposal_change"("p_operation" "text", "p_proposal_id" "uuid", "p_content" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."roadmap_proposal_change_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_proposal public.roadmap_proposals;
  v_request public.roadmap_generation_requests;
  v_decision public.roadmap_proposal_decisions;
  v_new_id uuid;
  v_existing_edit uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_operation is null
    or p_operation not in ('edit', 'reject')
    or p_proposal_id is null
    or (p_operation = 'edit' and p_content is null)
    or (p_operation = 'reject' and p_content is not null)
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap change.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62005,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
  end;

  select * into v_proposal
  from public.roadmap_proposals
  where id = p_proposal_id and user_id = v_user_id;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That proposal is no longer available.';
  end if;

  select * into v_decision
  from public.roadmap_proposal_decisions
  where proposal_id = v_proposal.id and user_id = v_user_id;

  if p_operation = 'reject' then
    if found then
      if v_decision.decision = 'rejected' then
        return (v_proposal.id, 'rejected')
          ::public.roadmap_proposal_change_receipt;
      end if;
      raise exception using
        errcode = 'PT409',
        message = 'That proposal has already been decided.';
    end if;

    insert into public.roadmap_proposal_decisions (
      proposal_id, user_id, decision, accepted_version_id, decided_at
    )
    values (v_proposal.id, v_user_id, 'rejected', null, v_now);

    return (v_proposal.id, 'rejected')
      ::public.roadmap_proposal_change_receipt;
  end if;

  if found then
    raise exception using
      errcode = 'PT409',
      message = 'That proposal has already been decided.';
  end if;

  select * into v_request
  from public.roadmap_generation_requests
  where id = v_proposal.generation_request_id and user_id = v_user_id;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That proposal is no longer available.';
  end if;

  if not public.roadmap_content_is_valid(
    p_content,
    v_request.requested_start_date,
    v_request.requested_end_date
  ) then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap change.';
  end if;

  -- Replay of the same edit returns the existing receipt instead of stacking a
  -- second identical owner_edit proposal.
  select id into v_existing_edit
  from public.roadmap_proposals
  where user_id = v_user_id
    and source_proposal_id = v_proposal.id
    and origin = 'owner_edit'
    and content = p_content
  limit 1;

  if v_existing_edit is not null then
    return (v_existing_edit, 'edited')::public.roadmap_proposal_change_receipt;
  end if;

  -- The edit copies the original's owner text, technical metadata and source
  -- references. It does not rewrite or decide the source proposal, and none of
  -- those fields is a caller input. The schema version is the one exception
  -- since v3, and it is not free either: it is read from content the check
  -- above has already held to `fittip.roadmap.v3`.
  insert into public.roadmap_proposals (
    user_id, generation_request_id, source_proposal_id, origin, planning_note,
    regeneration_feedback, schema_version, prompt_version, provider_code,
    model_code, rate_card_version, spend_reservation_id, content, created_at
  )
  values (
    v_user_id, v_proposal.generation_request_id, v_proposal.id, 'owner_edit',
    v_proposal.planning_note, v_proposal.regeneration_feedback,
    -- The version of what is stored, not of what was edited: an edit of a v2
    -- proposal is v3 content, and `roadmap_content_is_valid` has just said so.
    p_content->>'schemaVersion', v_proposal.prompt_version,
    v_proposal.provider_code, v_proposal.model_code,
    v_proposal.rate_card_version, v_proposal.spend_reservation_id,
    p_content, v_now
  )
  returning id into v_new_id;

  insert into public.roadmap_proposal_sources (
    proposal_id, user_id, ordinal, source_kind, record_id, revision_id,
    revision_number
  )
  select
    v_new_id, v_user_id, ordinal, source_kind, record_id, revision_id,
    revision_number
  from public.roadmap_proposal_sources
  where proposal_id = v_proposal.id and user_id = v_user_id;

  return (v_new_id, 'edited')::public.roadmap_proposal_change_receipt;
end;
$$;


ALTER FUNCTION "public"."apply_roadmap_proposal_change"("p_operation" "text", "p_proposal_id" "uuid", "p_content" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_rolling_plan_change_set"("p_expected_plan_revision" bigint, "p_idempotency_key" "uuid", "p_provenance" "text", "p_changes" "jsonb") RETURNS "public"."rolling_plan_change_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_timezone text;
  v_today date;
  v_plan public.rolling_plans;
  v_existing public.rolling_plan_change_sets;
  v_fingerprint text;
  v_change_set_id uuid := gen_random_uuid();
  v_new_revision bigint;
  v_change jsonb;
  v_operation text;
  v_session_input jsonb;
  v_session_id uuid;
  v_local_date date;
  v_target_date date;
  v_before jsonb;
  v_after jsonb;
  v_activity jsonb;
  v_ordinal integer := 0;
  v_position numeric;
  v_session_dates date[] := array[]::date[];
  v_series public.rolling_plan_series;
  v_series_id uuid;
  v_series_input jsonb;
  v_effective_date date;
  v_successor_series_id uuid;
  v_sweep_from date;
  v_sweep jsonb;
  v_series_effects jsonb := '[]'::jsonb;
  v_occurrence_series_id uuid;
  v_occurrence_date date;
  -- Cancellation reason: the owner's optional why, kept beside the session.
  v_cancel_reason text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'An authenticated FitTip user is required.';
  end if;
  if p_expected_plan_revision is null or p_expected_plan_revision < 0
    or p_idempotency_key is null or p_provenance is null
    or p_provenance !~ '^[a-z][a-z0-9_]{0,63}$'
    or p_changes is null or pg_catalog.jsonb_typeof(p_changes) <> 'array'
    or pg_catalog.jsonb_array_length(p_changes) not between 1 and 100
  then
    raise exception using errcode = '22023', message = 'Invalid rolling plan change set.';
  end if;

  -- Owner-local today comes from the stored profile zone and auth.uid() only.
  -- A caller cannot supply either, so neither rule below can be argued away.
  select profile.timezone_name into v_timezone
  from public.profiles profile where profile.user_id = v_user_id;
  if v_timezone is null then
    raise exception using errcode = 'PT428',
      message = 'Confirm your time zone before changing your plan.';
  end if;
  v_today := (pg_catalog.timezone(v_timezone, v_now))::date;

  v_fingerprint := pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'expectedPlanRevision', p_expected_plan_revision,
      'provenance', p_provenance,
      'changes', p_changes
    )::text, 'UTF8'), 'sha256'), 'hex');

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(62006, pg_catalog.hashtext(v_user_id::text));
  exception when lock_not_available then
    raise exception using errcode = 'PT409', message = 'Your plan changed. Reload and try again.';
  end;

  select * into v_existing from public.rolling_plan_change_sets
  where user_id = v_user_id and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_fingerprint <> v_fingerprint then
      raise exception using errcode = 'PT409', message = 'That plan change key was already used.';
    end if;
    return (
      v_existing.plan_id, v_existing.plan_revision, v_existing.id, 'replayed', null
    )::public.rolling_plan_change_receipt;
  end if;

  select * into v_plan from public.rolling_plans where user_id = v_user_id for update;
  if not found then
    if p_expected_plan_revision <> 0 then
      raise exception using errcode = 'PT409', message = 'Your plan changed. Reload and try again.';
    end if;
    insert into public.rolling_plans (user_id) values (v_user_id) returning * into v_plan;
  elsif v_plan.revision <> p_expected_plan_revision then
    raise exception using errcode = 'PT409', message = 'Your plan changed. Reload and try again.';
  end if;

  v_new_revision := v_plan.revision + 1;
  insert into public.rolling_plan_change_sets (
    id, user_id, plan_id, plan_revision, idempotency_key,
    request_fingerprint, provenance, created_at
  ) values (
    v_change_set_id, v_user_id, v_plan.id, v_new_revision,
    p_idempotency_key, v_fingerprint, p_provenance, v_now
  );

  for v_change in select value from pg_catalog.jsonb_array_elements(p_changes) loop
    if pg_catalog.jsonb_typeof(v_change) <> 'object'
      or not (v_change ? 'operation')
      or pg_catalog.jsonb_typeof(v_change->'operation') <> 'string'
    then raise exception using errcode = '22023', message = 'Invalid rolling plan change.'; end if;
    v_operation := v_change->>'operation';
    v_before := null;
    v_session_id := null;
    v_local_date := null;
    v_series_id := null;
    v_successor_series_id := null;
    v_sweep_from := null;

    if v_operation = 'set_recovery_day' then
      if v_change - array['operation', 'localDate', 'isRecoveryDay'] <> '{}'::jsonb
        or not (v_change ?& array['localDate', 'isRecoveryDay'])
        or pg_catalog.jsonb_typeof(v_change->'localDate') <> 'string'
        or (v_change->>'localDate')::date::text <> v_change->>'localDate'
        or pg_catalog.jsonb_typeof(v_change->'isRecoveryDay') <> 'boolean'
      then raise exception using errcode = '22023', message = 'Invalid rolling plan recovery day.'; end if;
      v_local_date := (v_change->>'localDate')::date;
      if v_local_date < v_today then
        raise exception using errcode = 'PT422',
          message = 'A plan change cannot target a date before today.';
      end if;

      -- A label is not a session, so it never counts toward the per-date cap.
      v_before := pg_catalog.jsonb_build_object(
        'localDate', v_local_date::text,
        'isRecoveryDay', exists (
          select 1 from public.rolling_plan_recovery_days recovery
          where recovery.user_id = v_user_id and recovery.local_date = v_local_date
        )
      );
      if (v_change->>'isRecoveryDay')::boolean then
        insert into public.rolling_plan_recovery_days (
          user_id, plan_id, local_date, created_at
        ) values (v_user_id, v_plan.id, v_local_date, v_now)
        on conflict (user_id, local_date) do nothing;
      else
        delete from public.rolling_plan_recovery_days recovery
        where recovery.user_id = v_user_id and recovery.local_date = v_local_date;
      end if;
      v_after := pg_catalog.jsonb_build_object(
        'localDate', v_local_date::text,
        'isRecoveryDay', (v_change->>'isRecoveryDay')::boolean
      );
    elsif v_operation in ('add_series', 'edit_series', 'end_series') then
      if not (v_change ? 'seriesId')
        or pg_catalog.jsonb_typeof(v_change->'seriesId') <> 'string'
      then raise exception using errcode = '22023', message = 'Invalid rolling plan series change.'; end if;
      begin v_series_id := (v_change->>'seriesId')::uuid;
      exception when others then
        raise exception using errcode = '22023', message = 'Invalid rolling plan series change.';
      end;

      if v_operation = 'add_series' then
        if v_change - array['operation', 'seriesId', 'series'] <> '{}'::jsonb
          or not (v_change ? 'series')
          or not public.rolling_plan_series_input_is_valid(v_change->'series')
          or exists (select 1 from public.rolling_plan_series where id = v_series_id)
        then raise exception using errcode = '22023', message = 'Invalid rolling plan series.'; end if;
        v_series_input := v_change->'series';
        if (v_series_input->>'startDate')::date < v_today then
          raise exception using errcode = 'PT422',
            message = 'A plan change cannot target a date before today.';
        end if;
        insert into public.rolling_plan_series (
          id, user_id, plan_id, predecessor_series_id, frequency, interval_count,
          weekdays, start_date, end_date, title, sport, intent,
          expected_duration_minutes, start_time, note, coach_note, created_at,
          updated_at
        ) values (
          v_series_id, v_user_id, v_plan.id, null,
          v_series_input->>'frequency',
          (v_series_input->>'intervalCount')::smallint,
          public.rolling_plan_weekday_set(v_series_input->'weekdays'),
          (v_series_input->>'startDate')::date,
          (v_series_input->>'endDate')::date,
          pg_catalog.btrim(v_series_input->>'title'),
          pg_catalog.btrim(v_series_input->>'sport'),
          nullif(v_series_input->>'intent', ''),
          (v_series_input->>'expectedDurationMinutes')::integer,
          (v_series_input->>'startTime')::time,
          nullif(v_series_input->>'note', ''),
          nullif(v_series_input->>'coachNote', ''),
          v_now, v_now
        );
        perform public.rolling_plan_replace_series_activities(
          v_user_id, v_series_id, v_series_input->'activities', v_now
        );
        v_after := public.rolling_plan_series_state(v_user_id, v_series_id);
      else
        select * into v_series from public.rolling_plan_series
        where id = v_series_id and user_id = v_user_id for update;
        if not found then
          raise exception using errcode = '22023', message = 'Invalid rolling plan series change.';
        end if;
        v_before := public.rolling_plan_series_state(v_user_id, v_series_id);

        if v_operation = 'end_series' then
          if v_change - array['operation', 'seriesId', 'effectiveDate'] <> '{}'::jsonb
            or not (v_change ? 'effectiveDate')
            or pg_catalog.jsonb_typeof(v_change->'effectiveDate') <> 'string'
            or (v_change->>'effectiveDate')::date::text <> v_change->>'effectiveDate'
          then raise exception using errcode = '22023', message = 'Invalid rolling plan series change.'; end if;
          v_effective_date := (v_change->>'effectiveDate')::date;
          if v_effective_date < v_today then
            raise exception using errcode = 'PT422',
              message = 'A plan change cannot target a date before today.';
          end if;
          -- Ending a segment never lengthens it. A segment that already
          -- ends earlier keeps its own end date, because the sweep below only
          -- runs from the effective date forward and so could never remove the
          -- occurrences a pushed-out end date would let the next
          -- materialization write into the reopened gap.
          update public.rolling_plan_series set
            end_date = least(
              coalesce(end_date, 'infinity'::date), v_effective_date - 1
            ),
            updated_at = v_now
          where id = v_series_id and user_id = v_user_id;
          v_sweep_from := v_effective_date;
          v_after := public.rolling_plan_series_state(v_user_id, v_series_id);
        elsif v_change ? 'effectiveDate' then
          -- This and future: close the running segment and open a successor
          -- that points back at it. Occurrences before the split date are never
          -- touched, so what they meant is preserved.
          if v_change - array[
            'operation', 'seriesId', 'effectiveDate', 'successorSeriesId', 'series'
          ] <> '{}'::jsonb
            or not (v_change ?& array['successorSeriesId', 'series'])
            or pg_catalog.jsonb_typeof(v_change->'effectiveDate') <> 'string'
            or (v_change->>'effectiveDate')::date::text <> v_change->>'effectiveDate'
            or pg_catalog.jsonb_typeof(v_change->'successorSeriesId') <> 'string'
            or not public.rolling_plan_series_input_is_valid(v_change->'series')
          then raise exception using errcode = '22023', message = 'Invalid rolling plan series change.'; end if;
          v_series_input := v_change->'series';
          v_effective_date := (v_change->>'effectiveDate')::date;
          begin v_successor_series_id := (v_change->>'successorSeriesId')::uuid;
          exception when others then
            raise exception using errcode = '22023', message = 'Invalid rolling plan series change.';
          end;
          if v_effective_date < v_today then
            raise exception using errcode = 'PT422',
              message = 'A plan change cannot target a date before today.';
          end if;
          -- The successor starts on the split date and the predecessor keeps
          -- at least its own first day, so a split is never a whole-series
          -- edit wearing a different name.
          if v_effective_date <= v_series.start_date
            or (v_series_input->>'startDate')::date <> v_effective_date
            or exists (select 1 from public.rolling_plan_series where id = v_successor_series_id)
          then raise exception using errcode = '22023', message = 'Invalid rolling plan series change.'; end if;
          -- Closing the predecessor never lengthens it either; the clamp is
          -- the same one `end_series` applies, for the same reason.
          update public.rolling_plan_series set
            end_date = least(
              coalesce(end_date, 'infinity'::date), v_effective_date - 1
            ),
            updated_at = v_now
          where id = v_series_id and user_id = v_user_id
          returning end_date into v_series.end_date;
          insert into public.rolling_plan_series (
            id, user_id, plan_id, predecessor_series_id, frequency, interval_count,
            weekdays, start_date, end_date, title, sport, intent,
            expected_duration_minutes, start_time, note, coach_note, created_at,
          updated_at
          ) values (
            v_successor_series_id, v_user_id, v_plan.id, v_series_id,
            v_series_input->>'frequency',
            (v_series_input->>'intervalCount')::smallint,
            public.rolling_plan_weekday_set(v_series_input->'weekdays'),
            v_effective_date,
            (v_series_input->>'endDate')::date,
            pg_catalog.btrim(v_series_input->>'title'),
            pg_catalog.btrim(v_series_input->>'sport'),
            nullif(v_series_input->>'intent', ''),
            (v_series_input->>'expectedDurationMinutes')::integer,
            (v_series_input->>'startTime')::time,
            nullif(v_series_input->>'note', ''),
            nullif(v_series_input->>'coachNote', ''),
            v_now, v_now
          );
          perform public.rolling_plan_replace_series_activities(
            v_user_id, v_successor_series_id, v_series_input->'activities', v_now
          );
          v_sweep_from := v_effective_date;
          v_after := public.rolling_plan_series_state(v_user_id, v_successor_series_id)
            || pg_catalog.jsonb_build_object(
              'predecessorSeriesId', v_series_id,
              'predecessorEndDate', v_series.end_date::text
            );
        else
          -- A whole-series edit rewrites what every occurrence of the segment
          -- means, so it is only offered while the segment has not started.
          if v_change - array['operation', 'seriesId', 'series'] <> '{}'::jsonb
            or not (v_change ? 'series')
            or not public.rolling_plan_series_input_is_valid(v_change->'series')
          then raise exception using errcode = '22023', message = 'Invalid rolling plan series change.'; end if;
          -- No occurrence can precede the segment's own start date, so a
          -- segment that still starts today or later has had none.
          if v_series.start_date < v_today then
            raise exception using errcode = 'PT424',
              message = 'This series has already started. Change it from a date instead.';
          end if;
          v_series_input := v_change->'series';
          if (v_series_input->>'startDate')::date < v_today then
            raise exception using errcode = 'PT422',
              message = 'A plan change cannot target a date before today.';
          end if;
          update public.rolling_plan_series set
            frequency = v_series_input->>'frequency',
            interval_count = (v_series_input->>'intervalCount')::smallint,
            weekdays = public.rolling_plan_weekday_set(v_series_input->'weekdays'),
            start_date = (v_series_input->>'startDate')::date,
            end_date = (v_series_input->>'endDate')::date,
            title = pg_catalog.btrim(v_series_input->>'title'),
            sport = pg_catalog.btrim(v_series_input->>'sport'),
            intent = nullif(v_series_input->>'intent', ''),
            expected_duration_minutes = (v_series_input->>'expectedDurationMinutes')::integer,
            start_time = (v_series_input->>'startTime')::time,
            note = nullif(v_series_input->>'note', ''),
            coach_note = nullif(v_series_input->>'coachNote', ''),
            updated_at = v_now
          where id = v_series_id and user_id = v_user_id;
          perform public.rolling_plan_replace_series_activities(
            v_user_id, v_series_id, v_series_input->'activities', v_now
          );
          -- The rule changed, so every occurrence it already produced is stale.
          v_sweep_from := least(
            v_series.start_date, (v_series_input->>'startDate')::date
          );
          -- M3-20: a deleted occurrence is skipped only under the rule it was
          -- deleted from. The rule is being rewritten from here, and the sweep
          -- below already discards every cancelled and edited occurrence in
          -- the same range, so the owner's skips there go with them.
          update public.rolling_plan_series set
            skipped_occurrence_dates = array(
              select skipped from pg_catalog.unnest(skipped_occurrence_dates) as skipped
              where skipped < v_sweep_from order by skipped
            )
          where id = v_series_id and user_id = v_user_id;
          v_after := public.rolling_plan_series_state(v_user_id, v_series_id);
        end if;
      end if;
    else
      if not (v_change ? 'sessionId')
        or pg_catalog.jsonb_typeof(v_change->'sessionId') <> 'string'
      then raise exception using errcode = '22023', message = 'Invalid rolling plan change.'; end if;
      begin v_session_id := (v_change->>'sessionId')::uuid;
      exception when others then
        raise exception using errcode = '22023', message = 'Invalid rolling plan change.';
      end;

      if v_operation = 'add' then
        if v_change - array['operation', 'sessionId', 'session'] <> '{}'::jsonb
          or not (v_change ? 'session')
          or not public.rolling_plan_session_input_is_valid(v_change->'session', true)
          or exists (select 1 from public.rolling_plan_sessions where id = v_session_id)
        then raise exception using errcode = '22023', message = 'Invalid rolling plan addition.'; end if;
        v_session_input := v_change->'session';
        v_local_date := (v_session_input->>'localDate')::date;
        if v_local_date < v_today then
          raise exception using errcode = 'PT422',
            message = 'A plan change cannot target a date before today.';
        end if;
        v_occurrence_series_id := (v_session_input->>'seriesId')::uuid;
        if v_occurrence_series_id is not null and not exists (
          select 1 from public.rolling_plan_series
          where id = v_occurrence_series_id and user_id = v_user_id
        ) then
          raise exception using errcode = '22023', message = 'Invalid rolling plan addition.';
        end if;
        v_session_dates := v_session_dates || v_local_date;
        insert into public.rolling_plan_sessions (
          id, user_id, plan_id, local_date, position, title, sport, intent,
          expected_duration_minutes, start_time, note, coach_note, status, series_id,
          occurrence_date, has_diverged, created_at, updated_at
        ) values (
          v_session_id, v_user_id, v_plan.id,
          v_local_date,
          (v_session_input->>'position')::smallint,
          pg_catalog.btrim(v_session_input->>'title'),
          pg_catalog.btrim(v_session_input->>'sport'),
          nullif(v_session_input->>'intent', ''),
          (v_session_input->>'expectedDurationMinutes')::integer,
          (v_session_input->>'startTime')::time,
          nullif(v_session_input->>'note', ''),
          nullif(v_session_input->>'coachNote', ''),
          'active', v_occurrence_series_id,
          (v_session_input->>'occurrenceDate')::date,
          false, v_now, v_now
        );
      elsif v_operation = 'delete' then
        -- M3-19: the one owner-driven hard delete of a planned session.
        --
        -- A cancelled row is admitted as well as an active one, because a
        -- session the owner already cancelled is exactly what they may next
        -- want gone. The past boundary still holds, as it does for every
        -- other operation.
        if v_change - array['operation', 'sessionId'] <> '{}'::jsonb then
          raise exception using errcode = '22023', message = 'Invalid rolling plan deletion.';
        end if;
        select session.local_date, session.series_id, session.occurrence_date
        into v_local_date, v_occurrence_series_id, v_occurrence_date
        from public.rolling_plan_sessions session
        where session.id = v_session_id and session.user_id = v_user_id
          and session.status in ('active', 'cancelled')
        for update;
        if not found then raise exception using errcode = '22023', message = 'Invalid rolling plan change.'; end if;
        if v_local_date < v_today then
          raise exception using errcode = 'PT422',
            message = 'A plan change cannot target a date before today.';
        end if;
        -- The record of what happened outlives the plan entry it was measured
        -- against, which is the same reasoning that made `planned_snapshot`
        -- write-once. `completions_plan_fkey` would refuse the delete anyway;
        -- raising here is what turns a raw foreign-key violation into an
        -- owner-visible refusal. The row lock above is stronger than the key
        -- share a concurrent completion insert takes, so this cannot be raced.
        if exists (
          select 1 from public.completions completion
          where completion.user_id = v_user_id
            and completion.plan_session_id = v_session_id
        ) then
          raise exception using errcode = 'PT425',
            message = 'This session has training logged against it, so its plan entry cannot be changed.';
        end if;
        v_session_dates := v_session_dates || v_local_date;
        v_before := public.rolling_plan_session_state(v_user_id, v_session_id);
        delete from public.rolling_plan_sessions
        where id = v_session_id and user_id = v_user_id;
        -- M3-20: without this the materializer finds the rule date empty and
        -- writes the occurrence straight back. The rule date is recorded, not
        -- the local date, because a moved occurrence is still the series'
        -- answer to its rule date. Dates behind today can never be filled
        -- again, so they are dropped here rather than kept forever.
        if v_occurrence_series_id is not null and v_occurrence_date >= v_today then
          update public.rolling_plan_series set
            skipped_occurrence_dates = array(
              select skipped from pg_catalog.unnest(
                skipped_occurrence_dates || v_occurrence_date
              ) as skipped
              where skipped >= v_today
              group by skipped order by skipped
            )
          where id = v_occurrence_series_id and user_id = v_user_id;
        end if;
        -- Exactly the entry `rolling_plan_sweep_series_occurrences` already
        -- writes for a removed occurrence: a dated `delete` naming no session,
        -- which is what survives `rolling_plan_change_entries_session_fkey`
        -- cascading this row's own earlier entries away.
        v_after := pg_catalog.jsonb_build_object(
          'localDate', v_local_date::text, 'deleted', true
        );
      elsif v_operation = 'reactivate' then
        -- M3-20: the one operation that admits only a cancelled session. Like
        -- delete it is the owner's individual act; the past boundary holds,
        -- because an active planned
        -- session in the past is something no operation may create. A session
        -- trained after it was cancelled is logged against the cancelled row,
        -- whose completion snapshot then records both facts.
        if v_change - array['operation', 'sessionId'] <> '{}'::jsonb then
          raise exception using errcode = '22023', message = 'Invalid rolling plan reactivation.';
        end if;
        select session.local_date into v_local_date
        from public.rolling_plan_sessions session
        where session.id = v_session_id and session.user_id = v_user_id
          and session.status = 'cancelled'
        for update;
        if not found then raise exception using errcode = '22023', message = 'Invalid rolling plan change.'; end if;
        if v_local_date < v_today then
          raise exception using errcode = 'PT422',
            message = 'A plan change cannot target a date before today.';
        end if;
        -- Logged session: a cancelled session that was trained anyway keeps
        -- the state its log was written against.
        if exists (
          select 1 from public.completions completion
          where completion.user_id = v_user_id
            and completion.plan_session_id = v_session_id
        ) then
          raise exception using errcode = 'PT425',
            message = 'This session has training logged against it, so its plan entry cannot be changed.';
        end if;
        v_session_dates := v_session_dates || v_local_date;
        v_before := public.rolling_plan_session_state(v_user_id, v_session_id);
        -- Cancelling freed the session's place in the day, and another session
        -- may hold it now. It returns after the last active one; a day that is
        -- already full is refused by the cap below, not here.
        select coalesce(pg_catalog.max(session.position), -1) + 1 into v_position
        from public.rolling_plan_sessions session
        where session.user_id = v_user_id and session.local_date = v_local_date
          and session.status = 'active';
        if v_position > 99 then
          select pg_catalog.min(candidate) into v_position
          from pg_catalog.generate_series(0, 99) as candidate
          where not exists (
            select 1 from public.rolling_plan_sessions session
            where session.user_id = v_user_id and session.local_date = v_local_date
              and session.status = 'active' and session.position = candidate
          );
        end if;
        update public.rolling_plan_sessions set
          status = 'active', cancelled_at = null,
          position = v_position::smallint, updated_at = v_now
        where id = v_session_id and user_id = v_user_id;
        -- Cancellation reason: a reactivated session is no longer cancelled,
        -- so why it was is no longer true of it (owner, 29 Sep 2026).
        delete from public.rolling_plan_session_cancellations
        where session_id = v_session_id and user_id = v_user_id;
      elsif v_operation in ('edit', 'move', 'cancel') then
        select session.local_date into v_local_date
        from public.rolling_plan_sessions session
        where session.id = v_session_id and session.user_id = v_user_id
          and session.status = 'active'
        for update;
        if not found then raise exception using errcode = '22023', message = 'Invalid rolling plan change.'; end if;
        -- A past session is history: the past boundary blocks the owner.
        if v_local_date < v_today then
          raise exception using errcode = 'PT422',
            message = 'A plan change cannot target a date before today.';
        end if;
        -- Logged session: what a log was measured against is settled, because
        -- the page that offers
        -- none of these is the rule being enforced. Behind the row lock
        -- above, as Delete's check is, so a log being written is waited for.
        if exists (
          select 1 from public.completions completion
          where completion.user_id = v_user_id
            and completion.plan_session_id = v_session_id
        ) then
          raise exception using errcode = 'PT425',
            message = 'This session has training logged against it, so its plan entry cannot be changed.';
        end if;
        v_session_dates := v_session_dates || v_local_date;
        v_before := public.rolling_plan_session_state(v_user_id, v_session_id);

        if v_operation = 'edit' then
          if v_change - array['operation', 'sessionId', 'session'] <> '{}'::jsonb
            or not (v_change ? 'session')
            or not public.rolling_plan_session_input_is_valid(v_change->'session', false)
          then raise exception using errcode = '22023', message = 'Invalid rolling plan edit.'; end if;
          v_session_input := v_change->'session';
          update public.rolling_plan_sessions set
            title = pg_catalog.btrim(v_session_input->>'title'),
            sport = pg_catalog.btrim(v_session_input->>'sport'),
            intent = nullif(v_session_input->>'intent', ''),
            expected_duration_minutes = (v_session_input->>'expectedDurationMinutes')::integer,
            start_time = (v_session_input->>'startTime')::time,
            note = nullif(v_session_input->>'note', ''),
            coach_note = nullif(v_session_input->>'coachNote', ''),
            updated_at = v_now
          where id = v_session_id and user_id = v_user_id;
          delete from public.rolling_plan_activities
          where session_id = v_session_id and user_id = v_user_id;
        elsif v_operation = 'move' then
          if v_change - array['operation', 'sessionId', 'localDate', 'position'] <> '{}'::jsonb
            or not (v_change ?& array['localDate', 'position'])
            or pg_catalog.jsonb_typeof(v_change->'localDate') <> 'string'
            or (v_change->>'localDate')::date::text <> v_change->>'localDate'
            or pg_catalog.jsonb_typeof(v_change->'position') <> 'number'
          then raise exception using errcode = '22023', message = 'Invalid rolling plan move.'; end if;
          v_position := (v_change->>'position')::numeric;
          if v_position <> trunc(v_position) or v_position not between 0 and 99 then
            raise exception using errcode = '22023', message = 'Invalid rolling plan move.';
          end if;
          v_target_date := (v_change->>'localDate')::date;
          if v_target_date < v_today then
            raise exception using errcode = 'PT422',
              message = 'A plan change cannot target a date before today.';
          end if;
          v_session_dates := v_session_dates || v_target_date;
          update public.rolling_plan_sessions set
            local_date = v_target_date,
            position = v_position::smallint, updated_at = v_now
          where id = v_session_id and user_id = v_user_id;
        elsif v_operation = 'cancel' then
          -- Cancellation reason: `reason` is optional, and a cancel without
          -- one is exactly the cancel it always was.
          if v_change - array['operation', 'sessionId', 'reason'] <> '{}'::jsonb
            or (
              v_change ? 'reason'
              and pg_catalog.jsonb_typeof(v_change->'reason') <> 'null'
              and not public.rolling_plan_cancellation_reason_is_valid(v_change->'reason')
            )
          then
            raise exception using errcode = '22023', message = 'Invalid rolling plan cancellation.';
          end if;
          update public.rolling_plan_sessions set
            status = 'cancelled', cancelled_at = v_now, updated_at = v_now
          where id = v_session_id and user_id = v_user_id;
          v_cancel_reason := pg_catalog.btrim(v_change->>'reason', E' \t\r\n');
          if v_cancel_reason is not null then
            insert into public.rolling_plan_session_cancellations (
              session_id, user_id, reason, created_at, updated_at
            ) values (v_session_id, v_user_id, v_cancel_reason, v_now, v_now);
          end if;
        else
          -- M3-19: cancel used to be this chain's fallthrough. Now that one of
          -- the operations beside it destroys a row, an unrecognized operation
          -- has to land nowhere rather than in whichever branch happens to be
          -- written last.
          raise exception using errcode = '22023', message = 'Invalid rolling plan change.';
        end if;

        -- ADR-017, as amended 22 September 2026: an occurrence is diverged
        -- when its content no longer reads as its rule's, which only an edit
        -- does. A move and a cancel leave what it says alone, so they
        -- leave the flag alone. The materializer never revisits an existing
        -- occurrence either way.
        if v_operation = 'edit' then
          update public.rolling_plan_sessions set has_diverged = true
          where id = v_session_id and user_id = v_user_id
            and series_id is not null and not has_diverged;
        end if;
      else
        raise exception using errcode = '22023', message = 'Invalid rolling plan change.';
      end if;

      if v_operation in ('add', 'edit') then
        for v_activity in
          select value from pg_catalog.jsonb_array_elements(v_session_input->'activities')
        loop
          if v_activity ? 'personalActivityId'
            and pg_catalog.jsonb_typeof(v_activity->'personalActivityId') <> 'null'
            and not exists (
              select 1 from public.personal_activities
              where id = (v_activity->>'personalActivityId')::uuid and user_id = v_user_id
            )
          then raise exception using errcode = '22023', message = 'Invalid rolling plan activity.'; end if;
          insert into public.rolling_plan_activities (
            user_id, plan_id, session_id, personal_activity_id, position,
            name, sport, instructions, rationale, measurement_mode, target,
            created_at, updated_at
          ) values (
            v_user_id, v_plan.id, v_session_id,
            (v_activity->>'personalActivityId')::uuid,
            (v_activity->>'position')::smallint,
            pg_catalog.btrim(v_activity->>'name'),
            pg_catalog.btrim(v_activity->>'sport'),
            nullif(v_activity->>'instructions', ''),
            nullif(v_activity->>'rationale', ''),
            v_activity->>'measurementMode', v_activity->'target',
            v_now, v_now
          );
        end loop;
      end if;

      if v_operation <> 'delete' then
        v_after := public.rolling_plan_session_state(v_user_id, v_session_id);
      end if;
    end if;

    if v_before is not null and v_before = v_after then
      raise exception using errcode = '22023', message = 'A plan change must change current state.';
    end if;
    insert into public.rolling_plan_change_entries (
      user_id, plan_id, change_set_id, session_id, series_id, local_date,
      ordinal, change_kind, before_state, after_state, created_at
    ) values (
      v_user_id, v_plan.id, v_change_set_id,
      case when v_operation in ('add', 'edit', 'move', 'cancel', 'reactivate')
        then v_session_id else null end,
      case when v_operation = 'add_series' then v_series_id
        when v_operation = 'end_series' then v_series_id
        when v_operation = 'edit_series'
          then coalesce(v_successor_series_id, v_series_id)
        else null end,
      case when v_operation in ('set_recovery_day', 'delete') then v_local_date
        else null end,
      v_ordinal, v_operation, v_before, v_after, v_now
    );
    v_ordinal := v_ordinal + 1;

    if v_sweep_from is not null then
      v_sweep := public.rolling_plan_sweep_series_occurrences(
        v_user_id, v_plan.id, v_change_set_id, v_series_id,
        v_sweep_from, v_today, v_ordinal, v_now
      );
      v_ordinal := (v_sweep->>'nextOrdinal')::integer;
      v_series_effects := v_series_effects || pg_catalog.jsonb_build_object(
        'seriesId', v_series_id,
        'operation', v_operation,
        'deleted', v_sweep->'deleted',
        'divergedDeleted', v_sweep->'divergedDeleted',
        'completedKept', v_sweep->'completedKept'
      );
    end if;
  end loop;

  set constraints public.rolling_plan_sessions_active_order_key immediate;

  -- The cap is judged on the state the whole change set leaves behind, not on
  -- any one subchange, so a swap that stays within ten never trips it.
  if exists (
    select 1 from public.rolling_plan_sessions session
    where session.user_id = v_user_id and session.status = 'active'
      and session.local_date = any(v_session_dates)
    group by session.local_date
    having pg_catalog.count(*) > 10
  ) then
    raise exception using errcode = 'PT423',
      message = 'A date holds at most ten planned sessions.';
  end if;

  update public.rolling_plans set revision = v_new_revision, updated_at = v_now
  where id = v_plan.id and user_id = v_user_id;
  return (
    v_plan.id, v_new_revision, v_change_set_id, 'applied',
    case when pg_catalog.jsonb_array_length(v_series_effects) = 0
      then null else v_series_effects end
  )::public.rolling_plan_change_receipt;
exception
  when unique_violation or foreign_key_violation or check_violation or invalid_datetime_format then
    raise exception using errcode = '22023', message = 'Invalid rolling plan change set.';
end;
$_$;


ALTER FUNCTION "public"."apply_rolling_plan_change_set"("p_expected_plan_revision" bigint, "p_idempotency_key" "uuid", "p_provenance" "text", "p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_saved_session_change"("p_operation" "text", "p_saved_session_id" "uuid" DEFAULT NULL::"uuid", "p_expected_revision" bigint DEFAULT NULL::bigint, "p_name" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_sport" "text" DEFAULT NULL::"text", "p_intent" "text" DEFAULT NULL::"text", "p_expected_duration_minutes" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text", "p_activities" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."saved_session_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_saved_session_id uuid;
  v_revision bigint;
  v_activity jsonb;
  v_position smallint;
  v_constraint text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  if p_operation is null
    or p_operation not in ('create', 'edit', 'delete')
  then
    raise exception using errcode = '22023', message = 'Invalid saved session change.';
  end if;

  if p_operation = 'create' then
    -- A create names no existing record and answers to no revision.
    if p_saved_session_id is not null or p_expected_revision is not null
      or p_activities is null
      or pg_catalog.jsonb_typeof(p_activities) <> 'array'
      or pg_catalog.jsonb_array_length(p_activities) > 50
    then
      raise exception using errcode = '22023', message = 'Invalid saved session.';
    end if;
    for v_activity in select value from pg_catalog.jsonb_array_elements(p_activities) loop
      if not public.saved_session_activity_input_is_valid(v_activity) then
        raise exception using errcode = '22023', message = 'Invalid saved session activity.';
      end if;
    end loop;

    insert into public.saved_sessions (
      user_id, name, title, sport, intent, expected_duration_minutes, note,
      created_at, updated_at
    ) values (
      v_user_id, pg_catalog.btrim(p_name), pg_catalog.btrim(p_title),
      pg_catalog.btrim(p_sport), nullif(p_intent, ''),
      p_expected_duration_minutes, nullif(p_note, ''), v_now, v_now
    ) returning id, revision into v_saved_session_id, v_revision;

    for v_activity in select value from pg_catalog.jsonb_array_elements(p_activities) loop
      if v_activity ? 'personalActivityId'
        and pg_catalog.jsonb_typeof(v_activity->'personalActivityId') <> 'null'
        and not exists (
          select 1 from public.personal_activities
          where id = (v_activity->>'personalActivityId')::uuid and user_id = v_user_id
        )
      then
        raise exception using errcode = '22023', message = 'Invalid saved session activity.';
      end if;
      insert into public.saved_session_activities (
        user_id, saved_session_id, personal_activity_id, position,
        name, sport, instructions, measurement_mode, target, created_at, updated_at
      ) values (
        v_user_id, v_saved_session_id,
        (v_activity->>'personalActivityId')::uuid,
        (v_activity->>'position')::smallint,
        pg_catalog.btrim(v_activity->>'name'),
        pg_catalog.btrim(v_activity->>'sport'),
        nullif(v_activity->>'instructions', ''),
        v_activity->>'measurementMode',
        nullif(v_activity->'target', 'null'::jsonb), v_now, v_now
      );
    end loop;
    return (v_saved_session_id, v_revision, 'created')::public.saved_session_receipt;
  end if;

  -- Edit and delete both answer to the revision the owner last read.
  if p_saved_session_id is null or p_expected_revision is null
    or p_expected_revision < 0
    or (p_operation = 'delete' and (
      p_name is not null or p_title is not null or p_sport is not null
      or p_intent is not null or p_expected_duration_minutes is not null
      or p_note is not null or p_activities is not null))
    -- A6: an edit may carry the whole activity list. Null keeps it as saved.
    -- A CASE rather than OR, because OR does not promise to test the type
    -- before the length.
    or (p_operation = 'edit' and p_activities is not null and case
      when pg_catalog.jsonb_typeof(p_activities) = 'array'
        then pg_catalog.jsonb_array_length(p_activities) > 50
      else true
    end)
  then
    raise exception using errcode = '22023', message = 'Invalid saved session change.';
  end if;

  -- Every element is judged before anything is locked or written, so a list
  -- with one bad activity refuses the whole edit.
  if p_operation = 'edit' and p_activities is not null then
    for v_activity in select value from pg_catalog.jsonb_array_elements(p_activities) loop
      if not public.saved_session_activity_input_is_valid(v_activity) then
        raise exception using errcode = '22023', message = 'Invalid saved session activity.';
      end if;
    end loop;
  end if;

  -- ADR-010. The wait is bounded, so a second same-owner save gets an answer
  -- rather than hanging. Locking the one row rather than the whole library
  -- lets two different saved sessions be edited at the same time.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    select saved_session.revision into v_revision
    from public.saved_sessions saved_session
    where saved_session.id = p_saved_session_id
      and saved_session.user_id = v_user_id
    for update;
  exception when lock_not_available then
    raise exception using errcode = 'PT409',
      message = 'That saved session changed. Reload and try again.';
  end;

  -- A record another owner holds, or one already deleted elsewhere, is
  -- reported the same way: it changed. That is honest and leaks nothing.
  if v_revision is null or v_revision <> p_expected_revision then
    raise exception using errcode = 'PT409',
      message = 'That saved session changed. Reload and try again.';
  end if;

  if p_operation = 'delete' then
    delete from public.saved_sessions
    where id = p_saved_session_id and user_id = v_user_id;
    return (p_saved_session_id, v_revision, 'deleted')::public.saved_session_receipt;
  end if;

  update public.saved_sessions set
    name = pg_catalog.btrim(p_name),
    title = pg_catalog.btrim(p_title),
    sport = pg_catalog.btrim(p_sport),
    intent = nullif(p_intent, ''),
    expected_duration_minutes = p_expected_duration_minutes,
    note = nullif(p_note, ''),
    revision = v_revision + 1,
    updated_at = v_now
  where id = p_saved_session_id and user_id = v_user_id;

  if p_activities is not null then
    -- A replacement, as the Plan's editor makes one: the rows the owner
    -- removed are gone because they are absent here. Positions are the array's
    -- order, so the submitted `position` values are not trusted to be dense.
    delete from public.saved_session_activities
    where saved_session_id = p_saved_session_id and user_id = v_user_id;
    for v_activity, v_position in
      select value, ordinality - 1
      from pg_catalog.jsonb_array_elements(p_activities) with ordinality
    loop
      if v_activity ? 'personalActivityId'
        and pg_catalog.jsonb_typeof(v_activity->'personalActivityId') <> 'null'
        and not exists (
          select 1 from public.personal_activities
          where id = (v_activity->>'personalActivityId')::uuid and user_id = v_user_id
        )
      then
        raise exception using errcode = '22023', message = 'Invalid saved session activity.';
      end if;
      insert into public.saved_session_activities (
        user_id, saved_session_id, personal_activity_id, position,
        name, sport, instructions, measurement_mode, target, created_at, updated_at
      ) values (
        v_user_id, p_saved_session_id,
        (v_activity->>'personalActivityId')::uuid,
        v_position,
        pg_catalog.btrim(v_activity->>'name'),
        pg_catalog.btrim(v_activity->>'sport'),
        nullif(v_activity->>'instructions', ''),
        v_activity->>'measurementMode',
        nullif(v_activity->'target', 'null'::jsonb), v_now, v_now
      );
    end loop;
  end if;
  return (p_saved_session_id, v_revision + 1, 'updated')::public.saved_session_receipt;
exception
  when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    -- Its own code: the surface offers to update the entry with that title
    -- or to keep both under another (owner, 15 Oct 2026).
    if v_constraint = 'saved_sessions_title_key' then
      raise exception using errcode = 'PT434',
        message = 'A saved session with that title already exists.';
    end if;
    raise exception using errcode = '22023', message = 'Invalid saved session change.';
  when foreign_key_violation or check_violation
    or not_null_violation then
    raise exception using errcode = '22023', message = 'Invalid saved session change.';
end;
$$;


ALTER FUNCTION "public"."apply_saved_session_change"("p_operation" "text", "p_saved_session_id" "uuid", "p_expected_revision" bigint, "p_name" "text", "p_title" "text", "p_sport" "text", "p_intent" "text", "p_expected_duration_minutes" integer, "p_note" "text", "p_activities" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_plan_generation"("p_idempotency_key" "text", "p_request_fingerprint" "text", "p_start_date" "date", "p_day_count" integer, "p_expected_plan_revision" bigint, "p_planning_note" "text" DEFAULT NULL::"text", "p_previous_proposal_id" "uuid" DEFAULT NULL::"uuid", "p_regeneration_feedback" "text" DEFAULT NULL::"text", "p_replaceable_session_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "public"."plan_generation_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing public.plan_generation_requests;
  v_note text;
  v_end_date date;
  v_feedback text;
  v_previous public.plan_proposals;
  v_previous_request public.plan_generation_requests;
  v_regeneration_number smallint := 0;
  v_receipt public.plan_generation_receipt;
  v_replaceable uuid[] := coalesce(p_replaceable_session_ids, '{}'::uuid[]);
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (select 1 from public.profiles where user_id = v_user_id) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_idempotency_key is null
    or pg_catalog.char_length(p_idempotency_key) not between 16 and 128
    or p_request_fingerprint is null
    or pg_catalog.char_length(p_request_fingerprint) not between 16 and 256
    or p_start_date is null
    or p_day_count is null
    or p_day_count not between 1 and 7
    or p_expected_plan_revision is null
    or p_expected_plan_revision < 0
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan request.';
  end if;

  -- A start no earlier than the day before UTC today. The single day of slack
  -- is deliberate: the owner's local today can legitimately be one day behind
  -- or ahead of the server's. The plan's own past-date rule is enforced where
  -- it belongs, in `apply_rolling_plan_change_set`, against the owner's stored
  -- zone rather than against UTC.
  if p_start_date < (v_now at time zone 'utc')::date - 1 then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan request.';
  end if;
  v_end_date := p_start_date + (p_day_count - 1);

  -- What the owner marked "can be replaced". Seven days hold at most three
  -- proposed sessions each, so more marks than that could never all be used.
  if pg_catalog.cardinality(v_replaceable) > 21
    or pg_catalog.array_position(v_replaceable, null) is not null
    or pg_catalog.cardinality(v_replaceable) <> (
      select pg_catalog.count(distinct marked)
      from pg_catalog.unnest(v_replaceable) as marked
    )
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan request.';
  end if;

  v_note := public.roadmap_normalize_owner_text(p_planning_note);
  if v_note = '' then v_note := null; end if;
  if v_note is not null and pg_catalog.char_length(v_note) > 1000 then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan request.';
  end if;

  -- The regeneration half. Feedback without a proposal to attach it to is a
  -- complaint about nothing, and a proposal without feedback is a repeat of a
  -- question already paid for, so the two travel together or not at all.
  v_feedback := public.roadmap_normalize_owner_text(p_regeneration_feedback);
  if v_feedback = '' then v_feedback := null; end if;
  if (v_feedback is null) <> (p_previous_proposal_id is null) then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan request.';
  end if;
  -- 500, not 1000: `REGENERATION_FEEDBACK_MAX_LENGTH` in the context assembly
  -- has been 500 since M3-02, and that check runs after the owner's review has
  -- already been applied. Accepting more here only means destroying a proposal
  -- over text the coach would never have been shown.
  if v_feedback is not null
    and pg_catalog.char_length(v_feedback) not between 1 and 500
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan request.';
  end if;

  if p_previous_proposal_id is not null then
    select * into v_previous
    from public.plan_proposals
    where id = p_previous_proposal_id and user_id = v_user_id;

    if not found then
      raise exception using
        errcode = 'PT409',
        message = 'That proposal is no longer open.';
    end if;

    select * into v_previous_request
    from public.plan_generation_requests
    where id = v_previous.generation_request_id and user_id = v_user_id;

    v_regeneration_number :=
      (coalesce(v_previous_request.regeneration_number, 0) + 1)::smallint;

    -- Now that the lineage is a line, this ceiling means what it says. `PT429`
    -- rather than `22023`, matching the roadmap: the generic invalid-request
    -- code maps to "Something went wrong", which is the least useful thing to
    -- say to an owner who has just been told their proposal was closed.
    if v_regeneration_number > 20 then
      raise exception using
        errcode = 'PT429',
        message = 'This plan has reached its regeneration limit.';
    end if;
  end if;

  -- Same key, same fingerprint replays the claim, returning the stored status —
  -- pending, completed, or failed — and never 'claimed'. That is the whole
  -- discriminator. A different fingerprint under the same key is a conflict,
  -- not a silent second call.
  select * into v_existing
  from public.plan_generation_requests
  where user_id = v_user_id and idempotency_key = p_idempotency_key;

  if found then
    if v_existing.request_fingerprint is distinct from p_request_fingerprint then
      raise exception using
        errcode = 'PT409',
        message = 'That coaching request changed. Reload and try again.';
    end if;
    return (
      v_existing.id,
      v_existing.completion_token,
      v_existing.status,
      v_existing.proposal_id
    )::public.plan_generation_receipt;
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62007,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  -- The checks on the source run under the lock, so two "ask again" presses
  -- at once cannot both pass them: the second sees the first's request.
  if p_previous_proposal_id is not null then
    -- The proposal being regenerated stays open while the coach is asked
    -- (owner, 17 Oct 2026): a failed answer used to leave the owner with
    -- nothing, since the review had already been closed. It is closed by
    -- `finish_plan_generation`, in the transaction that records its
    -- replacement. One request at a time per source. A request pending for
    -- more than ten minutes is one whose server died after the call, since
    -- no call waits longer than ninety seconds; it blocks nothing.
    if exists (
      select 1
      from public.plan_generation_requests
      where previous_proposal_id = p_previous_proposal_id
        and user_id = v_user_id
        and status = 'pending'
        and created_at > pg_catalog.now() - interval '10 minutes'
    ) then
      raise exception using
        errcode = 'PT409',
        message = 'The coach is already being asked again about that proposal.';
    end if;

    -- One proposal, one replacement.
    --
    -- Without this the count above is not a chain at all. It reads the number
    -- from whichever predecessor the caller *names*, and a closed proposal
    -- stays closed forever, so pointing at the first proposal of a lineage
    -- yields 1 every time and the ceiling never arrives. Measured against a
    -- local database before adding this: two regenerations from one source,
    -- both numbered 1.
    if exists (
      select 1
      from public.plan_proposals
      where source_proposal_id = p_previous_proposal_id
        and user_id = v_user_id
    ) then
      raise exception using
        errcode = 'PT409',
        message = 'That proposal has already been replaced.';
    end if;
  end if;

  begin
    insert into public.plan_generation_requests (
      user_id, idempotency_key, request_fingerprint,
      requested_start_date, requested_end_date, day_count,
      expected_plan_revision, planning_note_hash, previous_proposal_id,
      regeneration_number, regeneration_feedback_hash, created_at, updated_at
    ) values (
      v_user_id, p_idempotency_key, p_request_fingerprint,
      p_start_date, v_end_date, p_day_count::smallint,
      p_expected_plan_revision, public.roadmap_owner_text_hash(v_note),
      p_previous_proposal_id, v_regeneration_number,
      public.roadmap_owner_text_hash(v_feedback),
      v_now, v_now
    )
    returning id, completion_token, 'claimed', proposal_id into v_receipt;

    -- The marks, written with the claim and only with it: a replay returns
    -- above and never reaches this. Each must be this owner's active session
    -- on one of the requested days with no training logged against it, which
    -- `finish_plan_proposal_review` checks again before it deletes anything. One that is not is a refusal rather than a mark
    -- quietly dropped: the owner was shown a list and chose from it.
    if pg_catalog.cardinality(v_replaceable) > 0 then
      insert into public.plan_generation_replaceable_sessions (
        request_id, user_id, handle, session_id
      )
      select
        v_receipt.generation_id,
        v_user_id,
        'r' || pg_catalog.row_number() over (
          order by session.local_date, session.position, session.id
        ),
        session.id
      from public.rolling_plan_sessions session
      where session.user_id = v_user_id
        and session.id = any (v_replaceable)
        and session.status = 'active'
        and session.local_date between p_start_date and v_end_date
        and not exists (
          select 1 from public.completions completion
          where completion.user_id = v_user_id
            and completion.plan_session_id = session.id
        );

      if (
        select pg_catalog.count(*)
        from public.plan_generation_replaceable_sessions
        where request_id = v_receipt.generation_id and user_id = v_user_id
      ) <> pg_catalog.cardinality(v_replaceable) then
        raise exception using
          errcode = 'PT409',
          message = 'Your plan changed. Reload and try again.';
      end if;
    end if;
  exception
    when unique_violation then
      -- The race loser. The winner's row is committed and visible now, so this
      -- is a replay that arrived simultaneously rather than sequentially, and
      -- it is answered exactly as a sequential replay would be.
      select * into v_existing
      from public.plan_generation_requests
      where user_id = v_user_id and idempotency_key = p_idempotency_key;
      if not found then
        raise exception using
          errcode = 'PT409',
          message = 'Your plan changed. Reload and try again.';
      end if;
      if v_existing.request_fingerprint is distinct from p_request_fingerprint then
        raise exception using
          errcode = 'PT409',
          message = 'That coaching request changed. Reload and try again.';
      end if;
      return (
        v_existing.id,
        v_existing.completion_token,
        v_existing.status,
        v_existing.proposal_id
      )::public.plan_generation_receipt;
  end;

  return v_receipt;
end;
$$;


ALTER FUNCTION "public"."begin_plan_generation"("p_idempotency_key" "text", "p_request_fingerprint" "text", "p_start_date" "date", "p_day_count" integer, "p_expected_plan_revision" bigint, "p_planning_note" "text", "p_previous_proposal_id" "uuid", "p_regeneration_feedback" "text", "p_replaceable_session_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_roadmap_generation"("p_idempotency_key" "text", "p_request_fingerprint" "text", "p_start_date" "date", "p_end_date" "date", "p_expected_head_revision" bigint, "p_planning_note" "text" DEFAULT NULL::"text", "p_previous_proposal_id" "uuid" DEFAULT NULL::"uuid", "p_regeneration_feedback" "text" DEFAULT NULL::"text", "p_change_roadmap" boolean DEFAULT false) RETURNS "public"."roadmap_generation_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing public.roadmap_generation_requests;
  v_head_revision bigint;
  v_note text;
  v_feedback text;
  v_previous public.roadmap_proposals;
  v_previous_request public.roadmap_generation_requests;
  v_regeneration integer := 0;
  v_changes_roadmap boolean := false;
  v_receipt public.roadmap_generation_receipt;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (
    select 1 from public.profiles where user_id = v_user_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_idempotency_key is null
    or pg_catalog.char_length(p_idempotency_key) not between 16 and 128
    or p_request_fingerprint is null
    or pg_catalog.char_length(p_request_fingerprint) not between 16 and 256
    or p_start_date is null
    or p_end_date is null
    or p_expected_head_revision is null
    or p_expected_head_revision < 0
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap request.';
  end if;

  -- Decision 1: four to fifty-two weeks, and a start no earlier than the day
  -- before UTC today. The single day of slack is deliberate: the owner's local
  -- today can legitimately be one day behind or ahead of the server's.
  if p_start_date < (v_now at time zone 'utc')::date - 1
    or p_end_date < p_start_date + 27
    or p_end_date > p_start_date + 365
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap request.';
  end if;

  v_note := public.roadmap_normalize_owner_text(p_planning_note);
  if v_note = '' then v_note := null; end if;
  v_feedback := public.roadmap_normalize_owner_text(p_regeneration_feedback);
  if v_feedback = '' then v_feedback := null; end if;

  if v_note is not null and pg_catalog.char_length(v_note) > 1000 then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap request.';
  end if;
  if v_feedback is not null and pg_catalog.char_length(v_feedback) > 500 then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap request.';
  end if;

  -- Same key, same fingerprint replays the claim, returning the stored status —
  -- pending, completed, or failed — and never 'claimed'. That is the whole
  -- discriminator: only the fresh insert below reports 'claimed', so only the
  -- caller that actually opened the attempt invokes the provider. A different
  -- fingerprint under the same key is a conflict, not a silent second call.
  select * into v_existing
  from public.roadmap_generation_requests
  where user_id = v_user_id
    and idempotency_key = p_idempotency_key;

  if found then
    if v_existing.request_fingerprint is distinct from p_request_fingerprint then
      raise exception using
        errcode = 'PT409',
        message = 'That coaching request changed. Reload and try again.';
    end if;
    return (
      v_existing.id,
      v_existing.completion_token,
      v_existing.status,
      v_existing.regeneration_number,
      v_existing.proposal_id
    )::public.roadmap_generation_receipt;
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62005,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
  end;

  select coalesce(revision, 0) into v_head_revision
  from public.roadmap_heads
  where user_id = v_user_id;
  v_head_revision := coalesce(v_head_revision, 0);

  if v_head_revision <> p_expected_head_revision then
    raise exception using
      errcode = 'PT409',
      message = 'Your roadmap changed. Reload and try again.';
  end if;

  if p_previous_proposal_id is null then
    -- An initial request carries no feedback at all.
    if v_feedback is not null then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap request.';
    end if;
    v_regeneration := 0;
    -- ADR-028. A request to change the roadmap in force says so, and there has
    -- to be one. Whether there is one is read here, never taken from the caller.
    v_changes_roadmap := coalesce(p_change_roadmap, false);
    if v_changes_roadmap and not exists (
      select 1 from public.roadmap_heads
      where user_id = v_user_id and current_version_id is not null
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap request.';
    end if;
  else
    -- A regeneration needs an owned, rejected immediate predecessor, the same
    -- horizon, and non-empty feedback. The ceiling is enforced here, before any
    -- provider call, because a fourth round must cost nothing.
    if v_feedback is null then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap request.';
    end if;

    select * into v_previous
    from public.roadmap_proposals
    where id = p_previous_proposal_id
      and user_id = v_user_id;

    if not found then
      raise exception using
        errcode = 'PT409',
        message = 'That proposal is no longer available.';
    end if;

    if not exists (
      select 1
      from public.roadmap_proposal_decisions
      where proposal_id = v_previous.id
        and user_id = v_user_id
        and decision = 'rejected'
    ) then
      raise exception using
        errcode = 'PT409',
        message = 'Decline that proposal before asking for another.';
    end if;

    select * into v_previous_request
    from public.roadmap_generation_requests
    where id = v_previous.generation_request_id
      and user_id = v_user_id;

    if not found
      or v_previous_request.requested_start_date <> p_start_date
      or v_previous_request.requested_end_date <> p_end_date
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap request.';
    end if;

    -- Asked again under the roadmap its predecessor was made under, or not
    -- at all: otherwise the coach is sent a newer roadmap beside an outline
    -- made from an older one (15 Oct 2026).
    if v_previous_request.expected_head_revision <> v_head_revision then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
    end if;

    v_regeneration := v_previous_request.regeneration_number + 1;
    -- Another answer to a change request is a change request: inherited from
    -- the predecessor, whatever the caller sent.
    v_changes_roadmap := v_previous_request.changes_roadmap;
    if v_regeneration > 3 then
      raise exception using
        errcode = 'PT429',
        message = 'This roadmap has reached its regeneration limit.';
    end if;
  end if;

  begin
    insert into public.roadmap_generation_requests (
      user_id,
      idempotency_key,
      request_fingerprint,
      requested_start_date,
      requested_end_date,
      expected_head_revision,
      previous_proposal_id,
      regeneration_number,
      planning_note_hash,
      regeneration_feedback_hash,
      changes_roadmap,
      status,
      created_at,
      updated_at
    )
    values (
      v_user_id,
      p_idempotency_key,
      p_request_fingerprint,
      p_start_date,
      p_end_date,
      p_expected_head_revision,
      p_previous_proposal_id,
      v_regeneration,
      public.roadmap_owner_text_hash(v_note),
      public.roadmap_owner_text_hash(v_feedback),
      v_changes_roadmap,
      'pending',
      v_now,
      v_now
    )
    -- The row is stored 'pending'; the receipt reports 'claimed'. Only this path
    -- runs for the caller that won the insert, so 'claimed' is the one state that
    -- authorizes a provider call. A replay above returns the stored 'pending'
    -- instead, and stops.
    returning id, completion_token, 'claimed', regeneration_number, proposal_id
    into v_receipt;
  exception
    when unique_violation then
      -- M3-09. The key was claimed by a concurrent caller between this
      -- transaction's replay read and its insert. That is a replay, not a
      -- failure, and it is answered exactly as the sequential replay above is:
      -- the fingerprint decides, and the stored receipt is returned unchanged.
      -- The stored status can only be 'pending' here, so this path never
      -- reports 'claimed' and never authorizes a second provider call.
      select * into v_existing
      from public.roadmap_generation_requests
      where user_id = v_user_id
        and idempotency_key = p_idempotency_key;

      if not found then
        -- The violation was not this key's. Nothing about it is understood, so
        -- nothing is claimed about it either.
        raise;
      end if;

      if v_existing.request_fingerprint is distinct from p_request_fingerprint
      then
        raise exception using
          errcode = 'PT409',
          message = 'That coaching request changed. Reload and try again.';
      end if;

      return (
        v_existing.id,
        v_existing.completion_token,
        v_existing.status,
        v_existing.regeneration_number,
        v_existing.proposal_id
      )::public.roadmap_generation_receipt;
  end;

  return v_receipt;
end;
$$;


ALTER FUNCTION "public"."begin_roadmap_generation"("p_idempotency_key" "text", "p_request_fingerprint" "text", "p_start_date" "date", "p_end_date" "date", "p_expected_head_revision" bigint, "p_planning_note" "text", "p_previous_proposal_id" "uuid", "p_regeneration_feedback" "text", "p_change_roadmap" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_session_activity_generation"("p_idempotency_key" "text", "p_request_fingerprint" "text", "p_session_id" "uuid", "p_expected_plan_revision" bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "public"."plan_generation_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing public.session_activity_requests;
  v_session public.rolling_plan_sessions;
  v_note text;
  v_receipt public.plan_generation_receipt;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (select 1 from public.profiles where user_id = v_user_id) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_idempotency_key is null
    or pg_catalog.char_length(p_idempotency_key) not between 16 and 128
    or p_request_fingerprint is null
    or pg_catalog.char_length(p_request_fingerprint) not between 16 and 256
    or p_session_id is null
    or p_expected_plan_revision is null
    or p_expected_plan_revision < 0
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity request.';
  end if;

  v_note := public.roadmap_normalize_owner_text(p_note);
  if v_note = '' then v_note := null; end if;
  if v_note is not null and pg_catalog.char_length(v_note) > 500 then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity request.';
  end if;

  -- Replay first, so a repeated request for a session that has since been
  -- deleted or passed still answers with what it already did.
  select * into v_existing
  from public.session_activity_requests
  where user_id = v_user_id and idempotency_key = p_idempotency_key;

  if found then
    if v_existing.request_fingerprint is distinct from p_request_fingerprint then
      raise exception using
        errcode = 'PT409',
        message = 'That coaching request changed. Reload and try again.';
    end if;
    return (
      v_existing.id,
      v_existing.completion_token,
      v_existing.status,
      v_existing.proposal_id
    )::public.plan_generation_receipt;
  end if;

  select * into v_session
  from public.rolling_plan_sessions
  where id = p_session_id and user_id = v_user_id;

  -- Another owner's session and no session at all are the same answer.
  if not found or v_session.status <> 'active' then
    raise exception using
      errcode = 'PT409',
      message = 'That session is no longer available.';
  end if;

  -- Logged session: its activities can no longer be saved, so the coach is
  -- not asked. The same answer as a session that is gone, because for
  -- planning it is. This is asked once, when the request is claimed:
  -- `finish_session_activity_generation` does not ask again, so a log
  -- written while the coach is answering still costs that one call and
  -- leaves a suggestion open. Accepting it is an `edit`, refused by the rule
  -- above; Dismiss clears it. A suggestion already open when the session is
  -- logged stays open the same way.
  if exists (
    select 1 from public.completions completion
    where completion.user_id = v_user_id
      and completion.plan_session_id = v_session.id
  ) then
    raise exception using
      errcode = 'PT409',
      message = 'That session is no longer available.';
  end if;

  if v_session.local_date < (v_now at time zone 'utc')::date - 1 then
    raise exception using
      errcode = 'PT422',
      message = 'That session is already in the past.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62009,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  begin
    insert into public.session_activity_requests (
      user_id, idempotency_key, request_fingerprint, session_id, local_date,
      expected_plan_revision, note_hash, created_at, updated_at
    ) values (
      v_user_id, p_idempotency_key, p_request_fingerprint, v_session.id,
      v_session.local_date, p_expected_plan_revision,
      public.roadmap_owner_text_hash(v_note), v_now, v_now
    )
    returning id, completion_token, 'claimed', proposal_id into v_receipt;
  exception
    when unique_violation then
      -- The race loser: answered exactly as a sequential replay would be.
      select * into v_existing
      from public.session_activity_requests
      where user_id = v_user_id and idempotency_key = p_idempotency_key;
      if not found then
        raise exception using
          errcode = 'PT409',
          message = 'Your plan changed. Reload and try again.';
      end if;
      if v_existing.request_fingerprint is distinct from p_request_fingerprint then
        raise exception using
          errcode = 'PT409',
          message = 'That coaching request changed. Reload and try again.';
      end if;
      return (
        v_existing.id,
        v_existing.completion_token,
        v_existing.status,
        v_existing.proposal_id
      )::public.plan_generation_receipt;
  end;

  return v_receipt;
end;
$$;


ALTER FUNCTION "public"."begin_session_activity_generation"("p_idempotency_key" "text", "p_request_fingerprint" "text", "p_session_id" "uuid", "p_expected_plan_revision" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."completion_activities_reject_immutable_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.user_id is distinct from old.user_id
    or new.completion_id is distinct from old.completion_id
  then
    raise exception using errcode = '42501',
      message = 'A completed activity cannot change owner or completion.';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."completion_activities_reject_immutable_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."completion_activity_input_is_valid"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_position numeric;
  v_planned numeric;
  v_mode text;
begin
  if p_value is null or pg_catalog.jsonb_typeof(p_value) <> 'object'
    or p_value - array[
      'personalActivityId', 'position', 'plannedPosition', 'name', 'sport',
      'instructions', 'measurementMode', 'actualMeasurement'
    ] <> '{}'::jsonb
    or not (p_value ?& array['position', 'name', 'sport', 'measurementMode'])
    or pg_catalog.jsonb_typeof(p_value->'position') <> 'number'
    or pg_catalog.jsonb_typeof(p_value->'name') <> 'string'
    or pg_catalog.jsonb_typeof(p_value->'sport') <> 'string'
    or pg_catalog.jsonb_typeof(p_value->'measurementMode') <> 'string'
  then return false; end if;

  v_position := (p_value->>'position')::numeric;
  v_mode := p_value->>'measurementMode';
  if v_position <> trunc(v_position) or v_position not between 0 and 99
    or pg_catalog.char_length(pg_catalog.btrim(p_value->>'name')) not between 1 and 120
    or pg_catalog.char_length(pg_catalog.btrim(p_value->>'sport')) not between 1 and 80
    or (p_value ? 'instructions'
      and pg_catalog.jsonb_typeof(p_value->'instructions') not in ('string', 'null'))
    or pg_catalog.char_length(coalesce(p_value->>'instructions', '')) > 2000
    or not public.is_training_measurement_mode(v_mode)
    -- An absent measurement and an explicit null mean the same thing: this
    -- activity records no measured value.
    or not public.is_valid_training_measurement(
      v_mode, nullif(p_value->'actualMeasurement', 'null'::jsonb))
  then return false; end if;

  if p_value ? 'plannedPosition'
    and pg_catalog.jsonb_typeof(p_value->'plannedPosition') <> 'null'
  then
    if pg_catalog.jsonb_typeof(p_value->'plannedPosition') <> 'number' then
      return false;
    end if;
    v_planned := (p_value->>'plannedPosition')::numeric;
    if v_planned <> trunc(v_planned) or v_planned not between 0 and 99 then
      return false;
    end if;
  end if;

  if p_value ? 'personalActivityId'
    and pg_catalog.jsonb_typeof(p_value->'personalActivityId') <> 'null'
  then
    if pg_catalog.jsonb_typeof(p_value->'personalActivityId') <> 'string' then
      return false;
    end if;
    perform (p_value->>'personalActivityId')::uuid;
  end if;
  return true;
exception when others then return false;
end;
$$;


ALTER FUNCTION "public"."completion_activity_input_is_valid"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."completion_input_is_valid"("p_value" "jsonb", "p_operation" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
  v_key text;
  v_number numeric;
  v_activity jsonb;
  v_positions integer[] := array[]::integer[];
begin
  if p_value is null or pg_catalog.jsonb_typeof(p_value) <> 'object'
    or p_value - (case when p_operation = 'create' then array[
        'planSessionId', 'status', 'actualLocalDate', 'actualStartedAt',
        'durationMinutes', 'perceivedEffort', 'note',
        'replacementDescription', 'painReported', 'illnessReported',
        'injuryReported', 'severeFatigueReported', 'activities', 'title', 'sport',
        'replacedByCompletionId', 'replacement'
      ] else array[
        'status', 'actualLocalDate', 'actualStartedAt', 'durationMinutes',
        'perceivedEffort', 'note', 'replacementDescription',
        'painReported', 'illnessReported', 'injuryReported',
        'severeFatigueReported', 'activities', 'title', 'sport',
        'replacedByCompletionId', 'replacement'
      ] end) <> '{}'::jsonb
    or not (p_value ?& array['status', 'actualLocalDate'])
    or pg_catalog.jsonb_typeof(p_value->'status') <> 'string'
    or pg_catalog.jsonb_typeof(p_value->'actualLocalDate') <> 'string'
  then return false; end if;

  v_status := p_value->>'status';
  -- The vocabulary is exactly these five. `rest` is not one of them: a
  -- recovery intention is a day-level planning label, not a completion.
  if v_status not in (
    'completed', 'partially_completed', 'skipped', 'replaced', 'unplanned'
  ) then return false; end if;
  if (p_value->>'actualLocalDate')::date::text <> p_value->>'actualLocalDate' then
    return false;
  end if;

  -- `unplanned` means exactly "no planned session", in both directions.
  if p_operation = 'create' then
    if (v_status = 'unplanned') <> (
      not (p_value ? 'planSessionId')
      or pg_catalog.jsonb_typeof(p_value->'planSessionId') = 'null'
    ) then return false; end if;
    if v_status <> 'unplanned' then
      if pg_catalog.jsonb_typeof(p_value->'planSessionId') <> 'string' then
        return false;
      end if;
      perform (p_value->>'planSessionId')::uuid;
    end if;
  end if;

  -- `replaced` means exactly "this points at what was done instead": either
  -- the unplanned log it names, or one written in the same call. Exactly one,
  -- and neither on any other outcome. A4d replaced the old rule, under which
  -- the pointer was a line of text; that text is now optional, is admitted
  -- only beside `replaced`, and survives so a log written before the link
  -- keeps what the owner typed.
  if (v_status = 'replaced') <> (
    p_value ? 'replacedByCompletionId' or p_value ? 'replacement'
  ) then return false; end if;
  if p_value ? 'replacedByCompletionId' and p_value ? 'replacement' then
    return false;
  end if;
  if p_value ? 'replacedByCompletionId' then
    if pg_catalog.jsonb_typeof(p_value->'replacedByCompletionId') <> 'string' then
      return false;
    end if;
    perform (p_value->>'replacedByCompletionId')::uuid;
  end if;
  -- Only the shape is judged here. The recursive create that writes it runs
  -- this validator again as unplanned training, which judges the contents.
  if p_value ? 'replacement' and (
    pg_catalog.jsonb_typeof(p_value->'replacement') <> 'object'
    or (p_value->'replacement') - array[
      'title', 'sport', 'durationMinutes', 'perceivedEffort',
      'activities'
    ] <> '{}'::jsonb
    or not ((p_value->'replacement') ?& array['title', 'sport', 'activities'])
  ) then return false; end if;
  if p_value ? 'replacementDescription'
    and pg_catalog.jsonb_typeof(p_value->'replacementDescription') <> 'null'
    and (
      v_status <> 'replaced'
      or pg_catalog.jsonb_typeof(p_value->'replacementDescription') <> 'string'
      or pg_catalog.char_length(
        pg_catalog.btrim(p_value->>'replacementDescription')) not between 1 and 500
    )
  then return false; end if;

  -- A log's own name, both halves or neither. Absent on a create means the
  -- write function supplies one; absent on an edit leaves the stored one.
  if (p_value ? 'title') <> (p_value ? 'sport') then return false; end if;
  if p_value ? 'title' and (
    pg_catalog.jsonb_typeof(p_value->'title') <> 'string'
    or pg_catalog.jsonb_typeof(p_value->'sport') <> 'string'
    or pg_catalog.char_length(pg_catalog.btrim(p_value->>'title'))
      not between 1 and 120
    or pg_catalog.char_length(pg_catalog.btrim(p_value->>'sport'))
      not between 1 and 80
  ) then return false; end if;

  if p_value ? 'actualStartedAt'
    and pg_catalog.jsonb_typeof(p_value->'actualStartedAt') <> 'null'
  then
    if pg_catalog.jsonb_typeof(p_value->'actualStartedAt') <> 'string' then
      return false;
    end if;
    perform (p_value->>'actualStartedAt')::timestamptz;
  end if;

  foreach v_key in array array['durationMinutes', 'perceivedEffort'] loop
    if p_value ? v_key and pg_catalog.jsonb_typeof(p_value->v_key) <> 'null' then
      if pg_catalog.jsonb_typeof(p_value->v_key) <> 'number' then
        return false;
      end if;
      v_number := (p_value->>v_key)::numeric;
      if v_number <> trunc(v_number)
        or (v_key = 'durationMinutes' and v_number not between 0 and 10080)
        or (v_key = 'perceivedEffort' and v_number not between 1 and 10)
      then return false; end if;
    end if;
  end loop;

  if p_value ? 'note'
    and pg_catalog.jsonb_typeof(p_value->'note') not in ('string', 'null')
  then return false; end if;
  if pg_catalog.char_length(coalesce(p_value->>'note', '')) > 2000 then
    return false;
  end if;

  foreach v_key in array array[
    'painReported', 'illnessReported', 'injuryReported', 'severeFatigueReported'
  ] loop
    if p_value ? v_key
      and pg_catalog.jsonb_typeof(p_value->v_key) not in ('boolean', 'null')
    then return false; end if;
  end loop;

  -- A create states the whole list, including an empty one. An edit states it
  -- only to replace it; leaving the key out leaves the activities alone.
  if p_operation = 'create' and not (p_value ? 'activities') then
    return false;
  end if;
  if p_value ? 'activities' then
    if pg_catalog.jsonb_typeof(p_value->'activities') <> 'array'
      or pg_catalog.jsonb_array_length(p_value->'activities') > 50
    then return false; end if;
    for v_activity in
      select value from pg_catalog.jsonb_array_elements(p_value->'activities')
    loop
      if not public.completion_activity_input_is_valid(v_activity) then
        return false;
      end if;
      if (v_activity->>'position')::integer = any(v_positions) then
        return false;
      end if;
      v_positions := v_positions || (v_activity->>'position')::integer;
    end loop;
  end if;
  return true;
exception when others then return false;
end;
$$;


ALTER FUNCTION "public"."completion_input_is_valid"("p_value" "jsonb", "p_operation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."completions_reject_immutable_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.user_id is distinct from old.user_id then
    raise exception using errcode = '42501',
      message = 'A completion owner cannot be reassigned.';
  end if;
  if new.plan_session_id is distinct from old.plan_session_id
    or new.planned_snapshot is distinct from old.planned_snapshot
    or new.timezone_name is distinct from old.timezone_name
  then
    raise exception using errcode = '42501',
      message = 'What a completion was measured against cannot be rewritten.';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."completions_reject_immutable_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_goal_suggestion"("p_suggestion_id" "uuid", "p_decision" "text", "p_priority_tier" "text" DEFAULT NULL::"text", "p_expected_goal_revision" bigint DEFAULT NULL::bigint) RETURNS "public"."goal_suggestion_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_suggestion public.goal_suggestions;
  v_receipt public.goal_change_receipt;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_today date;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_suggestion_id is null
    or p_decision is null
    or p_decision not in ('accept', 'reject')
    or (p_decision = 'accept' and (
      p_priority_tier is null
      or p_priority_tier not in ('core', 'supporting')
      or p_expected_goal_revision is null
    ))
    or (p_decision = 'reject' and p_priority_tier is not null)
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid goal suggestion decision.';
  end if;

  select * into v_suggestion
  from public.goal_suggestions
  where id = p_suggestion_id and user_id = v_user_id
  for update;

  if not found or v_suggestion.status <> 'proposed' then
    raise exception using
      errcode = 'PT409',
      message = 'That suggestion is no longer open.';
  end if;

  if p_decision = 'reject' then
    update public.goal_suggestions
    set status = 'rejected', decided_at = v_now
    where id = v_suggestion.id and user_id = v_user_id;
    return (v_suggestion.id, 'rejected', null::uuid, null::bigint)
      ::public.goal_suggestion_receipt;
  end if;

  -- A target date that has passed while the suggestion waited is no target:
  -- the goal is created without one rather than with a date already gone.
  select coalesce(
    (pg_catalog.timezone(profile.timezone_name, v_now))::date,
    (v_now at time zone 'utc')::date
  )
  into v_today
  from public.profiles profile
  where profile.user_id = v_user_id;

  v_receipt := public.apply_goal_change(
    p_expected_goal_revision, 'create', null,
    v_suggestion.title, v_suggestion.desired_outcome, v_suggestion.sports,
    case when v_suggestion.target_date >= v_today
      then v_suggestion.target_date end,
    p_priority_tier, null, null
  );

  update public.goal_suggestions
  set status = 'accepted', goal_id = v_receipt.goal_id, decided_at = v_now
  where id = v_suggestion.id and user_id = v_user_id;

  return (
    v_suggestion.id, 'accepted', v_receipt.goal_id,
    v_receipt.collection_revision
  )::public.goal_suggestion_receipt;
end;
$$;


ALTER FUNCTION "public"."decide_goal_suggestion"("p_suggestion_id" "uuid", "p_decision" "text", "p_priority_tier" "text", "p_expected_goal_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_plan_proposal_item"("p_proposal_id" "uuid", "p_ordinal" integer, "p_decision" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_proposal_id is null
    or p_ordinal is null
    or p_ordinal not between 0 and 47
    or p_decision is null
    or p_decision not in ('staged', 'staged_beside', 'rejected', 'proposed')
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan proposal decision.';
  end if;

  if not exists (
    select 1 from public.plan_proposal_items
    where proposal_id = p_proposal_id
      and ordinal = p_ordinal::smallint
      and user_id = v_user_id
  ) then
    raise exception using
      errcode = 'PT409',
      message = 'That proposed item is no longer available.';
  end if;

  -- The same lock the finish and the discard take. Without it, a choice made in
  -- one tab could read "not finished" just before another tab's finish
  -- committed, and then write after it — leaving the permanent record saying an
  -- item was staged that never entered the plan. Held, the terminal-row check
  -- below cannot be overtaken, and the finish sees a stable set of choices.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62008,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  if exists (
    select 1 from public.plan_proposal_decisions
    where proposal_id = p_proposal_id and user_id = v_user_id
  ) then
    raise exception using
      errcode = 'PT433',
      message = 'That review is already finished.';
  end if;

  -- "Add beside" is a choice about the session an item would replace, so an
  -- item that replaces nothing does not have it, and neither does a suggested
  -- cancel: there is nothing to add (ADR-033).
  if p_decision = 'staged_beside' and not exists (
    select 1 from public.plan_proposal_items
    where proposal_id = p_proposal_id
      and ordinal = p_ordinal::smallint
      and user_id = v_user_id
      and kind = 'session'
      and replaces_session_id is not null
  ) then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan proposal decision.';
  end if;

  if p_decision = 'proposed' then
    delete from public.plan_proposal_item_decisions
    where proposal_id = p_proposal_id
      and ordinal = p_ordinal::smallint
      and user_id = v_user_id;
    return;
  end if;

  insert into public.plan_proposal_item_decisions (
    proposal_id, ordinal, user_id, decision, decided_at
  ) values (
    p_proposal_id, p_ordinal::smallint, v_user_id, p_decision,
    pg_catalog.clock_timestamp()
  )
  on conflict (proposal_id, ordinal) do update
  set decision = excluded.decision, decided_at = excluded.decided_at;
end;
$$;


ALTER FUNCTION "public"."decide_plan_proposal_item"("p_proposal_id" "uuid", "p_ordinal" integer, "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_session_activity_proposal"("p_proposal_id" "uuid", "p_decision" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_existing text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_proposal_id is null
    or p_decision is null
    or p_decision not in ('accepted', 'dismissed')
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity decision.';
  end if;

  if not exists (
    select 1
    from public.session_activity_proposals
    where id = p_proposal_id and user_id = v_user_id
  ) then
    raise exception using
      errcode = 'PT409',
      message = 'That proposal is no longer available.';
  end if;

  insert into public.session_activity_decisions (proposal_id, user_id, decision)
  values (p_proposal_id, v_user_id, p_decision)
  on conflict (proposal_id) do nothing;

  select decision into v_existing
  from public.session_activity_decisions
  where proposal_id = p_proposal_id and user_id = v_user_id;

  if v_existing is distinct from p_decision then
    raise exception using
      errcode = 'PT433',
      message = 'That proposal is already decided.';
  end if;

  return v_existing;
end;
$$;


ALTER FUNCTION "public"."decide_session_activity_proposal"("p_proposal_id" "uuid", "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_my_account"("p_confirmation" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  -- The application asks for the word first; this is the backstop.
  if p_confirmation is distinct from 'DELETE' then
    raise exception using errcode = '22023',
      message = 'Type DELETE to delete your account.';
  end if;

  -- One account deletion at a time, and a write racing it fails on the lock
  -- or on the missing profile rather than leaving a row behind.
  perform 1 from public.profiles where user_id = v_user_id for update;

  delete from public.completions where user_id = v_user_id;
  delete from public.plan_proposal_decisions where user_id = v_user_id;
  delete from public.goal_lifecycle_events where user_id = v_user_id;

  -- An item names its current revision and each revision its previous one;
  -- both links are deferrable, so the pair is checked once both are gone.
  set constraints public.memory_items_current_revision_fkey,
    public.memory_revisions_previous_fkey deferred;
  delete from public.memory_items where user_id = v_user_id;

  delete from public.rolling_plans where user_id = v_user_id;
  delete from public.saved_sessions where user_id = v_user_id;

  delete from auth.users where id = v_user_id;
end;
$$;


ALTER FUNCTION "public"."delete_my_account"("p_confirmation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_my_account"("p_confirmation" "text") IS 'ADR-039: deletes the calling user''s account and every row they own. Owner from auth.uid() only.';



CREATE OR REPLACE FUNCTION "public"."delete_roadmap"("p_version_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_current uuid;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_version_id is null then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62005,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
  end;

  select head.current_version_id into v_current
  from public.roadmap_heads head
  where head.user_id = v_user_id
  for update;

  if not found then
    return 'replayed';
  end if;

  if v_current <> p_version_id then
    raise exception using
      errcode = 'PT409',
      message = 'Your roadmap changed. Reload and try again.';
  end if;

  -- Children first, so no cascade decides what goes. Every statement is held
  -- to the caller's own rows.
  delete from public.roadmap_heads where user_id = v_user_id;
  delete from public.roadmap_milestone_marks where user_id = v_user_id;
  delete from public.roadmap_review_marks where user_id = v_user_id;
  delete from public.roadmap_proposal_decisions where user_id = v_user_id;
  delete from public.roadmap_versions where user_id = v_user_id;
  delete from public.roadmap_proposal_sources where user_id = v_user_id;
  delete from public.roadmap_proposals where user_id = v_user_id;
  delete from public.roadmap_generation_requests where user_id = v_user_id;

  return 'deleted';
end;
$$;


ALTER FUNCTION "public"."delete_roadmap"("p_version_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discard_plan_proposal"("p_proposal_id" "uuid") RETURNS "public"."plan_review_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_existing public.plan_proposal_decisions;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_proposal_id is null then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan review.';
  end if;

  if not exists (
    select 1 from public.plan_proposals
    where id = p_proposal_id and user_id = v_user_id
  ) then
    raise exception using
      errcode = 'PT409',
      message = 'That proposal is no longer available.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62008,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  select * into v_existing
  from public.plan_proposal_decisions
  where proposal_id = p_proposal_id and user_id = v_user_id;
  if found then
    if v_existing.decision <> 'discarded' then
      raise exception using
        errcode = 'PT433',
        message = 'That review is already finished.';
    end if;
    return (
      v_existing.proposal_id, v_existing.decision, v_existing.applied_count,
      v_existing.change_set_id, v_existing.plan_revision, 'replayed'
    )::public.plan_review_receipt;
  end if;

  insert into public.plan_proposal_decisions (
    proposal_id, user_id, decision, applied_count, decided_at
  ) values (
    p_proposal_id, v_user_id, 'discarded', 0, pg_catalog.clock_timestamp()
  );

  return (p_proposal_id, 'discarded', 0::smallint, null::uuid, null::bigint, 'discarded')
    ::public.plan_review_receipt;
end;
$$;


ALTER FUNCTION "public"."discard_plan_proposal"("p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."edit_roadmap"("p_content" "jsonb", "p_expected_head_revision" bigint) RETURNS "public"."roadmap_acceptance_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_today date;
  v_start date;
  v_end date;
  v_head public.roadmap_heads;
  v_old jsonb;
  v_replay record;
  v_proposal_id uuid;
  v_receipt public.roadmap_acceptance_receipt;
  v_locked integer := 0;
  v_count integer;
  v_mark record;
  v_old_milestone jsonb;
  v_target record;
  v_used text[] := array[]::text[];
  v_review record;
  v_reviewed_phase integer;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  -- Today where the owner is, from the confirmed time zone, and UTC's where
  -- none is confirmed: the day that decides which phases have ended.
  select (pg_catalog.timezone(
    coalesce(profile.timezone_name, 'UTC'), v_now
  ))::date into v_today
  from public.profiles profile
  where profile.user_id = v_user_id;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_content is null
    or pg_catalog.jsonb_typeof(p_content) <> 'object'
    or p_expected_head_revision is null
    or p_expected_head_revision < 1
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  begin
    v_start := (p_content->>'startDate')::date;
    v_end := (p_content->>'endDate')::date;
  exception
    when others then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap.';
  end;

  if v_start is null
    or v_end is null
    or v_end < v_today
    or v_end < v_start + 27
    or v_end > v_start + 365
    or not public.roadmap_content_is_valid(p_content, v_start, v_end)
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62005,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
  end;

  select * into v_head
  from public.roadmap_heads
  where user_id = v_user_id;

  if coalesce(v_head.revision, 0) <> p_expected_head_revision then
    -- The same change, in force one revision on: this edit has already
    -- landed.
    select proposal.id as proposal_id, version.id as version_id
    into v_replay
    from public.roadmap_versions version
    join public.roadmap_proposals proposal
      on proposal.id = version.source_proposal_id
      and proposal.user_id = version.user_id
    where version.user_id = v_user_id
      and version.id = v_head.current_version_id
      and v_head.revision = p_expected_head_revision + 1
      and proposal.origin = 'owner_written'
      and proposal.content = p_content;

    if found then
      return (
        v_replay.proposal_id, v_replay.version_id, v_head.revision, 'replayed'
      )::public.roadmap_acceptance_receipt;
    end if;

    raise exception using
      errcode = 'PT409',
      message = 'Your roadmap changed. Reload and try again.';
  end if;

  select version.content into v_old
  from public.roadmap_versions version
  where version.id = v_head.current_version_id
    and version.user_id = v_user_id;

  -- One refusal for everything about the past, as for the content: the
  -- application has said what is wrong before this is reached.
  if not found
    or (v_old->>'startDate')::date is distinct from v_start
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  -- Every phase that has ended comes back as it was. Phases are contiguous
  -- and in order, so the ended ones are the first few.
  v_count := pg_catalog.jsonb_array_length(v_old->'phases');
  while v_locked < v_count
    and ((v_old->'phases'->v_locked->>'endDate')::date) < v_today
  loop
    if (p_content->'phases'->v_locked) is distinct from
       (v_old->'phases'->v_locked)
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap.';
    end if;
    v_locked := v_locked + 1;
  end loop;

  -- A roadmap that has ended is over, not edited: a new one replaces it.
  if v_locked = v_count then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  -- The phase after them keeps its start, and nothing not locked ends before
  -- today: either would rewrite days that have passed.
  if v_locked < v_count
    and (p_content->'phases'->v_locked->>'startDate')
      is distinct from (v_old->'phases'->v_locked->>'startDate')
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;
  -- Each phase after it starts the day after the one before ends, so none
  -- reaches back over what has passed: the content check alone holds the
  -- dates inside the roadmap, not their order.
  for v_index in
    v_locked .. pg_catalog.jsonb_array_length(p_content->'phases') - 1
  loop
    if ((p_content->'phases'->v_index->>'endDate')::date) < v_today
      or (
        v_index > v_locked
        and ((p_content->'phases'->v_index->>'startDate')::date)
          is distinct from
          ((p_content->'phases'->(v_index - 1)->>'endDate')::date) + 1
      )
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap.';
    end if;
  end loop;

  insert into public.roadmap_proposals (
    user_id, origin, schema_version, content, created_at
  )
  values (
    v_user_id, 'owner_written', p_content->>'schemaVersion', p_content, v_now
  )
  returning id into v_proposal_id;

  -- The version, the head and the decision, by the one path that writes them.
  -- The advisory lock is the transaction's already.
  v_receipt := public.accept_roadmap_proposal(
    v_proposal_id, p_expected_head_revision
  );

  -- A tick goes to the first unchanged milestone not already given one: the
  -- same title and the same date, in any phase. One that changed starts
  -- unticked (owner, 14 Oct 2026).
  for v_mark in
    select phase_index, milestone_index, reached_on
    from public.roadmap_milestone_marks
    where version_id = v_head.current_version_id and user_id = v_user_id
    order by phase_index, milestone_index
  loop
    v_old_milestone :=
      v_old->'phases'->v_mark.phase_index->'milestones'->v_mark.milestone_index;
    if v_old_milestone is null then
      continue;
    end if;

    select phase.ordinality - 1 as phase_index,
      milestone.ordinality - 1 as milestone_index
    into v_target
    from pg_catalog.jsonb_array_elements(p_content->'phases')
      with ordinality as phase (value, ordinality)
    cross join lateral pg_catalog.jsonb_array_elements(phase.value->'milestones')
      with ordinality as milestone (value, ordinality)
    where milestone.value->>'title' = v_old_milestone->>'title'
      and milestone.value->>'targetDate' = v_old_milestone->>'targetDate'
      and not (
        ((phase.ordinality - 1)::text || ':' || (milestone.ordinality - 1)::text)
        = any (v_used)
      )
    order by phase.ordinality, milestone.ordinality
    limit 1;

    if found then
      v_used := v_used
        || (v_target.phase_index::text || ':' || v_target.milestone_index::text);
      insert into public.roadmap_milestone_marks (
        user_id, version_id, phase_index, milestone_index, reached_on
      )
      values (
        v_user_id, v_receipt.version_id, v_target.phase_index,
        v_target.milestone_index, v_mark.reached_on
      );
    end if;
  end loop;

  -- A done review stays with its phase. A phase reviewed on its last day and
  -- since lengthened is not over any more, so the mark falls back to the phase
  -- before it, which has ended and is locked.
  select phase_index, reviewed_on into v_review
  from public.roadmap_review_marks
  where version_id = v_head.current_version_id and user_id = v_user_id;

  if found then
    v_reviewed_phase := v_review.phase_index;
    if (p_content->'phases'->v_reviewed_phase->>'endDate')
      is distinct from (v_old->'phases'->v_reviewed_phase->>'endDate')
    then
      v_reviewed_phase := v_reviewed_phase - 1;
    end if;
    if v_reviewed_phase >= 0 then
      insert into public.roadmap_review_marks (
        version_id, user_id, phase_index, reviewed_on
      )
      values (
        v_receipt.version_id, v_user_id, v_reviewed_phase, v_review.reviewed_on
      );
    end if;
  end if;

  return v_receipt;
end;
$$;


ALTER FUNCTION "public"."edit_roadmap"("p_content" "jsonb", "p_expected_head_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_plan_generation"("p_completion_token" "uuid", "p_outcome" "text", "p_schema_version" "text" DEFAULT NULL::"text", "p_prompt_version" "text" DEFAULT NULL::"text", "p_provider_code" "text" DEFAULT NULL::"text", "p_model_code" "text" DEFAULT NULL::"text", "p_rate_card_version" "text" DEFAULT NULL::"text", "p_spend_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_planning_note" "text" DEFAULT NULL::"text", "p_content" "jsonb" DEFAULT NULL::"jsonb", "p_sources" "jsonb" DEFAULT NULL::"jsonb", "p_safe_failure_code" "text" DEFAULT NULL::"text", "p_regeneration_feedback" "text" DEFAULT NULL::"text") RETURNS "public"."plan_generation_result"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.plan_generation_requests;
  v_note text;
  v_feedback text;
  v_proposal_id uuid;
  v_source jsonb;
  v_ordinal smallint := 0;
  v_kind text;
  v_record uuid;
  v_plan_revision bigint;
  v_named text[];
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_completion_token is null
    or p_outcome is null
    or p_outcome not in ('proposal', 'failed')
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan result.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62007,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  select * into v_request
  from public.plan_generation_requests
  where user_id = v_user_id and completion_token = p_completion_token
  for update;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  -- Replay. An already finished request returns its recorded result when the
  -- caller repeats the same outcome, and conflicts when it does not: a second
  -- call must never overwrite what the first one persisted.
  if v_request.status <> 'pending' then
    if (v_request.status = 'completed' and p_outcome = 'proposal')
      or (v_request.status = 'failed' and p_outcome = 'failed'
          and v_request.failure_code is not distinct from p_safe_failure_code)
    then
      return (v_request.status, v_request.proposal_id)
        ::public.plan_generation_result;
    end if;
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is already finished.';
  end if;

  if p_outcome = 'failed' then
    if p_safe_failure_code is null
      or p_safe_failure_code !~ '^[a-z][a-z0-9_]{1,63}$'
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid plan result.';
    end if;
    update public.plan_generation_requests
    set status = 'failed', failure_code = p_safe_failure_code, updated_at = v_now
    where id = v_request.id and user_id = v_user_id;
    return ('failed', null)::public.plan_generation_result;
  end if;

  -- The planning note travels again on finish rather than being read back from
  -- the claim, which stores only its hash. The hash is what proves the text
  -- finish was given is the text begin claimed.
  v_note := public.roadmap_normalize_owner_text(p_planning_note);
  if v_note = '' then v_note := null; end if;

  -- The feedback travels again on finish for the reason the planning note
  -- does, and is proved the same way: the claim stored only a hash, so the
  -- hash is what shows this is the text the claim was made for.
  v_feedback := public.roadmap_normalize_owner_text(p_regeneration_feedback);
  if v_feedback = '' then v_feedback := null; end if;
  if public.roadmap_owner_text_hash(v_feedback)
     is distinct from v_request.regeneration_feedback_hash
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan result.';
  end if;
  if public.roadmap_owner_text_hash(v_note)
     is distinct from v_request.planning_note_hash
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan result.';
  end if;

  if p_schema_version is distinct from 'fittip.seven-day-plan.v2'
    or p_prompt_version is null
    or p_provider_code is null
    or p_model_code is null
    or p_rate_card_version is null
    or not public.plan_content_is_valid(
      p_content, v_request.requested_start_date, v_request.requested_end_date
    )
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan result.';
  end if;

  -- The provider, model and rate card must be a pairing somebody approved, and
  -- a live pairing must carry a reservation while the fixture one must not.
  -- This is what stops a paid call being recorded as a free fixture, and it is
  -- also what the owner-facing "example" label rests on: that label reads
  -- `provider_code`, so the database has to guarantee the code is honest. The
  -- function is the roadmap's; it names no operation, and M3-03's dropped plan
  -- migration used it the same way.
  if not public.roadmap_technical_codes_are_accepted(
    p_provider_code,
    p_model_code,
    p_rate_card_version,
    p_spend_reservation_id is not null
  ) then
    raise exception using
      errcode = '22023',
      message = 'That coaching model is not approved.';
  end if;

  -- A live result must carry a settled reservation belonging to this owner,
  -- for this operation, priced by the same rate card. Without it a proposal
  -- could point at another owner's reservation, or at one that paid for a
  -- roadmap.
  if p_spend_reservation_id is not null then
    -- Settled here, in the transaction that records the proposal, so the two
    -- commit together or neither does. Before this, a reservation the
    -- application failed to settle made the check below refuse a result the
    -- provider had already been paid for, and the proposal was thrown away.
    --
    -- The amount is what the reservation was holding, not the real usage: the
    -- real usage is known only to the caller that just failed to report it.
    -- Charging the ceiling is the conservative direction, and it applies only
    -- to runs where the settle had already gone wrong.
    update public.ai_spend_reservations
    set
      charged_micro_usd = reserved_micro_usd,
      settled_at = pg_catalog.now()
    where id = p_spend_reservation_id
      and user_id = v_user_id
      and operation = 'create_seven_day_plan'
      and rate_card_version = p_rate_card_version
      and settled_at is null;

    -- Asserted separately rather than from the update's row count, because a
    -- reservation the application settled normally matches no row above and is
    -- a perfectly good finish. What has to hold on every path is the same four
    -- things it always did, plus that the reservation is now closed.
    if not exists (
      select 1
      from public.ai_spend_reservations
      where id = p_spend_reservation_id
        and user_id = v_user_id
        and operation = 'create_seven_day_plan'
        and settled_at is not null
        and rate_card_version = p_rate_card_version
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid plan result.';
    end if;
  end if;

  -- The proposal this one replaces closes here, with its replacement, and
  -- not before the coach is asked (owner, 17 Oct 2026): a failed answer
  -- leaves it open, the owner's choices on it intact. What the owner had not
  -- decided is declined; what they accepted is applied by the review's own
  -- finish, so the rules about what an ending means stay in one place. One
  -- the owner finished or discarded while waiting is left as they left it.
  if v_request.previous_proposal_id is not null and not exists (
    select 1
    from public.plan_proposal_decisions
    where proposal_id = v_request.previous_proposal_id
      and user_id = v_user_id
  ) then
    insert into public.plan_proposal_item_decisions (
      proposal_id, ordinal, user_id, decision, decided_at
    )
    select item.proposal_id, item.ordinal, v_user_id, 'rejected', v_now
    from public.plan_proposal_items item
    where item.proposal_id = v_request.previous_proposal_id
      and item.user_id = v_user_id
    on conflict (proposal_id, ordinal) do nothing;

    select revision into v_plan_revision
    from public.rolling_plans
    where user_id = v_user_id;

    perform public.finish_plan_proposal_review(
      v_request.previous_proposal_id,
      coalesce(v_plan_revision, 0),
      p_completion_token
    );
  end if;

  insert into public.plan_proposals (
    user_id, generation_request_id, origin, planning_note, schema_version,
    prompt_version, provider_code, model_code, rate_card_version,
    spend_reservation_id, content, source_proposal_id, regeneration_feedback,
    created_at
  ) values (
    v_user_id, v_request.id,
    case when v_request.regeneration_number > 0
      then 'ai_regeneration' else 'ai_initial' end,
    v_note, p_schema_version,
    p_prompt_version, p_provider_code, p_model_code, p_rate_card_version,
    p_spend_reservation_id, p_content, v_request.previous_proposal_id,
    v_feedback, v_now
  )
  returning id into v_proposal_id;

  -- A proposed session may stand in for one the owner left open, and the
  -- coach may suggest cancelling one, each named by its handle (ADR-024,
  -- ADR-033). A handle this request never issued, or one named twice across
  -- both, refuses the whole answer, exactly as invalid content does: half a
  -- proposal is not something the owner asked for.
  select coalesce(pg_catalog.array_agg(named.handle), '{}'::text[])
  into v_named
  from (
    select proposed.value->>'replaces' as handle
    from pg_catalog.jsonb_array_elements(p_content->'sessions') as proposed(value)
    where nullif(proposed.value->>'replaces', '') is not null
    union all
    select cancel.value->>'replaceHandle'
    from pg_catalog.jsonb_array_elements(
      case when pg_catalog.jsonb_typeof(p_content->'cancels') = 'array'
        then p_content->'cancels' else '[]'::jsonb end
    ) as cancel(value)
  ) as named;

  if exists (
    select 1
    from pg_catalog.unnest(v_named) as named(handle)
    where not exists (
      select 1
      from public.plan_generation_replaceable_sessions marked
      where marked.request_id = v_request.id
        and marked.user_id = v_user_id
        and marked.handle = named.handle
    )
  ) or pg_catalog.cardinality(v_named) <> (
    select pg_catalog.count(distinct named.handle)
    from pg_catalog.unnest(v_named) as named(handle)
  ) then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan result.';
  end if;

  -- Items, in the order the surface reads them: by date, a suggested cancel
  -- before the sessions, then proposed sessions in the order the coach listed
  -- them. A cancel item carries the title of the session it names, as it was
  -- when the answer arrived, and the coach's reason as its rationale; one
  -- whose session is gone, cancelled or moved off those days since the
  -- request began is not offered. Only sessions: a free day is
  -- not offered as a recovery day (owner, 17 October 2026). `ordinal` is the
  -- owner's stable handle on a choice; `content_index` is the way back to the
  -- rest of what the coach said.
  insert into public.plan_proposal_items (
    proposal_id, ordinal, user_id, kind, content_index, session_id,
    local_date, title, sport, intent, expected_duration_minutes, rationale,
    replaces_session_id
  )
  select
    v_proposal_id,
    (pg_catalog.row_number() over (
      order by item.local_date, item.kind, item.content_index, item.replaces
    ) - 1)::smallint,
    v_user_id,
    item.kind,
    item.content_index,
    case when item.kind = 'session' then pg_catalog.gen_random_uuid() end,
    item.local_date,
    item.title,
    item.sport,
    item.intent,
    item.expected_duration_minutes,
    item.rationale,
    (
      select marked.session_id
      from public.plan_generation_replaceable_sessions marked
      where marked.request_id = v_request.id
        and marked.user_id = v_user_id
        and marked.handle = item.replaces
    )
  from (
    select
      'session' as kind,
      (session.ordinality - 1)::smallint as content_index,
      (session.value->>'date')::date as local_date,
      pg_catalog.btrim(session.value->>'title') as title,
      pg_catalog.btrim(session.value->>'sport') as sport,
      nullif(session.value->>'intent', '') as intent,
      (session.value->>'durationMinutes')::integer as expected_duration_minutes,
      pg_catalog.btrim(session.value->>'rationale') as rationale,
      nullif(session.value->>'replaces', '') as replaces
    from pg_catalog.jsonb_array_elements(p_content->'sessions')
      with ordinality as session(value, ordinality)
    union all
    select
      'cancel',
      null::smallint,
      target.local_date,
      target.title,
      null::text,
      null::text,
      null::integer,
      pg_catalog.btrim(cancel.value->>'reason'),
      cancel.value->>'replaceHandle'
    from pg_catalog.jsonb_array_elements(
      case when pg_catalog.jsonb_typeof(p_content->'cancels') = 'array'
        then p_content->'cancels' else '[]'::jsonb end
    ) as cancel(value)
    join public.plan_generation_replaceable_sessions marked
      on marked.request_id = v_request.id
      and marked.user_id = v_user_id
      and marked.handle = cancel.value->>'replaceHandle'
    join public.rolling_plan_sessions target
      on target.id = marked.session_id
      and target.user_id = v_user_id
    -- Only a session still active and still on the days asked about: the
    -- review shows those days alone, so an item dated elsewhere could never
    -- be decided and would hold the finish shut.
    where target.status = 'active'
      and target.local_date between v_request.requested_start_date
        and v_request.requested_end_date
  ) as item;

  -- Minimized provenance. Ids and revisions only; no copied source content.
  if p_sources is not null then
    if pg_catalog.jsonb_typeof(p_sources) <> 'array'
      or pg_catalog.jsonb_array_length(p_sources) > 256
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid plan result.';
    end if;
    for v_source in select value from pg_catalog.jsonb_array_elements(p_sources) loop
      v_kind := v_source->>'kind';
      if v_kind is null
        or v_kind not in (
          'goal', 'memory', 'plan_session', 'completion', 'roadmap_version'
        )
      then
        raise exception using
          errcode = '22023',
          message = 'Invalid plan result.';
      end if;
      begin
        v_record := (v_source->>'recordId')::uuid;
      exception when others then
        raise exception using
          errcode = '22023',
          message = 'Invalid plan result.';
      end;
      insert into public.plan_proposal_sources (
        proposal_id, ordinal, user_id, source_kind, record_id,
        revision_id, revision_number
      ) values (
        v_proposal_id, v_ordinal, v_user_id, v_kind, v_record,
        case
          when pg_catalog.jsonb_typeof(v_source->'revisionId') = 'string'
          then (v_source->>'revisionId')::uuid
        end,
        case
          when pg_catalog.jsonb_typeof(v_source->'revisionNumber') = 'number'
          then (v_source->>'revisionNumber')::bigint
        end
      );
      v_ordinal := v_ordinal + 1;
    end loop;
  end if;

  update public.plan_generation_requests
  set status = 'completed', proposal_id = v_proposal_id, updated_at = v_now
  where id = v_request.id and user_id = v_user_id;

  return ('completed', v_proposal_id)::public.plan_generation_result;
exception
  when check_violation or invalid_datetime_format or invalid_text_representation then
    raise exception using errcode = '22023', message = 'Invalid plan result.';
end;
$_$;


ALTER FUNCTION "public"."finish_plan_generation"("p_completion_token" "uuid", "p_outcome" "text", "p_schema_version" "text", "p_prompt_version" "text", "p_provider_code" "text", "p_model_code" "text", "p_rate_card_version" "text", "p_spend_reservation_id" "uuid", "p_planning_note" "text", "p_content" "jsonb", "p_sources" "jsonb", "p_safe_failure_code" "text", "p_regeneration_feedback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_plan_proposal_review"("p_proposal_id" "uuid", "p_expected_plan_revision" bigint, "p_idempotency_key" "uuid") RETURNS "public"."plan_review_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing public.plan_proposal_decisions;
  v_unresolved integer;
  v_changes jsonb;
  v_applied smallint;
  v_cancels jsonb;
  v_cancel_count smallint;
  v_receipt public.rolling_plan_change_receipt;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_proposal_id is null
    or p_expected_plan_revision is null
    or p_expected_plan_revision < 0
    or p_idempotency_key is null
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid plan review.';
  end if;

  if not exists (
    select 1 from public.plan_proposals
    where id = p_proposal_id and user_id = v_user_id
  ) then
    raise exception using
      errcode = 'PT409',
      message = 'That proposal is no longer available.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62008,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  -- Replay. A repeated finish returns what the first one did; a finish after a
  -- discard is a conflict, because there is nothing left to apply and saying
  -- 'applied' would be untrue.
  select * into v_existing
  from public.plan_proposal_decisions
  where proposal_id = p_proposal_id and user_id = v_user_id;
  if found then
    if v_existing.decision <> 'applied' then
      raise exception using
        errcode = 'PT433',
        message = 'That review is already finished.';
    end if;
    return (
      v_existing.proposal_id, v_existing.decision, v_existing.applied_count,
      v_existing.change_set_id, v_existing.plan_revision, 'replayed'
    )::public.plan_review_receipt;
  end if;

  select pg_catalog.count(*) into v_unresolved
  from public.plan_proposal_items item
  left join public.plan_proposal_item_decisions decision
    on decision.proposal_id = item.proposal_id
    and decision.ordinal = item.ordinal
    and decision.user_id = item.user_id
  where item.proposal_id = p_proposal_id
    and item.user_id = v_user_id
    and decision.decision is null;

  if v_unresolved > 0 then
    raise exception using
      errcode = 'PT432',
      message = 'Every proposed item needs a choice before you can finish.';
  end if;

  select
    pg_catalog.jsonb_agg(change.entry order by change.local_date, change.ordinal),
    pg_catalog.count(*)::smallint
  into v_changes, v_applied
  from (
    select
      staged.local_date,
      staged.ordinal,
      case staged.kind
        when 'recovery_day' then pg_catalog.jsonb_build_object(
          'operation', 'set_recovery_day',
          'localDate', staged.local_date::text,
          'isRecoveryDay', true
        )
        else pg_catalog.jsonb_build_object(
          'operation', 'add',
          'sessionId', staged.session_id,
          'session', pg_catalog.jsonb_build_object(
            'localDate', staged.local_date::text,
            -- The nth position on this date that no active session holds,
            -- where n is this item's place among the date's staged sessions.
            -- Not `max + n`: an owner who has moved a session to 99 would push
            -- that past the 0-99 bound and the whole finish would be refused.
            -- A date holds at most ten active sessions, so a free slot always
            -- exists below 100.
            'position', (
              select slot
              from pg_catalog.generate_series(0, 99) as slot
              where not exists (
                select 1
                from public.rolling_plan_sessions existing
                where existing.user_id = v_user_id
                  and existing.local_date = staged.local_date
                  and existing.status = 'active'
                  and existing.position = slot
              )
              order by slot
              offset staged.date_rank - 1
              limit 1
            )::smallint,
            'title', staged.title,
            'sport', staged.sport,
            'intent', staged.intent,
            'expectedDurationMinutes', staged.expected_duration_minutes,
            'activities', '[]'::jsonb
          )
        )
      end as entry
    from (
      select
        item.*,
        pg_catalog.row_number() over (
          partition by item.local_date, item.kind order by item.ordinal
        ) as date_rank
      from public.plan_proposal_items item
      join public.plan_proposal_item_decisions decision
        on decision.proposal_id = item.proposal_id
        and decision.ordinal = item.ordinal
        and decision.user_id = item.user_id
      where item.proposal_id = p_proposal_id
        and item.user_id = v_user_id
        and decision.decision in ('staged', 'staged_beside')
        -- A cancel item adds nothing; it is the second half below.
        and item.kind <> 'cancel'
        -- A staged rest day on a date that is already one is a choice whose
        -- outcome already holds. Sending it would be refused by the change
        -- function as a change that changes nothing, and that refusal would
        -- take every other staged item down with it. It is left out, and it
        -- is not counted as applied, because nothing was.
        and not (
          item.kind = 'recovery_day'
          and exists (
            select 1
            from public.rolling_plan_recovery_days recovery
            where recovery.user_id = v_user_id
              and recovery.local_date = item.local_date
          )
        )
    ) as staged
  ) as change;

  -- The other half of "replace", and a suggested cancel the owner staged
  -- (ADR-033): the owner's session is cancelled in the change set that adds
  -- the one standing in for it, so the swap happens whole or not at all.
  -- Replacing cancels and no longer deletes, so the session can be brought
  -- back. Four things are checked again here, because the mark is as old as
  -- the request: the session is still active, not behind today, still on one
  -- of the days asked about, and has no training logged against it. One that
  -- fails any of them is left alone (a replacing session is then added beside
  -- it, which is what the review shows for such an item). A session with a
  -- log is never cancelled here.
  select
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'sessionId', target.id,
        'replacedBy', case when item.kind = 'session' then item.session_id end
      )
      order by target.local_date, target.position, target.id
    ),
    pg_catalog.count(*) filter (where item.kind = 'cancel')::smallint
  into v_cancels, v_cancel_count
  from public.plan_proposal_items item
  join public.plan_proposal_item_decisions decision
    on decision.proposal_id = item.proposal_id
    and decision.ordinal = item.ordinal
    and decision.user_id = item.user_id
  join public.rolling_plan_sessions target
    on target.id = item.replaces_session_id
    and target.user_id = v_user_id
  where item.proposal_id = p_proposal_id
    and item.user_id = v_user_id
    and item.kind in ('session', 'cancel')
    and decision.decision = 'staged'
    and target.status = 'active'
    and target.local_date >= (
      select (pg_catalog.timezone(profile.timezone_name, v_now))::date
      from public.profiles profile
      where profile.user_id = v_user_id
    )
    -- Only a session this owner left open for this very proposal, and only
    -- while it is still on one of the days that proposal was asked about. A
    -- session moved elsewhere since is no longer the one the owner offered
    -- for those days, and the review, which reads those days, cannot show it.
    and exists (
      select 1
      from public.plan_proposals proposal
      join public.plan_generation_requests request
        on request.id = proposal.generation_request_id
        and request.user_id = proposal.user_id
      join public.plan_generation_replaceable_sessions marked
        on marked.request_id = request.id
        and marked.user_id = request.user_id
      where proposal.id = p_proposal_id
        and proposal.user_id = v_user_id
        and marked.session_id = target.id
        and target.local_date between request.requested_start_date
          and request.requested_end_date
    )
    and not exists (
      select 1 from public.completions completion
      where completion.user_id = v_user_id
        and completion.plan_session_id = target.id
    );

  -- A staged cancel counts as applied; a replacement was already counted by
  -- the session it adds.
  v_applied := coalesce(v_applied, 0) + coalesce(v_cancel_count, 0);

  if v_cancels is not null then
    v_changes := (
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'operation', 'cancel',
          'sessionId', entry.value->'sessionId'
        )
        order by entry.ordinality
      )
      from pg_catalog.jsonb_array_elements(v_cancels)
        with ordinality as entry(value, ordinality)
    ) || coalesce(v_changes, '[]'::jsonb);
  end if;

  if v_applied = 0 then
    insert into public.plan_proposal_decisions (
      proposal_id, user_id, decision, applied_count, decided_at
    ) values (p_proposal_id, v_user_id, 'applied', 0, v_now);
    return (p_proposal_id, 'applied', 0::smallint, null::uuid, null::bigint, 'applied')
      ::public.plan_review_receipt;
  end if;

  -- The plan's single door. Every refusal it can raise — a stale revision, a
  -- past date, a date already holding ten sessions — propagates unchanged, and
  -- the terminal row below is never written when one does.
  v_receipt := public.apply_rolling_plan_change_set(
    p_expected_plan_revision, p_idempotency_key, 'owner_ai_proposal', v_changes
  );

  -- What this review cancelled, with the session that replaced it, and the
  -- cancellation it is about: a session brought back and later cancelled by
  -- hand no longer matches, so the Plan shows it again.
  if v_cancels is not null then
    insert into public.plan_proposal_cancellations (
      proposal_id, session_id, user_id, replaced_by_session_id, cancelled_at
    )
    select
      p_proposal_id,
      target.id,
      v_user_id,
      (entry.value->>'replacedBy')::uuid,
      target.cancelled_at
    from pg_catalog.jsonb_array_elements(v_cancels) as entry(value)
    join public.rolling_plan_sessions target
      on target.id = (entry.value->>'sessionId')::uuid
      and target.user_id = v_user_id
      and target.status = 'cancelled';
  end if;

  insert into public.plan_proposal_decisions (
    proposal_id, user_id, decision, applied_count, change_set_id,
    plan_revision, decided_at
  ) values (
    p_proposal_id, v_user_id, 'applied', v_applied, v_receipt.change_set_id,
    v_receipt.plan_revision, v_now
  );

  return (
    p_proposal_id, 'applied', v_applied, v_receipt.change_set_id,
    v_receipt.plan_revision, 'applied'
  )::public.plan_review_receipt;
end;
$$;


ALTER FUNCTION "public"."finish_plan_proposal_review"("p_proposal_id" "uuid", "p_expected_plan_revision" bigint, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_roadmap_generation"("p_completion_token" "uuid", "p_outcome" "text", "p_schema_version" "text" DEFAULT NULL::"text", "p_prompt_version" "text" DEFAULT NULL::"text", "p_provider_code" "text" DEFAULT NULL::"text", "p_model_code" "text" DEFAULT NULL::"text", "p_rate_card_version" "text" DEFAULT NULL::"text", "p_spend_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_planning_note" "text" DEFAULT NULL::"text", "p_regeneration_feedback" "text" DEFAULT NULL::"text", "p_content" "jsonb" DEFAULT NULL::"jsonb", "p_sources" "jsonb" DEFAULT NULL::"jsonb", "p_safe_failure_code" "text" DEFAULT NULL::"text") RETURNS "public"."roadmap_generation_result"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.roadmap_generation_requests;
  v_note text;
  v_feedback text;
  v_origin text;
  v_proposal_id uuid;
  v_source jsonb;
  v_ordinal smallint := 0;
  v_kind text;
  v_record uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_completion_token is null
    or p_outcome is null
    or p_outcome not in ('proposal', 'failed')
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap result.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62005,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
  end;

  select * into v_request
  from public.roadmap_generation_requests
  where user_id = v_user_id
    and completion_token = p_completion_token
  for update;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  -- Replay. An already finished request returns its recorded result when the
  -- caller repeats the same outcome, and conflicts when it does not: a second
  -- call must never overwrite what the first one persisted.
  if v_request.status <> 'pending' then
    if (v_request.status = 'completed' and p_outcome = 'proposal')
      or (v_request.status = 'failed' and p_outcome = 'failed'
          and v_request.failure_code is not distinct from p_safe_failure_code)
    then
      if v_request.status = 'completed'
        and p_content is not null
        and not exists (
          select 1
          from public.roadmap_proposals
          where id = v_request.proposal_id
            and user_id = v_user_id
            and content = p_content
        )
      then
        raise exception using
          errcode = 'PT409',
          message = 'That coaching request is no longer open.';
      end if;
      return (v_request.status, v_request.proposal_id)
        ::public.roadmap_generation_result;
    end if;
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  if p_outcome = 'failed' then
    if p_content is not null
      or p_sources is not null
      or p_schema_version is not null
      or p_prompt_version is not null
      or p_provider_code is not null
      or p_model_code is not null
      or p_rate_card_version is not null
      or p_spend_reservation_id is not null
      or p_safe_failure_code is null
      or p_safe_failure_code !~ '^[a-z][a-z0-9_]{1,63}$'
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap result.';
    end if;

    update public.roadmap_generation_requests
    set status = 'failed', failure_code = p_safe_failure_code, updated_at = v_now
    where id = v_request.id and user_id = v_user_id;

    return ('failed', null::uuid)::public.roadmap_generation_result;
  end if;

  if p_safe_failure_code is not null
    or p_content is null
    or p_schema_version is distinct from 'fittip.roadmap.v4'
    or p_prompt_version is null
    or p_provider_code is null
    or p_model_code is null
    or p_rate_card_version is null
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap result.';
  end if;

  if not public.roadmap_technical_codes_are_accepted(
    p_provider_code,
    p_model_code,
    p_rate_card_version,
    p_spend_reservation_id is not null
  ) then
    raise exception using
      errcode = '22023',
      message = 'That coaching model is not approved.';
  end if;

  -- A live result must carry a settled, same-owner reservation priced by the
  -- same rate card. Without this a real call could be recorded as a fixture and
  -- cost nothing against the ceiling.
  if p_spend_reservation_id is not null then
    -- Settled here, in the transaction that records the proposal, so the two
    -- commit together or neither does. Before this, a reservation the
    -- application failed to settle made the check below refuse a result the
    -- provider had already been paid for, and the proposal was thrown away.
    --
    -- The amount is what the reservation was holding, not the real usage: the
    -- real usage is known only to the caller that just failed to report it.
    -- Charging the ceiling is the conservative direction, and it applies only
    -- to runs where the settle had already gone wrong.
    update public.ai_spend_reservations
    set
      charged_micro_usd = reserved_micro_usd,
      settled_at = pg_catalog.now()
    where id = p_spend_reservation_id
      and user_id = v_user_id
      and operation = 'create_roadmap'
      and rate_card_version = p_rate_card_version
      and settled_at is null;

    -- Asserted separately rather than from the update's row count, because a
    -- reservation the application settled normally matches no row above and is
    -- a perfectly good finish. What has to hold on every path is the same four
    -- things it always did, plus that the reservation is now closed.
    if not exists (
      select 1
      from public.ai_spend_reservations
      where id = p_spend_reservation_id
        and user_id = v_user_id
        and operation = 'create_roadmap'
        and settled_at is not null
        and rate_card_version = p_rate_card_version
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap result.';
    end if;
  end if;

  -- The owner text must be the text this request claimed before the provider
  -- call. Anything else means the content that travelled is not the content
  -- being stored, and the memory excerpt check downstream would be meaningless.
  v_note := public.roadmap_normalize_owner_text(p_planning_note);
  if v_note = '' then v_note := null; end if;
  v_feedback := public.roadmap_normalize_owner_text(p_regeneration_feedback);
  if v_feedback = '' then v_feedback := null; end if;

  if public.roadmap_owner_text_hash(v_note)
       is distinct from v_request.planning_note_hash
    or public.roadmap_owner_text_hash(v_feedback)
       is distinct from v_request.regeneration_feedback_hash
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap result.';
  end if;

  if not public.roadmap_content_is_valid(
    p_content,
    v_request.requested_start_date,
    v_request.requested_end_date
  ) then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap result.';
  end if;

  v_origin := case
    when v_request.regeneration_number > 0 then 'ai_regeneration'
    else 'ai_initial'
  end;

  insert into public.roadmap_proposals (
    user_id,
    generation_request_id,
    source_proposal_id,
    origin,
    planning_note,
    regeneration_feedback,
    schema_version,
    prompt_version,
    provider_code,
    model_code,
    rate_card_version,
    spend_reservation_id,
    content,
    created_at
  )
  values (
    v_user_id,
    v_request.id,
    v_request.previous_proposal_id,
    v_origin,
    v_note,
    v_feedback,
    p_schema_version,
    pg_catalog.btrim(p_prompt_version),
    pg_catalog.btrim(p_provider_code),
    pg_catalog.btrim(p_model_code),
    pg_catalog.btrim(p_rate_card_version),
    p_spend_reservation_id,
    p_content,
    v_now
  )
  returning id into v_proposal_id;

  if p_sources is not null then
    if pg_catalog.jsonb_typeof(p_sources) <> 'array'
      or pg_catalog.jsonb_array_length(p_sources) > 200
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap result.';
    end if;

    for v_source in
      select value from pg_catalog.jsonb_array_elements(p_sources)
    loop
      v_kind := v_source->>'kind';
      if v_kind not in ('goal', 'memory', 'plan_version', 'completion') then
        raise exception using
          errcode = '22023',
          message = 'Invalid roadmap result.';
      end if;

      begin
        v_record := (v_source->>'recordId')::uuid;
      exception
        when others then
          raise exception using
            errcode = '22023',
            message = 'Invalid roadmap result.';
      end;

      insert into public.roadmap_proposal_sources (
        proposal_id,
        user_id,
        ordinal,
        source_kind,
        record_id,
        revision_id,
        revision_number
      )
      values (
        v_proposal_id,
        v_user_id,
        v_ordinal,
        v_kind,
        v_record,
        nullif(v_source->>'revisionId', '')::uuid,
        nullif(v_source->>'revisionNumber', '')::bigint
      );
      v_ordinal := v_ordinal + 1;
    end loop;
  end if;

  update public.roadmap_generation_requests
  set status = 'completed', proposal_id = v_proposal_id, updated_at = v_now
  where id = v_request.id and user_id = v_user_id;

  return ('completed', v_proposal_id)::public.roadmap_generation_result;
end;
$_$;


ALTER FUNCTION "public"."finish_roadmap_generation"("p_completion_token" "uuid", "p_outcome" "text", "p_schema_version" "text", "p_prompt_version" "text", "p_provider_code" "text", "p_model_code" "text", "p_rate_card_version" "text", "p_spend_reservation_id" "uuid", "p_planning_note" "text", "p_regeneration_feedback" "text", "p_content" "jsonb", "p_sources" "jsonb", "p_safe_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_session_activity_generation"("p_completion_token" "uuid", "p_outcome" "text", "p_schema_version" "text" DEFAULT NULL::"text", "p_prompt_version" "text" DEFAULT NULL::"text", "p_provider_code" "text" DEFAULT NULL::"text", "p_model_code" "text" DEFAULT NULL::"text", "p_rate_card_version" "text" DEFAULT NULL::"text", "p_spend_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text", "p_content" "jsonb" DEFAULT NULL::"jsonb", "p_sources" "jsonb" DEFAULT NULL::"jsonb", "p_safe_failure_code" "text" DEFAULT NULL::"text") RETURNS "public"."plan_generation_result"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.session_activity_requests;
  v_note text;
  v_proposal_id uuid;
  v_source jsonb;
  v_ordinal smallint := 0;
  v_kind text;
  v_record uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_completion_token is null
    or p_outcome is null
    or p_outcome not in ('proposal', 'failed')
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity result.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62009,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your plan changed. Reload and try again.';
  end;

  select * into v_request
  from public.session_activity_requests
  where user_id = v_user_id and completion_token = p_completion_token
  for update;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  -- Replay: the same outcome returns what was recorded; a different one
  -- conflicts. A second call never overwrites the first one's result.
  if v_request.status <> 'pending' then
    if (v_request.status = 'completed' and p_outcome = 'proposal')
      or (v_request.status = 'failed' and p_outcome = 'failed'
          and v_request.failure_code is not distinct from p_safe_failure_code)
    then
      return (v_request.status, v_request.proposal_id)
        ::public.plan_generation_result;
    end if;
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is already finished.';
  end if;

  if p_outcome = 'failed' then
    if p_safe_failure_code is null
      or p_safe_failure_code !~ '^[a-z][a-z0-9_]{1,63}$'
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid session activity result.';
    end if;
    update public.session_activity_requests
    set status = 'failed', failure_code = p_safe_failure_code, updated_at = v_now
    where id = v_request.id and user_id = v_user_id;
    return ('failed', null)::public.plan_generation_result;
  end if;

  -- The note travels again on finish, and its hash proves it is the text the
  -- claim was made for.
  v_note := public.roadmap_normalize_owner_text(p_note);
  if v_note = '' then v_note := null; end if;
  if public.roadmap_owner_text_hash(v_note) is distinct from v_request.note_hash
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity result.';
  end if;

  if p_schema_version is distinct from 'fittip.session-activities.v1'
    or p_prompt_version is null
    or p_provider_code is null
    or p_model_code is null
    or p_rate_card_version is null
    or not public.session_activities_content_is_valid(p_content, v_user_id)
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity result.';
  end if;

  -- An approved pairing, with a reservation exactly when it is live: what the
  -- owner-facing "example" label rests on. The function names no operation.
  if not public.roadmap_technical_codes_are_accepted(
    p_provider_code,
    p_model_code,
    p_rate_card_version,
    p_spend_reservation_id is not null
  ) then
    raise exception using
      errcode = '22023',
      message = 'That coaching model is not approved.';
  end if;

  -- ADR-019: settled here, in the transaction that records the proposal, at
  -- the amount it was holding if the application's settle did not arrive. It
  -- must be this owner's, for this operation, priced by the same rate card.
  if p_spend_reservation_id is not null then
    update public.ai_spend_reservations
    set
      charged_micro_usd = reserved_micro_usd,
      settled_at = pg_catalog.now()
    where id = p_spend_reservation_id
      and user_id = v_user_id
      and operation = 'fill_session_activities'
      and rate_card_version = p_rate_card_version
      and settled_at is null;

    if not exists (
      select 1
      from public.ai_spend_reservations
      where id = p_spend_reservation_id
        and user_id = v_user_id
        and operation = 'fill_session_activities'
        and settled_at is not null
        and rate_card_version = p_rate_card_version
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid session activity result.';
    end if;
  end if;

  insert into public.session_activity_proposals (
    user_id, request_id, session_id, local_date, note, schema_version,
    prompt_version, provider_code, model_code, rate_card_version,
    spend_reservation_id, content, created_at
  ) values (
    v_user_id, v_request.id, v_request.session_id, v_request.local_date,
    v_note, p_schema_version, p_prompt_version, p_provider_code, p_model_code,
    p_rate_card_version, p_spend_reservation_id, p_content, v_now
  )
  returning id into v_proposal_id;

  if p_sources is not null then
    if pg_catalog.jsonb_typeof(p_sources) <> 'array'
      or pg_catalog.jsonb_array_length(p_sources) > 256
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid session activity result.';
    end if;
    for v_source in select value from pg_catalog.jsonb_array_elements(p_sources)
    loop
      v_kind := v_source->>'kind';
      if v_kind is null or v_kind not in (
        'goal', 'memory', 'completion',
        'plan_session', 'personal_activity', 'saved_session'
      ) then
        raise exception using
          errcode = '22023',
          message = 'Invalid session activity result.';
      end if;
      begin
        v_record := (v_source->>'recordId')::uuid;
      exception when others then
        raise exception using
          errcode = '22023',
          message = 'Invalid session activity result.';
      end;
      insert into public.session_activity_proposal_sources (
        proposal_id, ordinal, user_id, source_kind, record_id,
        revision_id, revision_number
      ) values (
        v_proposal_id, v_ordinal, v_user_id, v_kind, v_record,
        case
          when pg_catalog.jsonb_typeof(v_source->'revisionId') = 'string'
          then (v_source->>'revisionId')::uuid
        end,
        case
          when pg_catalog.jsonb_typeof(v_source->'revisionNumber') = 'number'
          then (v_source->>'revisionNumber')::bigint
        end
      );
      v_ordinal := v_ordinal + 1;
    end loop;
  end if;

  update public.session_activity_requests
  set status = 'completed', proposal_id = v_proposal_id, updated_at = v_now
  where id = v_request.id and user_id = v_user_id;

  return ('completed', v_proposal_id)::public.plan_generation_result;
exception
  -- `numeric_value_out_of_range` beyond the plan's list: a source revision
  -- number too large for bigint is invalid input, not a server error.
  when check_violation or invalid_datetime_format or invalid_text_representation
    or numeric_value_out_of_range then
    raise exception using
      errcode = '22023',
      message = 'Invalid session activity result.';
end;
$_$;


ALTER FUNCTION "public"."finish_session_activity_generation"("p_completion_token" "uuid", "p_outcome" "text", "p_schema_version" "text", "p_prompt_version" "text", "p_provider_code" "text", "p_model_code" "text", "p_rate_card_version" "text", "p_spend_reservation_id" "uuid", "p_note" "text", "p_content" "jsonb", "p_sources" "jsonb", "p_safe_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rolling_plan_slice"("p_start_date" "date", "p_end_date" "date") RETURNS "public"."rolling_plan_slice_receipt"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with caller as (
    select auth.uid() as user_id
  ),
  owner_plan as (
    select plan.id, plan.revision
    from public.rolling_plans plan
    cross join caller
    where plan.user_id = caller.user_id
  ),
  bounded_sessions as (
    select
      session.id,
      session.user_id,
      session.local_date,
      session.position,
      session.title,
      session.sport,
      session.intent,
      session.expected_duration_minutes,
      session.start_time,
      session.note,
      session.coach_note,
      session.status,
      session.cancelled_at,
      session.series_id,
      session.occurrence_date,
      session.has_diverged,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', activity.id,
            'personalActivityId', activity.personal_activity_id,
            'position', activity.position,
            'name', activity.name,
            'sport', activity.sport,
            'instructions', activity.instructions,
            'rationale', activity.rationale,
            'measurementMode', activity.measurement_mode,
            'target', activity.target
          ) order by activity.position, activity.id
        )
        from public.rolling_plan_activities activity
        where activity.user_id = session.user_id
          and activity.session_id = session.id
      ), '[]'::jsonb) as activities
    from public.rolling_plan_sessions session
    cross join caller
    where session.user_id = caller.user_id
      and session.local_date between p_start_date and p_end_date
  ),
  bounded_recovery as (
    select recovery.local_date
    from public.rolling_plan_recovery_days recovery
    cross join caller
    where recovery.user_id = caller.user_id
      and recovery.local_date between p_start_date and p_end_date
  )
  select (
    (select id from owner_plan),
    coalesce((select revision from owner_plan), 0),
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', session.id,
          'localDate', session.local_date,
          'position', session.position,
          'title', session.title,
          'sport', session.sport,
          'intent', session.intent,
          'expectedDurationMinutes', session.expected_duration_minutes,
          'startTime', pg_catalog.to_char(session.start_time, 'HH24:MI'),
          'note', session.note,
          'coachNote', session.coach_note,
          'status', session.status,
          'cancelledAt', session.cancelled_at,
          'seriesId', session.series_id,
          'occurrenceDate', session.occurrence_date,
          'hasDiverged', session.has_diverged,
          'activities', session.activities
        ) order by session.local_date, session.position, session.id
      ) from bounded_sessions session
    ), '[]'::jsonb),
    coalesce((
      select jsonb_agg(recovery.local_date::text order by recovery.local_date)
      from bounded_recovery recovery
    ), '[]'::jsonb)
  )::public.rolling_plan_slice_receipt;
$$;


ALTER FUNCTION "public"."get_rolling_plan_slice"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."goal_suggestion_fields_are_valid"("p_suggestion" "jsonb", "p_today" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_sport jsonb;
  v_seen text[] := array[]::text[];
  v_clean text;
begin
  if p_suggestion is null
    or pg_catalog.jsonb_typeof(p_suggestion) <> 'object'
    or exists (
      select 1 from pg_catalog.jsonb_object_keys(p_suggestion) as key
      where key not in ('title', 'desiredOutcome', 'sports', 'targetDate')
    )
    or pg_catalog.jsonb_typeof(p_suggestion->'title') is distinct from 'string'
    or pg_catalog.char_length(pg_catalog.btrim(p_suggestion->>'title'))
       not between 1 and 120
    or pg_catalog.jsonb_typeof(p_suggestion->'desiredOutcome')
       is distinct from 'string'
    or pg_catalog.char_length(pg_catalog.btrim(p_suggestion->>'desiredOutcome'))
       not between 1 and 1000
    or pg_catalog.jsonb_typeof(p_suggestion->'sports') is distinct from 'array'
    or pg_catalog.jsonb_array_length(p_suggestion->'sports') not between 1 and 10
  then
    return false;
  end if;

  for v_sport in
    select value from pg_catalog.jsonb_array_elements(p_suggestion->'sports')
  loop
    if pg_catalog.jsonb_typeof(v_sport) <> 'string' then
      return false;
    end if;
    v_clean := pg_catalog.btrim(v_sport #>> '{}');
    if pg_catalog.char_length(v_clean) not between 1 and 60
      or pg_catalog.lower(v_clean) = any (v_seen)
    then
      return false;
    end if;
    v_seen := v_seen || pg_catalog.lower(v_clean);
  end loop;

  if p_suggestion ? 'targetDate'
    and pg_catalog.jsonb_typeof(p_suggestion->'targetDate') <> 'null'
  then
    if pg_catalog.jsonb_typeof(p_suggestion->'targetDate') <> 'string'
      or (p_suggestion->>'targetDate')::date::text <> p_suggestion->>'targetDate'
      or (p_suggestion->>'targetDate')::date < p_today
    then
      return false;
    end if;
  end if;

  return true;
exception
  when others then
    return false;
end;
$$;


ALTER FUNCTION "public"."goal_suggestion_fields_are_valid"("p_suggestion" "jsonb", "p_today" "date") OWNER TO "postgres";


