CREATE OR REPLACE FUNCTION "public"."is_training_measurement_mode"("p_mode" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_mode in (
    'unmeasured', 'sets_reps_load', 'time_distance_pace', 'duration_intensity',
    'intervals'
  )
$$;


ALTER FUNCTION "public"."is_training_measurement_mode"("p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_valid_training_measurement"("p_mode" "text", "p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_first numeric;
  v_second numeric;
  v_third numeric;
  v_group jsonb;
  v_loaded boolean;
  v_measured boolean;
begin
  if p_value is null then
    return true;
  end if;

  if jsonb_typeof(p_value) is distinct from 'object'
    or octet_length(p_value::text) > 4096 then
    return false;
  end if;

  if p_mode = 'unmeasured' then
    return false;
  end if;

  if p_mode = 'sets_reps_load' then
    -- Grouped: each block is sets × reps or sets × seconds, either with a
    -- weight. Reps and seconds are two answers to one question, so a block
    -- carries at most one of them.
    if p_value ? 'groups' then
      if p_value - array['groups', 'load_unit'] <> '{}'::jsonb
        or jsonb_typeof(p_value -> 'groups') is distinct from 'array'
        or jsonb_array_length(p_value -> 'groups') not between 1 and 20 then
        return false;
      end if;

      v_loaded := false;
      for v_group in
        select value from jsonb_array_elements(p_value -> 'groups')
      loop
        if jsonb_typeof(v_group) is distinct from 'object'
          or v_group - array['sets', 'reps', 'seconds', 'load'] <> '{}'::jsonb
          or not (
            v_group ? 'sets' or v_group ? 'reps' or v_group ? 'seconds'
            or v_group ? 'load'
          )
          or (v_group ? 'reps' and v_group ? 'seconds') then
          return false;
        end if;

        if v_group ? 'sets' then
          if jsonb_typeof(v_group -> 'sets') is distinct from 'number' then
            return false;
          end if;
          v_first := (v_group ->> 'sets')::numeric;
          if v_first <> trunc(v_first) or v_first not between 1 and 100 then
            return false;
          end if;
        end if;

        if v_group ? 'reps' then
          if jsonb_typeof(v_group -> 'reps') is distinct from 'number' then
            return false;
          end if;
          v_second := (v_group ->> 'reps')::numeric;
          if v_second <> trunc(v_second) or v_second not between 1 and 10000 then
            return false;
          end if;
        end if;

        if v_group ? 'seconds' then
          if jsonb_typeof(v_group -> 'seconds') is distinct from 'number' then
            return false;
          end if;
          v_second := (v_group ->> 'seconds')::numeric;
          if v_second <> trunc(v_second) or v_second not between 1 and 86400 then
            return false;
          end if;
        end if;

        if v_group ? 'load' then
          if jsonb_typeof(v_group -> 'load') is distinct from 'number' then
            return false;
          end if;
          v_third := (v_group ->> 'load')::numeric;
          if v_third < 0 or v_third > 100000 then
            return false;
          end if;
          v_loaded := true;
        end if;
      end loop;

      -- The presence test first: absent, the comparison is NULL, and a check
      -- constraint passes a NULL (A2c).
      if v_loaded then
        return p_value ? 'load_unit'
          and jsonb_typeof(p_value -> 'load_unit') = 'string'
          and p_value ->> 'load_unit' in ('kg', 'lb');
      end if;
      return not (p_value ? 'load_unit');
    end if;

    -- The flat form nothing writes any more, readable for good (A2c).
    if p_value - array['sets', 'reps', 'load', 'load_unit'] <> '{}'::jsonb
      or jsonb_typeof(p_value -> 'sets') is distinct from 'number'
      or jsonb_typeof(p_value -> 'reps') is distinct from 'number'
      or (
        p_value ? 'load'
        and jsonb_typeof(p_value -> 'load') is distinct from 'number'
      )
      or (
        p_value ? 'load'
        and jsonb_typeof(p_value -> 'load_unit') is distinct from 'string'
      )
      or (
        not (p_value ? 'load')
        and p_value ? 'load_unit'
      ) then
      return false;
    end if;

    v_first := (p_value ->> 'sets')::numeric;
    v_second := (p_value ->> 'reps')::numeric;
    if v_first <> trunc(v_first) or v_first not between 1 and 100
      or v_second <> trunc(v_second) or v_second not between 1 and 10000 then
      return false;
    end if;

    if p_value ? 'load' then
      v_third := (p_value ->> 'load')::numeric;
      if v_third < 0 or v_third > 100000
        or p_value ->> 'load_unit' not in ('kg', 'lb') then
        return false;
      end if;
    end if;

    return true;
  end if;

  if p_mode = 'intervals' then
    -- Blocks of repeats, each of a distance or a time (or both: 400 m in
    -- 90 s), with rest between. The distance unit sits once at the top, as
    -- the load unit does, and is there exactly when a block has a distance.
    if p_value - array['blocks', 'distance_unit'] <> '{}'::jsonb
      or jsonb_typeof(p_value -> 'blocks') is distinct from 'array'
      or jsonb_array_length(p_value -> 'blocks') not between 1 and 20 then
      return false;
    end if;

    v_measured := false;
    for v_group in
      select value from jsonb_array_elements(p_value -> 'blocks')
    loop
      if jsonb_typeof(v_group) is distinct from 'object'
        or v_group - array['repeats', 'distance', 'seconds', 'rest_seconds']
          <> '{}'::jsonb
        or jsonb_typeof(v_group -> 'repeats') is distinct from 'number'
        or not (v_group ? 'distance' or v_group ? 'seconds') then
        return false;
      end if;

      v_first := (v_group ->> 'repeats')::numeric;
      if v_first <> trunc(v_first) or v_first not between 1 and 100 then
        return false;
      end if;

      if v_group ? 'distance' then
        if jsonb_typeof(v_group -> 'distance') is distinct from 'number' then
          return false;
        end if;
        v_second := (v_group ->> 'distance')::numeric;
        if v_second <= 0 or v_second > 1000000 then
          return false;
        end if;
        v_measured := true;
      end if;

      if v_group ? 'seconds' then
        if jsonb_typeof(v_group -> 'seconds') is distinct from 'number' then
          return false;
        end if;
        v_third := (v_group ->> 'seconds')::numeric;
        if v_third <> trunc(v_third) or v_third not between 1 and 86400 then
          return false;
        end if;
      end if;

      if v_group ? 'rest_seconds' then
        if jsonb_typeof(v_group -> 'rest_seconds') is distinct from 'number' then
          return false;
        end if;
        v_third := (v_group ->> 'rest_seconds')::numeric;
        if v_third <> trunc(v_third) or v_third not between 0 and 3600 then
          return false;
        end if;
      end if;
    end loop;

    if v_measured then
      return p_value ? 'distance_unit'
        and jsonb_typeof(p_value -> 'distance_unit') = 'string'
        and p_value ->> 'distance_unit' in ('m', 'km', 'mi', 'yd');
    end if;
    return not (p_value ? 'distance_unit');
  end if;

  if p_mode = 'time_distance_pace' then
    if p_value - array[
      'duration_seconds',
      'distance',
      'distance_unit',
      'pace_seconds_per_unit',
      'pace_unit'
    ] <> '{}'::jsonb
      or not (
        p_value ? 'duration_seconds'
        or p_value ? 'distance'
        or p_value ? 'pace_seconds_per_unit'
      ) then
      return false;
    end if;

    if p_value ? 'duration_seconds' then
      if jsonb_typeof(p_value -> 'duration_seconds') is distinct from 'number' then
        return false;
      end if;
      v_first := (p_value ->> 'duration_seconds')::numeric;
      if v_first <= 0 or v_first > 604800 then
        return false;
      end if;
    end if;

    if p_value ? 'distance' then
      if jsonb_typeof(p_value -> 'distance') is distinct from 'number'
        or jsonb_typeof(p_value -> 'distance_unit') is distinct from 'string' then
        return false;
      end if;
      v_second := (p_value ->> 'distance')::numeric;
      if v_second <= 0 or v_second > 1000000
        or p_value ->> 'distance_unit' not in ('m', 'km', 'mi', 'yd') then
        return false;
      end if;
    elsif p_value ? 'distance_unit' then
      return false;
    end if;

    if p_value ? 'pace_seconds_per_unit' then
      if jsonb_typeof(p_value -> 'pace_seconds_per_unit') is distinct from 'number'
        or jsonb_typeof(p_value -> 'pace_unit') is distinct from 'string' then
        return false;
      end if;
      v_third := (p_value ->> 'pace_seconds_per_unit')::numeric;
      if v_third <= 0 or v_third > 86400
        or p_value ->> 'pace_unit' not in (
          'sec/km',
          'sec/mi',
          'sec/100m',
          'sec/100yd'
        ) then
        return false;
      end if;
    elsif p_value ? 'pace_unit' then
      return false;
    end if;

    return true;
  end if;

  if p_mode = 'duration_intensity' then
    if p_value - array[
      'duration_minutes',
      'intensity',
      'perceived_effort'
    ] <> '{}'::jsonb
      or jsonb_typeof(p_value -> 'duration_minutes') is distinct from 'number' then
      return false;
    end if;

    v_first := (p_value ->> 'duration_minutes')::numeric;
    if v_first <= 0 or v_first > 10080 then
      return false;
    end if;

    if p_value ? 'intensity' and (
      jsonb_typeof(p_value -> 'intensity') is distinct from 'string'
      or p_value ->> 'intensity' not in ('easy', 'moderate', 'hard', 'very_hard')
    ) then
      return false;
    end if;

    if p_value ? 'perceived_effort' then
      if jsonb_typeof(p_value -> 'perceived_effort') is distinct from 'number' then
        return false;
      end if;
      v_second := (p_value ->> 'perceived_effort')::numeric;
      if v_second <> trunc(v_second) or v_second not between 1 and 10 then
        return false;
      end if;
    end if;

    return true;
  end if;

  -- Repetitions and Custom are gone (ADR-038); an unknown mode is refused.
  return false;
exception
  when others then
    return false;
end;
$$;


ALTER FUNCTION "public"."is_valid_training_measurement"("p_mode" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."keep_sports"("p_names" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_raw text;
  v_name text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  -- Without a profile there is no list to add to.
  perform 1 from public.profiles where user_id = v_user_id for update;
  if not found then return; end if;

  foreach v_raw in array coalesce(p_names, '{}'::text[]) loop
    v_name := public.tidy_sport_name(v_raw);
    continue when v_name is null or v_name = ''
      or pg_catalog.char_length(v_name) > 60
      or pg_catalog.strpos(v_name, ',') > 0;
    exit when (
      select pg_catalog.count(*) from public.sports where user_id = v_user_id
    ) >= 100;
    insert into public.sports (user_id, name)
    values (v_user_id, v_name)
    on conflict (user_id, pg_catalog.lower(name)) do nothing;
  end loop;
end;
$$;


ALTER FUNCTION "public"."keep_sports"("p_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialize_rolling_plan_series"("p_expected_plan_revision" bigint, "p_idempotency_key" "uuid") RETURNS "public"."rolling_plan_materialization_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_timezone text;
  v_today date;
  v_window_end date;
  v_plan public.rolling_plans;
  v_series public.rolling_plan_series;
  v_date date;
  v_key text;
  v_count integer;
  v_position integer;
  v_counts jsonb;
  v_positions jsonb;
  v_activities jsonb;
  v_changes jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_receipt public.rolling_plan_change_receipt;
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  if p_expected_plan_revision is null or p_expected_plan_revision < 0
    or p_idempotency_key is null
  then
    raise exception using errcode = '22023',
      message = 'Invalid rolling plan materialization.';
  end if;

  select profile.timezone_name into v_timezone
  from public.profiles profile where profile.user_id = v_user_id;
  if v_timezone is null then
    raise exception using errcode = 'PT428',
      message = 'Confirm your time zone before changing your plan.';
  end if;
  -- The window is owner-local and comes from the stored zone alone. A caller
  -- cannot name a date, so it cannot widen what gets written.
  -- R3b-2: today plus ninety days, thirteen weeks in all. It was `+ 13`.
  v_today := (pg_catalog.timezone(v_timezone, v_now))::date;
  v_window_end := v_today + 90;

  select * into v_plan from public.rolling_plans where user_id = v_user_id;
  if not found then
    return (null, 0::bigint, null, 'unchanged', 0, '[]'::jsonb)
      ::public.rolling_plan_materialization_receipt;
  end if;

  select coalesce(pg_catalog.jsonb_object_agg(dated.local_date::text, dated.total), '{}'::jsonb)
  into v_counts
  from (
    select session.local_date, pg_catalog.count(*)::integer as total
    from public.rolling_plan_sessions session
    where session.user_id = v_user_id and session.status = 'active'
      and session.local_date between v_today and v_window_end
    group by session.local_date
  ) as dated;

  select coalesce(pg_catalog.jsonb_object_agg(dated.local_date::text, dated.highest), '{}'::jsonb)
  into v_positions
  from (
    select session.local_date, pg_catalog.max(session.position)::integer as highest
    from public.rolling_plan_sessions session
    where session.user_id = v_user_id and session.status = 'active'
      and session.local_date between v_today and v_window_end
    group by session.local_date
  ) as dated;

  for v_series in
    select series.* from public.rolling_plan_series series
    where series.user_id = v_user_id
      and series.start_date <= v_window_end
      and (series.end_date is null or series.end_date >= v_today)
    order by series.created_at, series.id
  loop
    v_activities := coalesce((
      select pg_catalog.jsonb_agg(ordered.item order by ordered.position)
      from (
        select
          activity.position,
          pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
            'personalActivityId', activity.personal_activity_id,
            'position', activity.position,
            'name', activity.name,
            'sport', activity.sport,
            'instructions', activity.instructions,
            'rationale', activity.rationale,
            'measurementMode', activity.measurement_mode,
            'target', activity.target
          )) as item
        from public.rolling_plan_series_activities activity
        where activity.user_id = v_user_id and activity.series_id = v_series.id
      ) as ordered
    ), '[]'::jsonb);

    for v_date in
      select rule_date from public.rolling_plan_series_dates(
        v_series.frequency, v_series.interval_count, v_series.weekdays,
        v_series.start_date, v_series.end_date, v_today, v_window_end
      ) as rule_date
    loop
      -- A date the series already covers is never revisited, whether the
      -- occurrence is untouched, diverged, or cancelled.
      if exists (
        select 1 from public.rolling_plan_sessions occurrence
        where occurrence.series_id = v_series.id
          and occurrence.occurrence_date = v_date
      ) then continue; end if;
      -- M3-20: nor is a date the owner deleted this series' occurrence from.
      if v_date = any(v_series.skipped_occurrence_dates) then continue; end if;

      v_key := v_date::text;
      v_count := coalesce((v_counts->>v_key)::integer, 0);
      if v_count >= 10 then
        v_skipped := v_skipped || pg_catalog.jsonb_build_object(
          'seriesId', v_series.id,
          'occurrenceDate', v_key,
          'reason', 'daily_session_limit'
        );
        continue;
      end if;
      -- `apply_rolling_plan_change_set` accepts at most one hundred changes, so
      -- a very full window is finished by the next call rather than refused.
      -- R3b-2: at ninety-one days two daily series already exceed that on a
      -- first fill, so the application now calls again while this is reported.
      if pg_catalog.jsonb_array_length(v_changes) >= 100 then
        v_skipped := v_skipped || pg_catalog.jsonb_build_object(
          'seriesId', v_series.id,
          'occurrenceDate', v_key,
          'reason', 'change_set_limit'
        );
        continue;
      end if;

      v_position := coalesce((v_positions->>v_key)::integer, -1) + 1;
      v_changes := v_changes || pg_catalog.jsonb_build_object(
        'operation', 'add',
        'sessionId', public.rolling_plan_occurrence_id(v_series.id, v_date),
        'session', pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'localDate', v_key,
          'title', v_series.title,
          'sport', v_series.sport,
          'intent', v_series.intent,
          'expectedDurationMinutes', v_series.expected_duration_minutes,
          'startTime', pg_catalog.to_char(v_series.start_time, 'HH24:MI'),
          'note', v_series.note,
          'coachNote', v_series.coach_note,
          'seriesId', v_series.id,
          'occurrenceDate', v_key
        )) || pg_catalog.jsonb_build_object(
          'position', v_position,
          'activities', v_activities
        )
      );
      v_counts := v_counts || pg_catalog.jsonb_build_object(v_key, v_count + 1);
      v_positions := v_positions || pg_catalog.jsonb_build_object(v_key, v_position);
    end loop;
  end loop;

  if pg_catalog.jsonb_array_length(v_changes) = 0 then
    return (
      v_plan.id, v_plan.revision, null, 'unchanged', 0, v_skipped
    )::public.rolling_plan_materialization_receipt;
  end if;

  v_receipt := public.apply_rolling_plan_change_set(
    p_expected_plan_revision, p_idempotency_key, 'series_expansion', v_changes
  );
  return (
    v_receipt.plan_id, v_receipt.plan_revision, v_receipt.change_set_id,
    v_receipt.result, pg_catalog.jsonb_array_length(v_changes), v_skipped
  )::public.rolling_plan_materialization_receipt;
end;
$$;


ALTER FUNCTION "public"."materialize_rolling_plan_series"("p_expected_plan_revision" bigint, "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."plan_content_is_valid"("p_content" "jsonb", "p_start_date" "date", "p_end_date" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_session jsonb;
  v_alternative jsonb;
  v_day_count integer;
  v_count integer;
  v_minutes jsonb;
  v_cancel jsonb;
begin
  if p_content is null or pg_catalog.jsonb_typeof(p_content) <> 'object' then
    return false;
  end if;

  if pg_catalog.octet_length(p_content::text) > 16000 then
    return false;
  end if;

  if p_start_date is null or p_end_date is null or p_end_date < p_start_date then
    return false;
  end if;

  v_day_count := (p_end_date - p_start_date) + 1;
  if v_day_count not between 1 and 7 then
    return false;
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_object_keys(p_content) as key
    where key not in (
      'schemaVersion', 'weekDescription', 'startDate', 'endDate', 'sessions',
      'assumptions', 'uncertainties', 'safetyConsiderations', 'cancels'
    )
  ) then
    return false;
  end if;

  if p_content->>'schemaVersion' is distinct from 'fittip.seven-day-plan.v2'
    or pg_catalog.char_length(coalesce(p_content->>'weekDescription', ''))
       not between 1 and 600
    or (p_content->>'startDate')::date is distinct from p_start_date
    or (p_content->>'endDate')::date is distinct from p_end_date
  then
    return false;
  end if;

  if pg_catalog.jsonb_typeof(p_content->'sessions') <> 'array' then
    return false;
  end if;
  v_count := pg_catalog.jsonb_array_length(p_content->'sessions');
  if v_count not between 0 and (3 * v_day_count) then
    return false;
  end if;

  -- At most three sessions on any one date.
  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_content->'sessions') as entry(value)
    group by entry.value->>'date'
    having pg_catalog.count(*) > 3
  ) then
    return false;
  end if;

  for v_session in
    select value from pg_catalog.jsonb_array_elements(p_content->'sessions')
  loop
    if pg_catalog.jsonb_typeof(v_session) <> 'object' then
      return false;
    end if;
    if exists (
      select 1
      from pg_catalog.jsonb_object_keys(v_session) as key
      where key not in (
        'date', 'title', 'sport', 'focus', 'intent', 'durationMinutes',
        'primaryGoalId', 'secondaryGoalIds', 'alternatives', 'rationale',
        'replaces'
      )
    ) then
      return false;
    end if;

    if (v_session->>'date')::date < p_start_date
      or (v_session->>'date')::date > p_end_date
      or pg_catalog.char_length(coalesce(v_session->>'title', ''))
         not between 1 and 120
      or pg_catalog.char_length(coalesce(v_session->>'sport', ''))
         not between 1 and 60
      or pg_catalog.char_length(coalesce(v_session->>'focus', ''))
         not between 1 and 300
      or pg_catalog.char_length(coalesce(v_session->>'intent', ''))
         not between 1 and 300
      or pg_catalog.char_length(coalesce(v_session->>'rationale', ''))
         not between 1 and 300
      or pg_catalog.char_length(coalesce(v_session->>'primaryGoalId', ''))
         not between 1 and 64
    then
      return false;
    end if;

    -- The handle of a session the owner marked replaceable, or absent. Only
    -- its shape is checked here; `finish_plan_generation` holds it to the
    -- marks of the request it answers.
    if v_session ? 'replaces'
      and pg_catalog.jsonb_typeof(v_session->'replaces') <> 'null'
      and (
        pg_catalog.jsonb_typeof(v_session->'replaces') <> 'string'
        or (v_session->>'replaces') !~ '^r[1-9][0-9]?$'
      )
    then
      return false;
    end if;

    v_minutes := v_session->'durationMinutes';
    if pg_catalog.jsonb_typeof(v_minutes) <> 'number'
      or (v_minutes::text)::numeric not between 10 and 240
      or (v_minutes::text)::numeric
         <> pg_catalog.trunc((v_minutes::text)::numeric)
    then
      return false;
    end if;

    if v_session ? 'secondaryGoalIds' and (
      pg_catalog.jsonb_typeof(v_session->'secondaryGoalIds') <> 'array'
      or pg_catalog.jsonb_array_length(v_session->'secondaryGoalIds') > 6
    ) then
      return false;
    end if;

    if v_session ? 'alternatives' then
      if pg_catalog.jsonb_typeof(v_session->'alternatives') <> 'array'
        or pg_catalog.jsonb_array_length(v_session->'alternatives') > 2
      then
        return false;
      end if;
      for v_alternative in
        select value
        from pg_catalog.jsonb_array_elements(v_session->'alternatives')
      loop
        if pg_catalog.jsonb_typeof(v_alternative) <> 'object'
          or exists (
            select 1
            from pg_catalog.jsonb_object_keys(v_alternative) as key
            where key not in ('title', 'whenToChoose')
          )
          or pg_catalog.char_length(coalesce(v_alternative->>'title', ''))
             not between 1 and 120
          or pg_catalog.char_length(
               coalesce(v_alternative->>'whenToChoose', '')
             ) not between 1 and 200
        then
          return false;
        end if;
      end loop;
    end if;
  end loop;

  if p_content ? 'assumptions' and (
    pg_catalog.jsonb_typeof(p_content->'assumptions') <> 'array'
    or pg_catalog.jsonb_array_length(p_content->'assumptions') > 4
  ) then
    return false;
  end if;

  if p_content ? 'uncertainties' and (
    pg_catalog.jsonb_typeof(p_content->'uncertainties') <> 'array'
    or pg_catalog.jsonb_array_length(p_content->'uncertainties') > 3
  ) then
    return false;
  end if;

  if p_content ? 'safetyConsiderations' and (
    pg_catalog.jsonb_typeof(p_content->'safetyConsiderations') <> 'array'
    or pg_catalog.jsonb_array_length(p_content->'safetyConsiderations') > 3
  ) then
    return false;
  end if;

  -- Sessions the coach suggests cancelling, each by the handle of a session
  -- the owner left open (ADR-033). Only the shape is checked here;
  -- `finish_plan_generation` holds each handle to the request it answers.
  if p_content ? 'cancels'
    and pg_catalog.jsonb_typeof(p_content->'cancels') <> 'null'
  then
    if pg_catalog.jsonb_typeof(p_content->'cancels') <> 'array'
      or pg_catalog.jsonb_array_length(p_content->'cancels') > 21
    then
      return false;
    end if;
    for v_cancel in
      select value from pg_catalog.jsonb_array_elements(p_content->'cancels')
    loop
      if pg_catalog.jsonb_typeof(v_cancel) <> 'object'
        or exists (
          select 1
          from pg_catalog.jsonb_object_keys(v_cancel) as key
          where key not in ('replaceHandle', 'reason')
        )
        or pg_catalog.jsonb_typeof(v_cancel->'replaceHandle')
           is distinct from 'string'
        or (v_cancel->>'replaceHandle') !~ '^r[1-9][0-9]?$'
        or pg_catalog.jsonb_typeof(v_cancel->'reason') is distinct from 'string'
        or pg_catalog.char_length(pg_catalog.btrim(v_cancel->>'reason'))
           not between 1 and 160
      then
        return false;
      end if;
    end loop;
  end if;

  return true;
exception
  when others then
    -- A malformed date or number cast is invalid content, not a server error.
    return false;
end;
$_$;


ALTER FUNCTION "public"."plan_content_is_valid"("p_content" "jsonb", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_goal_suggestion"("p_source" "text", "p_completion_token" "uuid", "p_suggestion" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_proposal_id uuid;
  v_note text;
  v_origin text;
  v_today date;
  v_reference text;
  v_existing uuid;
  v_id uuid;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_source not in ('plan', 'roadmap') or p_completion_token is null then
    raise exception using
      errcode = '22023',
      message = 'Invalid goal suggestion.';
  end if;

  if p_source = 'plan' then
    select proposal.id, proposal.planning_note, null
    into v_proposal_id, v_note, v_origin
    from public.plan_generation_requests request
    join public.plan_proposals proposal
      on proposal.id = request.proposal_id
      and proposal.user_id = request.user_id
    where request.user_id = v_user_id
      and request.completion_token = p_completion_token
      and request.status = 'completed';
  else
    select proposal.id, proposal.planning_note, proposal.origin
    into v_proposal_id, v_note, v_origin
    from public.roadmap_generation_requests request
    join public.roadmap_proposals proposal
      on proposal.id = request.proposal_id
      and proposal.user_id = request.user_id
    where request.user_id = v_user_id
      and request.completion_token = p_completion_token
      and request.status = 'completed';
  end if;

  if v_proposal_id is null or v_origin is not distinct from 'owner_edit' then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  -- Only from the planning note (owner): without one there is nothing to
  -- draw a suggestion from.
  if v_note is null then
    raise exception using
      errcode = '22023',
      message = 'Invalid goal suggestion.';
  end if;

  v_reference := p_source || '-proposal:' || v_proposal_id::text;

  -- A replay returns the row it made; one per proposal either way.
  select id into v_existing
  from public.goal_suggestions
  where user_id = v_user_id and source_reference = v_reference;
  if found then
    return v_existing;
  end if;

  select coalesce(
    (pg_catalog.timezone(profile.timezone_name, pg_catalog.clock_timestamp()))::date,
    (pg_catalog.clock_timestamp() at time zone 'utc')::date
  )
  into v_today
  from public.profiles profile
  where profile.user_id = v_user_id;

  if not public.goal_suggestion_fields_are_valid(p_suggestion, v_today) then
    raise exception using
      errcode = '22023',
      message = 'Invalid goal suggestion.';
  end if;

  insert into public.goal_suggestions (
    user_id, source_reference, title, desired_outcome, sports, target_date
  ) values (
    v_user_id,
    v_reference,
    pg_catalog.btrim(p_suggestion->>'title'),
    pg_catalog.btrim(p_suggestion->>'desiredOutcome'),
    array(
      select pg_catalog.btrim(sport.value #>> '{}')
      from pg_catalog.jsonb_array_elements(p_suggestion->'sports')
        with ordinality as sport(value, ordinality)
      order by sport.ordinality
    ),
    case
      when pg_catalog.jsonb_typeof(p_suggestion->'targetDate') = 'string'
      then (p_suggestion->>'targetDate')::date
    end
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_goal_suggestion"("p_source" "text", "p_completion_token" "uuid", "p_suggestion" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_plan_memory_candidates"("p_completion_token" "uuid", "p_expected_memory_revision" bigint, "p_candidates" "jsonb") RETURNS "public"."plan_memory_candidate_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.plan_generation_requests;
  v_proposal public.plan_proposals;
  v_current_revision bigint;
  v_new_revision bigint;
  v_candidate jsonb;
  v_ordinal integer := 0;
  v_content text;
  v_type text;
  v_confidence smallint;
  v_item_id uuid;
  v_revision_id uuid;
  v_source_reference text;
  v_item_ids uuid[] := array[]::uuid[];
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_completion_token is null
    or p_expected_memory_revision is null
    or p_expected_memory_revision < 0
    or p_candidates is null
    or pg_catalog.jsonb_typeof(p_candidates) <> 'array'
    or pg_catalog.jsonb_array_length(p_candidates) not between 1 and 4
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory candidates.';
  end if;

  select * into v_request
  from public.plan_generation_requests
  where user_id = v_user_id
    and completion_token = p_completion_token
    and status = 'completed';

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  select * into v_proposal
  from public.plan_proposals
  where id = v_request.proposal_id
    and user_id = v_user_id;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  -- With no planning note there is nothing for a candidate to be drawn from.
  if v_proposal.planning_note is null then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory candidates.';
  end if;

  -- ADR-010's owner lock, stale-revision check and collection increment, with
  -- decision 11's bounded wait: a contended save answers with a conflict the
  -- caller can act on rather than hanging. The lock key matches the roadmap
  -- route's, because both serialize the same owner's memory collection.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62002,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Memory changed. Reload and try again.';
  end;

  -- Retry returns the existing candidates rather than duplicating them. The
  -- source reference is the proposal plus the candidate ordinal, so the same
  -- batch replayed maps onto the same rows.
  if exists (
    select 1
    from public.memory_items
    where user_id = v_user_id
      and source_reference like 'plan-proposal:' || v_proposal.id::text || ':%'
  ) then
    select
      coalesce(
        (select revision from public.memory_collections where user_id = v_user_id),
        0
      ),
      pg_catalog.array_agg(id order by source_reference)
    into v_new_revision, v_item_ids
    from public.memory_items
    where user_id = v_user_id
      and source_reference like 'plan-proposal:' || v_proposal.id::text || ':%';

    return (v_new_revision, v_item_ids)
      ::public.plan_memory_candidate_receipt;
  end if;

  select revision into v_current_revision
  from public.memory_collections
  where user_id = v_user_id;
  v_current_revision := coalesce(v_current_revision, 0);

  if v_current_revision <> p_expected_memory_revision then
    raise exception using
      errcode = 'PT409',
      message = 'Memory changed. Reload and try again.';
  end if;

  v_new_revision := v_current_revision + 1;

  for v_candidate in
    select value from pg_catalog.jsonb_array_elements(p_candidates)
  loop
    if exists (
      select 1
      from pg_catalog.jsonb_object_keys(v_candidate) as key
      where key not in ('memoryType', 'content', 'confidence')
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory candidates.';
    end if;

    v_type := v_candidate->>'memoryType';
    if v_type not in (
      'profile_fact', 'constraint', 'preference', 'observed_pattern'
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory candidates.';
    end if;

    -- The coach's own sentence (ADR-010 decision 16, amended 18 Oct 2026).
    -- Normalized as the application normalized it, and bounded; nothing ties
    -- it to the note's wording any more, which is the owner's decision.
    v_content := public.roadmap_normalize_owner_text(
      v_candidate->>'content'
    );
    if v_content is null
      or pg_catalog.char_length(v_content) not between 1 and 200
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory candidates.';
    end if;

    v_confidence := null;
    if v_candidate ? 'confidence'
      and pg_catalog.jsonb_typeof(v_candidate->'confidence') <> 'null'
    then
      if pg_catalog.jsonb_typeof(v_candidate->'confidence') <> 'number' then
        raise exception using
          errcode = '22023',
          message = 'Invalid memory candidates.';
      end if;
      v_confidence := (v_candidate->>'confidence')::numeric;
      if v_confidence not between 0 and 100 then
        raise exception using
          errcode = '22023',
          message = 'Invalid memory candidates.';
      end if;
    end if;

    v_item_id := gen_random_uuid();
    v_revision_id := gen_random_uuid();
    v_source_reference :=
      'plan-proposal:' || v_proposal.id::text || ':' || v_ordinal::text;

    -- Owner, provenance, author class, status and timestamps are derived here.
    -- None of them is a caller input, which is what keeps this route unable to
    -- create anything but a proposal.
    insert into public.memory_revisions (
      id, user_id, item_id, revision_number, content, author_class,
      provenance, change_kind, status_after, previous_revision_id, created_at
    )
    values (
      v_revision_id, v_user_id, v_item_id, 1, v_content, 'system',
      'inferred_proposed', 'created', 'proposed', null, v_now
    );

    insert into public.memory_items (
      id, user_id, memory_type, status, provenance, confidence,
      source_reference, expires_on, current_revision_id, user_confirmed_at,
      status_changed_at, created_at, updated_at
    )
    values (
      v_item_id, v_user_id, v_type, 'proposed', 'inferred_proposed',
      v_confidence, v_source_reference, null, v_revision_id, null,
      v_now, v_now, v_now
    );

    v_item_ids := v_item_ids || v_item_id;
    v_ordinal := v_ordinal + 1;
  end loop;

  insert into public.memory_collections (user_id, revision, updated_at)
  values (v_user_id, v_new_revision, v_now)
  on conflict (user_id)
  do update set revision = excluded.revision, updated_at = excluded.updated_at;

  return (v_new_revision, v_item_ids)
    ::public.plan_memory_candidate_receipt;
end;
$$;


ALTER FUNCTION "public"."record_plan_memory_candidates"("p_completion_token" "uuid", "p_expected_memory_revision" bigint, "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_roadmap_memory_candidates"("p_completion_token" "uuid", "p_expected_memory_revision" bigint, "p_candidates" "jsonb") RETURNS "public"."roadmap_memory_candidate_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_request public.roadmap_generation_requests;
  v_proposal public.roadmap_proposals;
  v_current_revision bigint;
  v_new_revision bigint;
  v_candidate jsonb;
  v_ordinal integer := 0;
  v_content text;
  v_type text;
  v_confidence smallint;
  v_item_id uuid;
  v_revision_id uuid;
  v_source_reference text;
  v_item_ids uuid[] := array[]::uuid[];
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_completion_token is null
    or p_expected_memory_revision is null
    or p_expected_memory_revision < 0
    or p_candidates is null
    or pg_catalog.jsonb_typeof(p_candidates) <> 'array'
    or pg_catalog.jsonb_array_length(p_candidates) not between 1 and 4
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory candidates.';
  end if;

  select * into v_request
  from public.roadmap_generation_requests
  where user_id = v_user_id
    and completion_token = p_completion_token
    and status = 'completed';

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  select * into v_proposal
  from public.roadmap_proposals
  where id = v_request.proposal_id
    and user_id = v_user_id;

  if not found or v_proposal.origin = 'owner_edit' then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching request is no longer open.';
  end if;

  -- With no planning note there is nothing for a candidate to be drawn from.
  if v_proposal.planning_note is null then
    raise exception using
      errcode = '22023',
      message = 'Invalid memory candidates.';
  end if;

  -- ADR-010's owner lock, stale-revision check and collection increment.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62002,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Memory changed. Reload and try again.';
  end;

  -- Retry returns the existing candidates rather than duplicating them. The
  -- source reference is the proposal plus the candidate ordinal, so the same
  -- batch replayed maps onto the same rows.
  if exists (
    select 1
    from public.memory_items
    where user_id = v_user_id
      and source_reference like 'roadmap-proposal:' || v_proposal.id::text || ':%'
  ) then
    select
      coalesce(
        (select revision from public.memory_collections where user_id = v_user_id),
        0
      ),
      pg_catalog.array_agg(id order by source_reference)
    into v_new_revision, v_item_ids
    from public.memory_items
    where user_id = v_user_id
      and source_reference like 'roadmap-proposal:' || v_proposal.id::text || ':%';

    return (v_new_revision, v_item_ids)
      ::public.roadmap_memory_candidate_receipt;
  end if;

  select revision into v_current_revision
  from public.memory_collections
  where user_id = v_user_id;
  v_current_revision := coalesce(v_current_revision, 0);

  if v_current_revision <> p_expected_memory_revision then
    raise exception using
      errcode = 'PT409',
      message = 'Memory changed. Reload and try again.';
  end if;

  v_new_revision := v_current_revision + 1;

  for v_candidate in
    select value from pg_catalog.jsonb_array_elements(p_candidates)
  loop
    if exists (
      select 1
      from pg_catalog.jsonb_object_keys(v_candidate) as key
      where key not in ('memoryType', 'content', 'confidence')
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory candidates.';
    end if;

    v_type := v_candidate->>'memoryType';
    if v_type not in (
      'profile_fact', 'constraint', 'preference', 'observed_pattern'
    ) then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory candidates.';
    end if;

    -- The coach's own sentence (ADR-010 decision 16, amended 18 Oct 2026).
    -- Normalized as the application normalized it, and bounded; nothing ties
    -- it to the note's wording any more, which is the owner's decision.
    v_content := public.roadmap_normalize_owner_text(
      v_candidate->>'content'
    );
    if v_content is null
      or pg_catalog.char_length(v_content) not between 1 and 200
    then
      raise exception using
        errcode = '22023',
        message = 'Invalid memory candidates.';
    end if;

    v_confidence := null;
    if v_candidate ? 'confidence'
      and pg_catalog.jsonb_typeof(v_candidate->'confidence') <> 'null'
    then
      if pg_catalog.jsonb_typeof(v_candidate->'confidence') <> 'number' then
        raise exception using
          errcode = '22023',
          message = 'Invalid memory candidates.';
      end if;
      v_confidence := (v_candidate->>'confidence')::numeric;
      if v_confidence not between 0 and 100 then
        raise exception using
          errcode = '22023',
          message = 'Invalid memory candidates.';
      end if;
    end if;

    v_item_id := gen_random_uuid();
    v_revision_id := gen_random_uuid();
    v_source_reference :=
      'roadmap-proposal:' || v_proposal.id::text || ':' || v_ordinal::text;

    -- Owner, provenance, author class, status and timestamps are derived here.
    -- None of them is a caller input, which is what keeps this route unable to
    -- create anything but a proposal.
    insert into public.memory_revisions (
      id, user_id, item_id, revision_number, content, author_class,
      provenance, change_kind, status_after, previous_revision_id, created_at
    )
    values (
      v_revision_id, v_user_id, v_item_id, 1, v_content, 'system',
      'inferred_proposed', 'created', 'proposed', null, v_now
    );

    insert into public.memory_items (
      id, user_id, memory_type, status, provenance, confidence,
      source_reference, expires_on, current_revision_id, user_confirmed_at,
      status_changed_at, created_at, updated_at
    )
    values (
      v_item_id, v_user_id, v_type, 'proposed', 'inferred_proposed',
      v_confidence, v_source_reference, null, v_revision_id, null,
      v_now, v_now, v_now
    );

    v_item_ids := v_item_ids || v_item_id;
    v_ordinal := v_ordinal + 1;
  end loop;

  insert into public.memory_collections (user_id, revision, updated_at)
  values (v_user_id, v_new_revision, v_now)
  on conflict (user_id)
  do update set revision = excluded.revision, updated_at = excluded.updated_at;

  return (v_new_revision, v_item_ids)
    ::public.roadmap_memory_candidate_receipt;
end;
$$;


ALTER FUNCTION "public"."record_roadmap_memory_candidates"("p_completion_token" "uuid", "p_expected_memory_revision" bigint, "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_sport"("p_sport_id" "uuid", "p_name" "text", "p_merge" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_old text;
  v_new text := public.tidy_sport_name(p_name);
  v_kept uuid;
  v_existing text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  if v_new is null or v_new = ''
    or pg_catalog.char_length(v_new) > 60
    or pg_catalog.strpos(v_new, ',') > 0
  then
    raise exception using errcode = '22023',
      message = 'A sport is a name of up to 60 characters, without a comma.';
  end if;

  perform 1 from public.profiles where user_id = v_user_id for update;
  select name into v_old
  from public.sports
  where id = p_sport_id and user_id = v_user_id
  for update;
  if not found then
    raise exception using errcode = 'P0002',
      message = 'That sport is no longer on your list.';
  end if;

  select id, name into v_kept, v_existing
  from public.sports
  where user_id = v_user_id and id <> p_sport_id
    and pg_catalog.lower(name) = pg_catalog.lower(v_new);
  if found then
    if not coalesce(p_merge, false) then
      raise exception using errcode = '23505',
        message = 'You already have that sport.';
    end if;
    delete from public.sports where id = p_sport_id and user_id = v_user_id;
    v_new := v_existing;
  else
    update public.sports set name = v_new
    where id = p_sport_id and user_id = v_user_id;
    v_kept := p_sport_id;
  end if;

  update public.rolling_plan_sessions set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.rolling_plan_activities set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.rolling_plan_series set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.rolling_plan_series_activities set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.saved_sessions as saved
  set
    sport = case
      when pg_catalog.lower(public.tidy_sport_name(saved.sport))
        = pg_catalog.lower(v_old) then v_new
      else saved.sport
    end,
    revision = saved.revision + 1
  where saved.user_id = v_user_id
    and (
      pg_catalog.lower(public.tidy_sport_name(saved.sport)) = pg_catalog.lower(v_old)
      or exists (
        select 1 from public.saved_session_activities as activity
        where activity.saved_session_id = saved.id
          and pg_catalog.lower(public.tidy_sport_name(activity.sport))
            = pg_catalog.lower(v_old)
      )
    );
  update public.saved_session_activities set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.personal_activities set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.live_workouts set sport = v_new, revision = revision + 1
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);
  update public.completions as log
  set
    sport = case
      when pg_catalog.lower(public.tidy_sport_name(log.sport))
        = pg_catalog.lower(v_old)
        or (
          log.sport is null
          and pg_catalog.lower(public.tidy_sport_name(log.planned_snapshot ->> 'sport'))
            = pg_catalog.lower(v_old)
        )
      then v_new
      else log.sport
    end,
    revision = log.revision + 1
  where log.user_id = v_user_id
    and (
      pg_catalog.lower(public.tidy_sport_name(log.sport)) = pg_catalog.lower(v_old)
      or (
        log.sport is null
        and pg_catalog.lower(public.tidy_sport_name(log.planned_snapshot ->> 'sport'))
          = pg_catalog.lower(v_old)
      )
      or exists (
        select 1 from public.completion_activities as activity
        where activity.completion_id = log.id
          and pg_catalog.lower(public.tidy_sport_name(activity.sport))
            = pg_catalog.lower(v_old)
      )
    );
  update public.completion_activities set sport = v_new
  where user_id = v_user_id
    and pg_catalog.lower(public.tidy_sport_name(sport)) = pg_catalog.lower(v_old);

  -- A goal names each sport once, so a merge leaves one of the two.
  update public.goals as goal
  set sports = array(
    select renamed.name
    from (
      select distinct on (pg_catalog.lower(entry.name)) entry.name, entry.ord
      from (
        select
          case
            when pg_catalog.lower(public.tidy_sport_name(listed.raw))
              = pg_catalog.lower(v_old) then v_new
            else listed.raw
          end as name,
          listed.ord
        from pg_catalog.unnest(goal.sports) with ordinality as listed(raw, ord)
      ) as entry
      order by pg_catalog.lower(entry.name), entry.ord
    ) as renamed
    order by renamed.ord
  )
  where goal.user_id = v_user_id
    and exists (
      select 1 from pg_catalog.unnest(goal.sports) as listed(raw)
      where pg_catalog.lower(public.tidy_sport_name(listed.raw)) = pg_catalog.lower(v_old)
    );

  return v_kept;
end;
$$;


ALTER FUNCTION "public"."rename_sport"("p_sport_id" "uuid", "p_name" "text", "p_merge" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rename_sport"("p_sport_id" "uuid", "p_name" "text", "p_merge" boolean) IS 'Renames the caller''s sport and every record of theirs that names it (owner, 6 Nov 2026). Owner from auth.uid() only.';



CREATE OR REPLACE FUNCTION "public"."reserve_ai_spend"("p_operation" "text", "p_reserved_micro_usd" bigint, "p_rate_card_version" "text", "p_currency" "text") RETURNS "public"."ai_spend_reservation_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  -- M3-01B decision 4, as approved on 10 August 2026. Changing a ceiling is a
  -- forward migration under review, which is the point: the only ceiling that
  -- survives a bug in the application is one the application cannot reach.
  -- 9,000 since 19 October 2026 (owner, ADR-034): the input ceiling rose to
  -- 20,000 tokens, and a reservation is 2,500 + 5,750 = 8,250.
  c_per_request_ceiling constant bigint := 9000;
  c_daily_ceiling constant bigint := 2000000;
  c_total_ceiling constant bigint := 20000000;
  -- Longer than the 30s deadlineMs by 30x, which leaves room for the
  -- settlement round trip, clock skew, and a frozen serverless instance
  -- between the provider response and the settle call.
  --
  -- It no longer bounds how long a hold counts. Until ADR-019 the second half
  -- of this comment read that a crashed call cannot hold budget past midnight
  -- and lock the owner out with no visible cause -- which is exactly what this
  -- change gives up, deliberately, because forgiving a charge we failed to
  -- record is the worse failure. `expires_at` is still written and still
  -- readable; nothing in the ceiling arithmetic consults it any more.
  c_reservation_ttl constant interval := interval '15 minutes';
  v_user_id uuid;
  v_now timestamptz := pg_catalog.now();
  v_day date := (pg_catalog.now() at time zone 'utc')::date;
  v_rate_card text;
  v_receipt public.ai_spend_reservation_receipt;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (
    select 1
    from public.profiles
    where user_id = v_user_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_operation is null
    or p_operation not in (
      'create_roadmap', 'create_seven_day_plan', 'fill_session_activities'
    )
    or p_reserved_micro_usd is null
    or p_reserved_micro_usd <= 0
    or p_currency is distinct from 'USD'
    or p_rate_card_version is null
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid coaching spend reservation.';
  end if;

  v_rate_card := trim(p_rate_card_version);
  if char_length(v_rate_card) not between 1 and 100 then
    raise exception using
      errcode = '22023',
      message = 'Invalid coaching spend reservation.';
  end if;

  -- The per-request ceiling is checked before the daily one so a single
  -- runaway request is refused on its own terms rather than as budget
  -- exhaustion.
  if p_reserved_micro_usd > c_per_request_ceiling then
    raise exception using
      errcode = 'PT402',
      message = 'Coaching spend ceiling reached.';
  end if;

  -- ADR-010. The check and the write below are one statement, but a lone
  -- INSERT ... SELECT ... WHERE does not lock the rows it aggregates, so under
  -- READ COMMITTED two concurrent reservations would both read the same total
  -- and both pass. Serializing per owner is what actually closes the race.
  -- Every wait is bounded, so exhaustion is a conflict the caller can act on
  -- rather than a silent hang.
  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62004,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'A coaching suggestion is already being prepared.';
  end;

  -- One statement: the ceilings are evaluated in the WHERE clause of the
  -- insert itself, so there is no window between deciding and writing. A
  -- settled reservation holds exactly what it was charged; an unsettled one
  -- holds what it reserved, for good. It used to stop holding anything once it
  -- expired, and ADR-019 removed that: a reservation nobody settled is one
  -- where money may well have been spent and we failed to record it.
  insert into public.ai_spend_reservations (
    user_id,
    operation,
    spend_day,
    reserved_micro_usd,
    rate_card_version,
    currency,
    expires_at,
    created_at
  )
  select
    v_user_id,
    p_operation,
    v_day,
    p_reserved_micro_usd,
    v_rate_card,
    'USD',
    v_now + c_reservation_ttl,
    v_now
  where (
      select coalesce(sum(
        case
          when r.settled_at is not null then r.charged_micro_usd
          else r.reserved_micro_usd
        end
      ), 0)
      from public.ai_spend_reservations r
      where r.user_id = v_user_id
        and r.spend_day = v_day
    ) + p_reserved_micro_usd <= c_daily_ceiling
    and (
      select coalesce(sum(
        case
          when r.settled_at is not null then r.charged_micro_usd
          else r.reserved_micro_usd
        end
      ), 0)
      from public.ai_spend_reservations r
      where r.user_id = v_user_id
    ) + p_reserved_micro_usd <= c_total_ceiling
  returning
    id,
    settlement_token,
    spend_day,
    reserved_micro_usd,
    expires_at
  into v_receipt;

  if not found then
    raise exception using
      errcode = 'PT402',
      message = 'Coaching spend ceiling reached.';
  end if;

  return v_receipt;
end;
$$;


ALTER FUNCTION "public"."reserve_ai_spend"("p_operation" "text", "p_reserved_micro_usd" bigint, "p_rate_card_version" "text", "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roadmap_content_is_valid"("p_content" "jsonb", "p_start_date" "date", "p_end_date" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_phase jsonb;
  v_entry jsonb;
  v_count integer;
begin
  if p_content is null or pg_catalog.jsonb_typeof(p_content) <> 'object' then
    return false;
  end if;

  if pg_catalog.octet_length(p_content::text) > 16000 then
    return false;
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_object_keys(p_content) as key
    where key not in (
      'schemaVersion', 'title', 'summary', 'startDate', 'endDate', 'phases'
    )
  ) then
    return false;
  end if;

  -- The summary may be left out (owner, 14 Oct 2026). One that is there is
  -- text of one to six hundred characters; a null is not a summary left out.
  if p_content->>'schemaVersion' is distinct from 'fittip.roadmap.v4'
    or pg_catalog.char_length(coalesce(p_content->>'title', ''))
       not between 1 and 80
    or (
      p_content ? 'summary'
      and pg_catalog.char_length(coalesce(p_content->>'summary', ''))
          not between 1 and 600
    )
    or (p_content->>'startDate')::date is distinct from p_start_date
    or (p_content->>'endDate')::date is distinct from p_end_date
  then
    return false;
  end if;

  if pg_catalog.jsonb_typeof(p_content->'phases') <> 'array' then
    return false;
  end if;
  v_count := pg_catalog.jsonb_array_length(p_content->'phases');
  if v_count not between 1 and 6 then
    return false;
  end if;

  for v_phase in
    select value from pg_catalog.jsonb_array_elements(p_content->'phases')
  loop
    if pg_catalog.jsonb_typeof(v_phase) <> 'object' then
      return false;
    end if;
    if exists (
      select 1
      from pg_catalog.jsonb_object_keys(v_phase) as key
      where key not in (
        'title', 'focus', 'startDate', 'endDate', 'goalAttention', 'milestones'
      )
    ) then
      return false;
    end if;
    if pg_catalog.char_length(coalesce(v_phase->>'title', ''))
         not between 1 and 80
      or pg_catalog.char_length(coalesce(v_phase->>'focus', ''))
         not between 1 and 300
      or (v_phase->>'startDate')::date < p_start_date
      or (v_phase->>'endDate')::date > p_end_date
      or (v_phase->>'endDate')::date < (v_phase->>'startDate')::date
    then
      return false;
    end if;
    -- A phase may have no milestone. `is distinct from` rather than `<>`, so a
    -- missing list is refused instead of comparing as unknown.
    if pg_catalog.jsonb_typeof(v_phase->'milestones') is distinct from 'array'
      or pg_catalog.jsonb_array_length(v_phase->'milestones') > 3
      or pg_catalog.jsonb_typeof(v_phase->'goalAttention')
         is distinct from 'array'
      or pg_catalog.jsonb_array_length(v_phase->'goalAttention')
         not between 1 and 4
    then
      return false;
    end if;
    for v_entry in
      select value from pg_catalog.jsonb_array_elements(v_phase->'goalAttention')
    loop
      if pg_catalog.jsonb_typeof(v_entry) is distinct from 'object' then
        return false;
      end if;
      -- A level and nothing beside it.
      if exists (
        select 1
        from pg_catalog.jsonb_object_keys(v_entry) as key
        where key not in ('goalId', 'level')
      ) then
        return false;
      end if;
      if coalesce(v_entry->>'level', '') not in
        ('primary', 'secondary', 'maintenance', 'deferred')
      then
        return false;
      end if;
    end loop;
  end loop;

  return true;
exception
  when others then
    -- A malformed date cast is invalid content, not a server error.
    return false;
end;
$$;


ALTER FUNCTION "public"."roadmap_content_is_valid"("p_content" "jsonb", "p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roadmap_normalize_owner_text"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- `normalize(text, NFC)` is special grammar, so the form keyword cannot be
  -- reached through a schema-qualified call. pg_catalog is implicitly first in
  -- the search path even when search_path is empty, so the bare name is still
  -- unambiguous.
  select pg_catalog.btrim(
    normalize(
      pg_catalog.replace(
        pg_catalog.replace(p_value, pg_catalog.chr(13) || pg_catalog.chr(10),
          pg_catalog.chr(10)),
        pg_catalog.chr(13),
        pg_catalog.chr(10)
      ),
      NFC
    ),
    concat(
      ' ',
      pg_catalog.chr(9),
      pg_catalog.chr(10),
      pg_catalog.chr(11),
      pg_catalog.chr(12),
      pg_catalog.chr(13)
    )
  );
$$;


ALTER FUNCTION "public"."roadmap_normalize_owner_text"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roadmap_owner_text_hash"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_value is null then null
    else pg_catalog.encode(
      extensions.digest(public.roadmap_normalize_owner_text(p_value), 'sha256'),
      'hex'
    )
  end;
$$;


