CREATE OR REPLACE FUNCTION "public"."rolling_plan_occurrence_id"("p_series_id" "uuid", "p_occurrence_date" "date") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (
    pg_catalog.substr(digest_hex, 1, 8) || '-'
    || pg_catalog.substr(digest_hex, 9, 4) || '-4'
    || pg_catalog.substr(digest_hex, 14, 3) || '-8'
    || pg_catalog.substr(digest_hex, 18, 3) || '-'
    || pg_catalog.substr(digest_hex, 21, 12)
  )::uuid
  from (
    select pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
      p_series_id::text || '|' || p_occurrence_date::text, 'UTF8'
    ), 'sha256'), 'hex') as digest_hex
  ) as derived;
$$;


ALTER FUNCTION "public"."rolling_plan_occurrence_id"("p_series_id" "uuid", "p_occurrence_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rolling_plan_recovery_days_reject_owner_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.user_id is distinct from old.user_id then
    raise exception using errcode = '42501',
      message = 'A recovery day owner cannot be reassigned.';
  end if;
  return new;
end;
$$;


