CREATE OR REPLACE FUNCTION "public"."rolling_plan_weekday_set_is_valid"("p_value" smallint[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_value is not null
    and pg_catalog.array_length(p_value, 1) between 1 and 7
    and p_value <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]
    and p_value = (
      select pg_catalog.array_agg(distinct weekday order by weekday)
      from pg_catalog.unnest(p_value) as weekday
    );
$$;


ALTER FUNCTION "public"."rolling_plan_weekday_set_is_valid"("p_value" smallint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."saved_session_activity_input_is_valid"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_position numeric;
  v_mode text;
begin
  if p_value is null or pg_catalog.jsonb_typeof(p_value) <> 'object'
    or p_value - array[
      'personalActivityId', 'position', 'name', 'sport', 'instructions',
      'measurementMode', 'target'
    ] <> '{}'::jsonb
    or not (p_value ?& array['position', 'name', 'sport', 'measurementMode'])
    or pg_catalog.jsonb_typeof(p_value->'position') <> 'number'
    or pg_catalog.jsonb_typeof(p_value->'name') <> 'string'
    or pg_catalog.jsonb_typeof(p_value->'sport') <> 'string'
    or pg_catalog.jsonb_typeof(p_value->'measurementMode') <> 'string'
  then return false; end if;

  v_position := (p_value->>'position')::numeric;
  v_mode := p_value->>'measurementMode';
  if v_position <> trunc(v_position) or v_position not between 0 and 99
    or pg_catalog.char_length(pg_catalog.btrim(p_value->>'name')) not between 1 and 120
    or pg_catalog.char_length(pg_catalog.btrim(p_value->>'sport')) not between 1 and 80
    or (p_value ? 'instructions'
      and pg_catalog.jsonb_typeof(p_value->'instructions') not in ('string', 'null'))
    or pg_catalog.char_length(coalesce(p_value->>'instructions', '')) > 2000
    or not public.is_training_measurement_mode(v_mode)
    -- An absent target and an explicit null target mean the same thing here:
    -- the activity carries no measurement target.
    or not public.is_valid_training_measurement(
      v_mode, nullif(p_value->'target', 'null'::jsonb))
  then return false; end if;

  if p_value ? 'personalActivityId'
    and pg_catalog.jsonb_typeof(p_value->'personalActivityId') <> 'null'
  then
    if pg_catalog.jsonb_typeof(p_value->'personalActivityId') <> 'string' then
      return false;
    end if;
    perform (p_value->>'personalActivityId')::uuid;
  end if;
  return true;
exception when others then return false;
end;
$$;


ALTER FUNCTION "public"."saved_session_activity_input_is_valid"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."saved_sessions_reject_owner_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.user_id is distinct from old.user_id then
    raise exception using errcode = '42501',
      message = 'A saved session owner cannot be reassigned.';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."saved_sessions_reject_owner_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."session_activities_content_is_valid"("p_content" "jsonb", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_activity jsonb;
  v_mode text;
  v_link text;
  v_entry jsonb;
begin
  if p_content is null
    or pg_catalog.jsonb_typeof(p_content) <> 'object'
    or exists (
      select 1 from pg_catalog.jsonb_object_keys(p_content) as key
      where key not in (
        'schemaVersion', 'summary', 'activities', 'safetyConsiderations'
      )
    )
    or p_content->>'schemaVersion' is distinct from 'fittip.session-activities.v1'
    or pg_catalog.jsonb_typeof(p_content->'summary') <> 'string'
    or pg_catalog.char_length(pg_catalog.btrim(p_content->>'summary'))
      not between 1 and 400
    or pg_catalog.jsonb_typeof(p_content->'activities') <> 'array'
    or pg_catalog.jsonb_array_length(p_content->'activities') not between 1 and 12
  then
    return false;
  end if;

  if p_content ? 'safetyConsiderations' then
    if pg_catalog.jsonb_typeof(p_content->'safetyConsiderations') <> 'array'
      or pg_catalog.jsonb_array_length(p_content->'safetyConsiderations') > 3
    then
      return false;
    end if;
    for v_entry in
      select value
      from pg_catalog.jsonb_array_elements(p_content->'safetyConsiderations')
    loop
      if pg_catalog.jsonb_typeof(v_entry) <> 'string'
        or pg_catalog.char_length(pg_catalog.btrim(v_entry #>> '{}'))
          not between 1 and 240
      then
        return false;
      end if;
    end loop;
  end if;

  for v_activity in
    select value from pg_catalog.jsonb_array_elements(p_content->'activities')
  loop
    if pg_catalog.jsonb_typeof(v_activity) <> 'object'
      or exists (
        select 1 from pg_catalog.jsonb_object_keys(v_activity) as key
        where key not in (
          'personalActivityId', 'name', 'sport', 'instructions',
          'measurementMode', 'target', 'rationale'
        )
      )
      or pg_catalog.jsonb_typeof(v_activity->'name') <> 'string'
      or pg_catalog.char_length(pg_catalog.btrim(v_activity->>'name'))
        not between 1 and 120
      or pg_catalog.jsonb_typeof(v_activity->'sport') <> 'string'
      or pg_catalog.char_length(pg_catalog.btrim(v_activity->>'sport'))
        not between 1 and 80
      or pg_catalog.jsonb_typeof(v_activity->'rationale') <> 'string'
      or pg_catalog.char_length(pg_catalog.btrim(v_activity->>'rationale'))
        not between 1 and 300
      or (
        coalesce(pg_catalog.jsonb_typeof(v_activity->'instructions'), 'null')
          <> 'null'
        and (
          pg_catalog.jsonb_typeof(v_activity->'instructions') <> 'string'
          or pg_catalog.char_length(pg_catalog.btrim(v_activity->>'instructions'))
            not between 1 and 500
        )
      )
    then
      return false;
    end if;

    v_mode := v_activity->>'measurementMode';
    if v_mode is null or not public.is_training_measurement_mode(v_mode) then
      return false;
    end if;

    if coalesce(pg_catalog.jsonb_typeof(v_activity->'target'), 'null') = 'null'
    then
      null;
    elsif v_mode = 'unmeasured'
      or not public.is_valid_training_measurement(v_mode, v_activity->'target')
    then
      return false;
    end if;

    if coalesce(pg_catalog.jsonb_typeof(v_activity->'personalActivityId'), 'null')
      <> 'null'
    then
      v_link := v_activity->>'personalActivityId';
      if not exists (
        select 1
        from public.personal_activities activity
        where activity.id = v_link::uuid
          and activity.user_id = p_user_id
          and activity.measurement_mode = v_mode
      ) then
        return false;
      end if;
    end if;
  end loop;

  return true;
exception
  when others then
    -- A malformed uuid or number cast is invalid content, not a server error.
    return false;
end;
$$;


ALTER FUNCTION "public"."session_activities_content_is_valid"("p_content" "jsonb", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_roadmap_milestone_reached"("p_version_id" "uuid", "p_phase_index" integer, "p_milestone_index" integer, "p_reached" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_content jsonb;
  v_today date;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'An authenticated FitTip user is required.';
  end if;
  if p_version_id is null or p_reached is null
    or p_phase_index is null or p_phase_index not between 0 and 5
    or p_milestone_index is null or p_milestone_index not between 0 and 2
  then
    raise exception using errcode = '22023', message = 'Invalid milestone mark.';
  end if;

  -- The head is locked for the length of the change, so a roadmap accepted at
  -- the same moment cannot leave a mark on the version it replaced.
  select version.content into v_content
  from public.roadmap_heads head
  join public.roadmap_versions version
    on version.id = head.current_version_id and version.user_id = head.user_id
  where head.user_id = v_user_id and head.current_version_id = p_version_id
  for update of head;
  if not found
    or pg_catalog.jsonb_typeof(
      v_content -> 'phases' -> p_phase_index -> 'milestones' -> p_milestone_index
    ) is distinct from 'object'
  then
    raise exception using errcode = '22023', message = 'Invalid milestone mark.';
  end if;

  if not p_reached then
    delete from public.roadmap_milestone_marks
    where version_id = p_version_id and user_id = v_user_id
      and phase_index = p_phase_index and milestone_index = p_milestone_index;
    return;
  end if;

  select (pg_catalog.timezone(
    coalesce(profile.timezone_name, 'UTC'), pg_catalog.now()
  ))::date into v_today
  from public.profiles profile
  where profile.user_id = v_user_id;

  insert into public.roadmap_milestone_marks (
    user_id, version_id, phase_index, milestone_index, reached_on
  )
  values (
    v_user_id, p_version_id, p_phase_index, p_milestone_index, v_today
  )
  on conflict (version_id, phase_index, milestone_index) do nothing;
end;
$$;


ALTER FUNCTION "public"."set_roadmap_milestone_reached"("p_version_id" "uuid", "p_phase_index" integer, "p_milestone_index" integer, "p_reached" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_roadmap_reviewed"("p_version_id" "uuid", "p_phase_index" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_content jsonb;
  v_today date;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'An authenticated FitTip user is required.';
  end if;
  if p_version_id is null
    or p_phase_index is null or p_phase_index not between 0 and 5
  then
    raise exception using errcode = '22023', message = 'Invalid roadmap review.';
  end if;

  -- The head is locked for the length of the change, so a roadmap accepted at
  -- the same moment cannot leave a mark on the version it replaced.
  select version.content into v_content
  from public.roadmap_heads head
  join public.roadmap_versions version
    on version.id = head.current_version_id and version.user_id = head.user_id
  where head.user_id = v_user_id and head.current_version_id = p_version_id
  for update of head;
  if not found then
    raise exception using errcode = '22023', message = 'Invalid roadmap review.';
  end if;

  select (pg_catalog.timezone(
    coalesce(profile.timezone_name, 'UTC'), pg_catalog.now()
  ))::date into v_today
  from public.profiles profile
  where profile.user_id = v_user_id;

  -- A phase the version does not have gives a null date, which is not on or
  -- before any day.
  if ((v_content -> 'phases' -> p_phase_index ->> 'endDate')::date <= v_today)
    is not true
  then
    raise exception using errcode = '22023', message = 'Invalid roadmap review.';
  end if;

  insert into public.roadmap_review_marks (
    version_id, user_id, phase_index, reviewed_on
  )
  values (p_version_id, v_user_id, p_phase_index, v_today)
  on conflict (version_id) do update set
    phase_index = excluded.phase_index,
    reviewed_on = excluded.reviewed_on,
    updated_at = pg_catalog.now()
  where public.roadmap_review_marks.user_id = v_user_id
    and public.roadmap_review_marks.phase_index < excluded.phase_index;
exception
  when invalid_datetime_format or datetime_field_overflow then
    -- A stored end date that is not a date is a phase that cannot be reviewed.
    raise exception using errcode = '22023', message = 'Invalid roadmap review.';
end;
$$;


ALTER FUNCTION "public"."set_roadmap_reviewed"("p_version_id" "uuid", "p_phase_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_session_cancellation_reason"("p_session_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_reason text := nullif(pg_catalog.btrim(p_reason, E' \t\r\n'), '');
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'An authenticated FitTip user is required.';
  end if;
  if p_session_id is null
    or (v_reason is not null
      and not public.rolling_plan_cancellation_reason_is_valid(pg_catalog.to_jsonb(v_reason)))
  then
    raise exception using errcode = '22023', message = 'Invalid cancellation reason.';
  end if;

  perform 1 from public.rolling_plan_sessions session
  where session.id = p_session_id and session.user_id = v_user_id
    and session.status = 'cancelled'
  for update;
  if not found then
    raise exception using errcode = '22023', message = 'Invalid cancellation reason.';
  end if;

  if v_reason is null then
    delete from public.rolling_plan_session_cancellations
    where session_id = p_session_id and user_id = v_user_id;
    return;
  end if;

  insert into public.rolling_plan_session_cancellations (session_id, user_id, reason)
  values (p_session_id, v_user_id, v_reason)
  on conflict (session_id) do update set
    reason = excluded.reason,
    updated_at = pg_catalog.now()
  where public.rolling_plan_session_cancellations.user_id = v_user_id;
end;
$$;


ALTER FUNCTION "public"."set_session_cancellation_reason"("p_session_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_sports"("p_names" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;
  perform 1 from public.profiles where user_id = v_user_id for update;
  if not found then return; end if;

  delete from public.sports as owned
  where owned.user_id = v_user_id
    and not exists (
      select 1 from pg_catalog.unnest(coalesce(p_names, '{}'::text[])) as chosen(raw)
      where pg_catalog.lower(public.tidy_sport_name(chosen.raw))
        = pg_catalog.lower(owned.name)
    );
  perform public.keep_sports(p_names);
end;
$$;


ALTER FUNCTION "public"."set_sports"("p_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_ai_spend"("p_settlement_token" "uuid", "p_charged_micro_usd" bigint) RETURNS "public"."ai_spend_settlement_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_receipt public.ai_spend_settlement_receipt;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if p_settlement_token is null
    or p_charged_micro_usd is null
    or p_charged_micro_usd < 0
    or p_charged_micro_usd > 1000000
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid coaching spend settlement.';
  end if;

  update public.ai_spend_reservations
  set
    charged_micro_usd = p_charged_micro_usd,
    settled_at = pg_catalog.now()
  where user_id = v_user_id
    and settlement_token = p_settlement_token
    and settled_at is null
  returning id, charged_micro_usd
  into v_receipt;

  if not found then
    raise exception using
      errcode = 'PT409',
      message = 'That coaching spend reservation is not open.';
  end if;

  return v_receipt;
end;
$$;


ALTER FUNCTION "public"."settle_ai_spend"("p_settlement_token" "uuid", "p_charged_micro_usd" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sports_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform 1 from public.profiles where user_id = new.user_id for update;

  if (select pg_catalog.count(*) from public.sports where user_id = new.user_id)
    >= 100
  then
    raise exception using errcode = '23514',
      message = 'You have 100 sports, which is the most there can be.';
  end if;

  if new.colour is null then
    -- The swatch fewest of the owner's sports wear, the first of those on a tie.
    select 'sport-' || swatch.n into new.colour
    from pg_catalog.generate_series(1, 12) as swatch(n)
    order by (
      select pg_catalog.count(*) from public.sports as owned
      where owned.user_id = new.user_id
        and owned.colour = 'sport-' || swatch.n
    ), swatch.n
    limit 1;
  end if;

  if new.position is null then
    select coalesce(pg_catalog.max(position) + 1, 0) into new.position
    from public.sports where user_id = new.user_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sports_before_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tidy_sport_name"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select pg_catalog.regexp_replace(pg_catalog.btrim(p_raw), '\s+', ' ', 'g')
$$;


ALTER FUNCTION "public"."tidy_sport_name"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_roadmap"("p_content" "jsonb", "p_expected_head_revision" bigint) RETURNS "public"."roadmap_acceptance_receipt"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_start date;
  v_end date;
  v_head public.roadmap_heads;
  v_replay record;
  v_proposal_id uuid;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'An authenticated FitTip user is required.';
  end if;

  if not exists (
    select 1 from public.profiles where user_id = v_user_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'A FitTip profile is required.';
  end if;

  if p_content is null
    or pg_catalog.jsonb_typeof(p_content) <> 'object'
    or p_expected_head_revision is null
    or p_expected_head_revision < 0
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  begin
    v_start := (p_content->>'startDate')::date;
    v_end := (p_content->>'endDate')::date;
  exception
    when others then
      raise exception using
        errcode = '22023',
        message = 'Invalid roadmap.';
  end;

  if v_start is null
    or v_end is null
    or v_start < (v_now at time zone 'utc')::date - 1
    or v_end < v_start + 27
    or v_end > v_start + 365
    or not public.roadmap_content_is_valid(p_content, v_start, v_end)
  then
    raise exception using
      errcode = '22023',
      message = 'Invalid roadmap.';
  end if;

  perform pg_catalog.set_config('lock_timeout', '3s', true);
  begin
    perform pg_catalog.pg_advisory_xact_lock(
      62005,
      pg_catalog.hashtext(v_user_id::text)
    );
  exception
    when lock_not_available then
      raise exception using
        errcode = 'PT409',
        message = 'Your roadmap changed. Reload and try again.';
  end;

  select * into v_head
  from public.roadmap_heads
  where user_id = v_user_id;

  if coalesce(v_head.revision, 0) <> p_expected_head_revision then
    -- The same roadmap, written by hand, in force one revision on: this
    -- write has already landed.
    select proposal.id as proposal_id, version.id as version_id
    into v_replay
    from public.roadmap_versions version
    join public.roadmap_proposals proposal
      on proposal.id = version.source_proposal_id
      and proposal.user_id = version.user_id
    where version.user_id = v_user_id
      and version.id = v_head.current_version_id
      and v_head.revision = p_expected_head_revision + 1
      and proposal.origin = 'owner_written'
      and proposal.content = p_content;

    if found then
      return (
        v_replay.proposal_id, v_replay.version_id, v_head.revision, 'replayed'
      )::public.roadmap_acceptance_receipt;
    end if;

    raise exception using
      errcode = 'PT409',
      message = 'Your roadmap changed. Reload and try again.';
  end if;

  insert into public.roadmap_proposals (
    user_id, origin, schema_version, content, created_at
  )
  values (
    v_user_id, 'owner_written', p_content->>'schemaVersion', p_content, v_now
  )
  returning id into v_proposal_id;

  -- The advisory lock is the transaction's already, and taking it again is a
  -- no-op. A proposal with no request passes acceptance's lineage check, and
  -- with no sources its source check: what is left is the head, compared
  -- again, and the version, head and decision written as for any proposal.
  return public.accept_roadmap_proposal(v_proposal_id, p_expected_head_revision);
end;
$$;


ALTER FUNCTION "public"."write_roadmap"("p_content" "jsonb", "p_expected_head_revision" bigint) OWNER TO "postgres";

