CREATE TABLE IF NOT EXISTS "public"."ai_spend_reservations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "settlement_token" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "operation" "text" NOT NULL,
    "spend_day" "date" NOT NULL,
    "reserved_micro_usd" bigint NOT NULL,
    "charged_micro_usd" bigint,
    "rate_card_version" "text" NOT NULL,
    "currency" "text" DEFAULT 'USD'::"text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "settled_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_spend_reservations_charged_check" CHECK ((("charged_micro_usd" IS NULL) OR (("charged_micro_usd" >= 0) AND ("charged_micro_usd" <= 1000000)))),
    CONSTRAINT "ai_spend_reservations_currency_check" CHECK (("currency" = 'USD'::"text")),
    CONSTRAINT "ai_spend_reservations_expiry_check" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "ai_spend_reservations_operation_check" CHECK (("operation" = ANY (ARRAY['create_roadmap'::"text", 'create_seven_day_plan'::"text", 'fill_session_activities'::"text"]))),
    CONSTRAINT "ai_spend_reservations_rate_card_check" CHECK ((("char_length"(TRIM(BOTH FROM "rate_card_version")) >= 1) AND ("char_length"(TRIM(BOTH FROM "rate_card_version")) <= 100))),
    CONSTRAINT "ai_spend_reservations_reserved_check" CHECK ((("reserved_micro_usd" >= 1) AND ("reserved_micro_usd" <= 1000000))),
    CONSTRAINT "ai_spend_reservations_settlement_check" CHECK ((("settled_at" IS NULL) = ("charged_micro_usd" IS NULL)))
);


ALTER TABLE "public"."ai_spend_reservations" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."completion_activities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "completion_id" "uuid" NOT NULL,
    "personal_activity_id" "uuid",
    "position" smallint NOT NULL,
    "name" "text" NOT NULL,
    "sport" "text" NOT NULL,
    "instructions" "text",
    "measurement_mode" "text" NOT NULL,
    "actual_measurement" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
